local config = {
  ui_story_5082_50820100_X1_dialog_content = "라인하르트!",
  ui_story_5082_50820100_X2_dialog_content = "흥, 그 「영혼을 불태우는 반역」들은 결국 실패한 거야?\n라인하르트, 넌 결국 「악룡」이 돼버린 거냐고.",
  ui_story_5082_50820100_X3_dialog_content = "족쇄를 벗어버려, 라인하르트... 한때 우리가 그랬던 것처럼.",
  ui_story_5082_50820100_1_dialog_content = "<color=#e8d9bb>화창한 어느 날, 나는 임시 사령부 밖 잔디밭에 누워 하늘을 바라보고 있었다...</color>",
  ui_story_5082_50820100_2_dialog_content = "최신 정보 듣고 싶지 않냥~?",
  ui_story_5082_50820100_3_dialog_content = "으앗...! 필리시! 언제부터 여기 있었어?",
  ui_story_5082_50820100_4_dialog_content = "중요한 건 그게 아니다냥.",
  ui_story_5082_50820100_5_dialog_content = "비비안 참모장님이 전에 필리시에게 시켰던 일 기억하냥?\nPlayerName한테 「어둠의 밑바닥 위험 회피 가이드」 만들어 주는 거 말이다냥.",
  ui_story_5082_50820100_6_dialog_content = "아, 그거? 설마 벌써 다 된 거야?",
  ui_story_5082_50820100_7_dialog_content = "그렇다냥! 꼬박 일주일 동안 생각한 끝에 완성했다냥! 그건 바로──",
  ui_story_5082_50820100_8_dialog_content = "바튼 군단장님한테 이틀 동안 널 데리고 전투 특훈을 해달라고 신청하는 거다냥!",
  ui_story_5082_50820100_9_dialog_content = "하? 전투 특훈? 게다가... 바튼 씨한테?!\n그게 무슨 「어둠의 밑바닥 위험 회피 가이드」야?!",
  ui_story_5082_50820100_10_dialog_content = "필리시도 한참 생각해서 겨우 깨달았다냥. 참모장님은 필리시를 시험하고 있는 거다냥.\n전투는 실전이 중요하단 말씀!",
  ui_story_5082_50820100_11_dialog_content = "그건 그냥 자기 일을 남한테 떠넘긴 거잖아!",
  ui_story_5082_50820100_12_dialog_content = "그리고 내 체력으로 바튼 씨 훈련 같은 걸 받았다간 어둠의 밑바닥에 가기도 전에\n망가져 버릴 거라고.",
  ui_story_5082_50820100_13_dialog_content = "그러니까 더 특훈이 필요한 거다냥.",
  ui_story_5082_50820100_14_dialog_content = "그리고 필리시는 PlayerName의 전투 능력을 알고 있다냥.",
  ui_story_5082_50820100_15_dialog_content = "네 신체 능력을 향상시키면 업무 능률도 분명히 더 좋아질 거다냥!",
  ui_story_5082_50820100_16_dialog_content = "이건 내가 어떻게 하면 훌륭한 보고서를 쉽게 쓸 수 있을지 겨우 생각해 낸 방법이다냥!",
  ui_story_5082_50820100_17_dialog_content = "게으름 피우는 걸 이젠 숨기지도 않는구나...",
  ui_story_5082_50820100_18_dialog_content = "휴, 아무튼 알았으면 설명은 이걸로 끝이다냥. 얼른 같이 일루미나로 돌아가자냥.",
  ui_story_5082_50820100_19_dialog_content = "빨리 가면 낮잠 시간이 생길지도 모른다냥... 흐아암~",
  ui_story_5082_50820100_20_dialog_content = "역시 필리시답다니까. 땡땡이도 정말 당당하게 치네... 아, 잠깐만, 아직 자면 안 돼!",
  ui_story_5082_50820100_21_dialog_content = "일단 훈련 내용부터 말해줘야지──!",
  ui_story_5082_50820100_22_dialog_content = "<color=#e8d9bb>자난성 훈련장</color>",
  ui_story_5082_50820100_23_dialog_content = "낮잠도 안 자고 바로 훈련장으로 데려오다니...",
  ui_story_5082_50820100_24_dialog_content = "미안, 필리시. 널 오해한 것 같아. 너도 진지하게 일할 때가 있었구나.",
  ui_story_5082_50820100_25_dialog_content = "칭찬 고맙다냥~ 그치만 널 꼭 지금 여기 데려온 것도 다 이유가 있다냥.",
  ui_story_5082_50820100_26_dialog_content = "이유?",
  ui_story_5082_50820100_27_dialog_content = "하아... 휴우... 하아...",
  ui_story_5082_50820100_28_dialog_content = "이 느려 터진 자식들! 밥도 안 먹고 나왔냐! 전장에서 암귀 밥이 되고 싶어서 환장한 거냐!",
  ui_story_5082_50820100_29_dialog_content = "가슴을 활짝 펴고! 속도를 높여서 50킬로 더 간다!",
  ui_story_5082_50820100_30_dialog_content = "예!",
  ui_story_5082_50820100_31_dialog_content = "바튼 씨 부대잖아. 다들 훈련하고 있네...",
  ui_story_5082_50820100_32_dialog_content = "바로 지금이다냥! 보고만 있지 말고 따라가라냥!",
  ui_story_5082_50820100_33_dialog_content = "뭐...? 내가?",
  ui_story_5082_50820100_34_dialog_content = "그럼 너 말고 누가 있냥!",
  ui_story_5082_50820100_35_dialog_content = "저건 군단장님이 새로 만드신 훈련소다냥.\n대부분 경험 없는 신병들이니까 PlayerName 너한테도 딱이다냥.",
  ui_story_5082_50820100_36_dialog_content = "캠프 계획에 따라 열심히 훈련하라냥. 필리시는 여기서 낮잠... 아니, 잘 보고 있겠다냥~",
  ui_story_5082_50820100_37_dialog_content = "...아까 칭찬한 거 취소할래!",
  ui_story_5082_50820100_38_dialog_content = "하하, 애송이, 기운이 넘치는군.",
  ui_story_5082_50820100_39_dialog_content = "하지만 어둠의 밑바닥의 적을 쓰러트리려면 여기 훈련으론 부족하지.",
  ui_story_5082_50820100_40_dialog_content = "그 많은 전투를 겪어 온 이상 너도 잘 알고 있겠지만, 전장에선 승리 아니면 죽음뿐이다.",
  ui_story_5082_50820100_41_dialog_content = "적에게 당하기 전에 내가 먼저 널 강하게 만들어 주마. 알겠냐?",
  ui_story_5082_50820100_42_dialog_content = "아, 알겠어요!",
  ui_story_5082_50820100_43_dialog_content = "(바튼 씨 기세에 나도 모르게 대답해 버렸잖아...)",
  ui_story_5082_50820100_44_dialog_content = "좋다.",
  ui_story_5082_50820100_45_dialog_content = "그럼 어떻게 하면 아이테르 애송이를 최대한 빨리 강하게 만들 수 있을지 생각해 보자고.",
  ui_story_5082_50820100_46_dialog_content = "근데 아까 왜 여기 훈련으론 부족하다고 하신 거죠?",
  ui_story_5082_50820100_47_dialog_content = "쳇, 그거야 저 잘난 위원회 놈들이 뭔 과학적인 훈련을 하라고 설치니까 그런 거 아니냐.",
  ui_story_5082_50820100_48_dialog_content = "표준 훈련 모델을 잔뜩 만들어서는 뭐든지 초 단위로 규정에 맞추려고 든다고.",
  ui_story_5082_50820100_49_dialog_content = "훈련이 원래 그런 거 아닌가요?",
  ui_story_5082_50820100_50_dialog_content = "네가 말하는 건 단련이다.",
  ui_story_5082_50820100_51_dialog_content = "하지만 우리가 키우려는 건 그런 틀에 박힌 인형이 아니라, 병사다.\n전선에서 목숨을 걸고 적과 싸우는 전사 말이야!",
  ui_story_5082_50820100_52_dialog_content = "저런 아무 변수도 없는 훈련 따위로는... 흥, 진정으로 우수한 병사는 길러낼 수 없다고.",
  ui_story_5082_50820100_53_dialog_content = "전에 나랑 대원수는 전선에서 작전을 펼치지 않을 땐 자주 실전 연습을 하곤 했다.",
  ui_story_5082_50820100_54_dialog_content = "참가자는 계급에 상관없이 모두가 낯선 환경에서 경쟁을 펼쳤지.",
  ui_story_5082_50820100_55_dialog_content = "주어지는 탄약과 식량 외에 의지할 것은 오직 자신의 몸과 두뇌뿐.",
  ui_story_5082_50820100_56_dialog_content = "높은 자리에 있던 사람이 갑자기 당해버릴 수도 있고,\n이름조차 알려지지 않은 녀석이 끝내 승리할 수도 있지.",
  ui_story_5082_50820100_57_dialog_content = "전투, 사고, 패배, 승리...",
  ui_story_5082_50820100_58_dialog_content = "강자에게 짓밟히는 고통, 무슨 수를 써서라도 이기겠다는 결심...",
  ui_story_5082_50820100_59_dialog_content = "...그런 것들을 직접 체험해야만 자신의 힘으로 삼을 수 있는 거다.",
  ui_story_5082_50820100_60_dialog_content = "오직 끊임없이 변하는 현실 그대로의 훈련에서만 진정한 힘을 기를 수 있단 말이다!",
  ui_story_5082_50820100_61_dialog_content = "그렇지.",
  ui_story_5082_50820100_62_dialog_content = "앗! 라인하르트 씨도 오셨네요!",
  ui_story_5082_50820100_63_dialog_content = "이제 곧 어둠의 밑바닥으로 출발할 테니, 물론 병사들의 상태를 확인하러 와야겠지.\n마침 때맞춰 잘 온 것 같군.",
  ui_story_5082_50820100_64_dialog_content = "바튼, 한동안 대련을 못 했던 것 같은데, 서로 얼마나 강해졌는지 확인해 보는 게 어때?",
  ui_story_5082_50820100_65_dialog_content = "원하던 바다!",
  ui_story_5082_50820100_66_dialog_content = "자, 잠깐만요. 설마...",
  ui_story_5082_50820100_67_dialog_content = "그럼 지금부터 가볍게 실전 연습을 해 볼까.",
  ui_story_5082_50820100_68_dialog_content = "애송이, 이제 와서 도망갈 생각은 말라고!",
  ui_story_5082_50820100_69_dialog_content = "그럴 리가요! 시작도 안 했는데 패배를 인정하는 짓은 안 해요!",
  ui_story_5082_50820100_70_dialog_content = "좋다, 이것도 PlayerName 네 특훈의 일부로 삼을 수 있겠지.\n그렇다면 특훈 책임자도 참가하는 게 당연하다.",
  ui_story_5082_50820100_71_dialog_content = "안 그런가? 필리시 정보부장?",
  ui_story_5082_50820100_72_dialog_content = "그러고 보니까 필리시가 계속 조용했는데... 언제 구석에 가 있었어?!",
  ui_story_5082_50820100_73_dialog_content = "으에~ 대원수님이 그렇게 말씀하신다면야옹.",
  ui_story_5082_50820100_74_dialog_content = "필리시도 참가하겠습니다냥.",
  ui_story_5082_50820100_75_dialog_content = "<color=#e8d9bb>잠시 후</color>",
  ui_story_5082_50820100_76_dialog_content = "여러분, 안녕하세요. 원래 계획엔 없던 일이지만...",
  ui_story_5082_50820100_77_dialog_content = "대원수님의 요청에 따라 제가 이번 연습의 심판을 맡게 됐어요.",
  ui_story_5082_50820100_78_dialog_content = "훈련은 이틀 밤낮에 걸쳐 실시하며, 총 4개 팀이 참가할 거예요.\n각 팀은 2명으로 구성되며, 팀 구성은 명단을 확인해 주세요.",
  ui_story_5082_50820100_79_dialog_content = "1팀은 라인하르트 씨랑 필리시...",
  ui_story_5082_50820100_80_dialog_content = "2팀은 나랑 바튼 씨, 나머지 2팀은 2군단 장교들...",
  ui_story_5082_50820100_81_dialog_content = "근데 어디서 하는 건데요?",
  ui_story_5082_50820100_82_dialog_content = "그거야 간단하지.",
  ui_story_5082_50820100_83_dialog_content = "<color=#e8d9bb>데굴데굴── 데굴── 데구르르르...</color>",
  ui_story_5082_50820100_84_dialog_content = "워게임용 주사위를 늘 가지고 다니는 거냐구요...",
  ui_story_5082_50820100_85_dialog_content = "하하! 좋아, 이 근처의 지하성으로 결정이다.",
  ui_story_5082_50820100_86_dialog_content = "애송이, 운도 좋군. 그 지하성은 오랫동안 버려져 있었는데,\n최근에 내가 훈련장으로 쓰겠다고 신청했거든.",
  ui_story_5082_50820100_87_dialog_content = "거긴 면적도 넓고 폐허가 된 건물이 잔뜩 있지.",
  ui_story_5082_50820100_88_dialog_content = "지형도 우회 잠복 작전을 펼치기 딱 좋다. 물론 상대도 같은 생각을 하겠지만 말이야.",
  ui_story_5082_50820100_89_dialog_content = "연습 장소를 이렇게 대충 정해도 되는 건가요?",
  ui_story_5082_50820100_90_dialog_content = "암귀가 언제는 그런 거 따져가며 습격하는 거 봤냐? 이런 불규칙성 또한 모의전의 일부다. 너도 빨리 적응하는 게 좋을 거다.",
  ui_story_5082_50820100_91_dialog_content = "잠깐만요... 심판은 저예요. 훈련 장소는 심판이 정해야 되지 않겠어요?",
  ui_story_5082_50820100_92_dialog_content = "하하하하, 의욕이 넘쳐서 그만 참모장 일을 빼앗고 말았군. 거 미안하게 됐어!",
  ui_story_5082_50820100_93_dialog_content = "......",
  ui_story_5082_50820100_94_dialog_content = "바튼의 결정대로 하자, 비비안.",
  ui_story_5082_50820100_95_dialog_content = "네, 그럼 준비 시간은 30분이고, 각 팀 모두 30분 후에 입장해 주세요.\n벨소리가 울리면 정식으로 대결이 시작될 거예요.",
  ui_story_5082_50820100_96_dialog_content = "이번 대결은 무척 귀중한 기회니까, 모두 진지하게 임하고 열심히 싸워 주세요.",
  ui_story_5082_50820100_97_dialog_content = "예!",
  ui_story_5082_50820100_98_dialog_content = "(근처의 지하성이라... 관련 기록부도 없네요.\n바튼 군단장은 어떻게 골라도 딱 그런 곳을 고르는지, 휴.)",
  ui_story_5082_50820201_1_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5082_50820201_2_dialog_content = "크하하하! 잘했어! 대원수의 보루를 날려버렸군! 이제 우릴 어떻게 막는지 보자고!",
  ui_story_5082_50820201_3_dialog_content = "콜록... 콜록콜록...",
  ui_story_5082_50820201_4_dialog_content = "연기가 장난이 아닌데요... 콜록콜록...\n이렇게 눈에 띄는 짓을 하면 우리 위치도 분명히 들켰을 거예요.",
  ui_story_5082_50820201_5_dialog_content = "일단 거리를 벌리는 게 좋지 않을까요?",
  ui_story_5082_50820201_6_dialog_content = "그래, 그럼 다음 활약 기회는 다른 녀석들한테 양보해 주자고.",
  ui_story_5082_50820201_7_dialog_content = "PlayerName, 우린 나뉘어서 움직인다. 이 틈에 식량을 최대한 모으는 거다.",
  ui_story_5082_50820201_8_dialog_content = "네!",
  ui_story_5082_50820201_9_dialog_content = "그럼 전 이쪽으로... 어라?",
  ui_story_5082_50820201_10_dialog_content = "(왠지 시선이 느껴지는 것 같은데...)",
  ui_story_5082_50820201_11_dialog_content = "휴... 겨우 만든 보루인데...",
  ui_story_5082_50820201_12_dialog_content = "말도 없이 날려버리다니, 너무하다냥.",
  ui_story_5082_50820201_13_dialog_content = "(벌써 돌아왔단 말이야?!)",
  ui_story_5082_50820201_14_dialog_content = "(그래도 필리시 혼자라면...)",
  ui_story_5082_50820201_15_dialog_content = "필리시! 일단 내 말 좀 들어봐.",
  ui_story_5082_50820201_16_dialog_content = "바튼 씨도 아직 멀리 안 갔어. 여기서 날 공격하면 소리를 듣고 바로 돌아올걸.",
  ui_story_5082_50820201_17_dialog_content = "2대 1이면 불리하잖아?",
  ui_story_5082_50820201_18_dialog_content = "아니면 이런 건 어때? 앞으로 2시간 동안 우린 너희 팀을 공격하지 않을게.",
  ui_story_5082_50820201_19_dialog_content = "그리고 너희랑 같이 다른 두 팀을 견제해 줄 테니까, 그동안 필리시 넌 아무것도 안 해도 돼.",
  ui_story_5082_50820201_20_dialog_content = "으음, 좋은 제안이다냥.",
  ui_story_5082_50820201_21_dialog_content = "그럼──",
  ui_story_5082_50820201_22_dialog_content = "아쉽지만 난 눈앞의 생쥐를 절대 놓아주지 않는다냥!",
  ui_story_5082_50820201_23_dialog_content = "...유미?!",
  ui_story_5082_50820201_24_dialog_content = "이미 늦었다냥!",
  ui_story_5082_50820201_25_dialog_content = "(유미 상대로는 협상은 무리야... 그럼 도망가는 수밖에!)",
  ui_story_5082_50820201_26_dialog_content = "거기 서라냥!",
  ui_story_5082_50820201_27_dialog_content = "이리저리 도망치고 귀찮네! 순순히 잡히라냥!",
  ui_story_5082_50820201_28_dialog_content = "PlayerName! 조금만 버텨라! 지금 바로 간다!",
  ui_story_5082_50820201_29_dialog_content = "...?! 방금 그건...",
  ui_story_5082_50820201_30_dialog_content = "PlayerName! 고개 들어!",
  ui_story_5082_50820201_31_dialog_content = "!!",
  ui_story_5082_50820201_32_dialog_content = "앞쪽은... 라인하르트 씨?! 망했다!",
  ui_story_5082_50820201_33_dialog_content = "일부러 눈에 띄는 곳을 골라 보루를 쌓은 보람이 있었군. 수확이 나쁘지 않아.",
  ui_story_5082_50820201_34_dialog_content = "미안하다, PlayerName. 아쉽지만 네 특훈 시간이 줄어들 게 될 것 같거든.",
  ui_story_5082_50820201_35_dialog_content = "어이! 애송이! 그대로 대원수한테 당해서 퇴장할 셈이냐?!",
  ui_story_5082_50820201_36_dialog_content = "빨리 도망치라고!",
  ui_story_5082_50820201_37_dialog_content = "아무리 빨리 도망쳐 봤자...",
  ui_story_5082_50820201_38_dialog_content = "도망쳐!",
  ui_story_5082_50820201_39_dialog_content = "도망쳐!",
  ui_story_5082_50820201_40_dialog_content = "...누구냐?",
  ui_story_5082_50820201_41_dialog_content = "놈들한테 네 힘을 빼앗기지 마──",
  ui_story_5082_50820201_42_dialog_content = "이 목소리...",
  ui_story_5082_50820201_43_dialog_content = "어서 가!",
  ui_story_5082_50820201_44_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5082_50820201_45_dialog_content = "......!",
  ui_story_5082_50820201_46_dialog_content = "전장에서 우물쭈물하다간 처참한 꼴만 당할 뿐이다!",
  ui_story_5082_50820201_47_dialog_content = "바튼 씨... 으앗!",
  ui_story_5082_50820201_48_dialog_content = "PlayerName 수령 완료!",
  ui_story_5082_50820201_49_dialog_content = "제가 무슨 택배냐구요!",
  ui_story_5082_50820201_50_dialog_content = "이건... 광산차? 이런 건 또 어디서 난 거죠?!",
  ui_story_5082_50820201_51_dialog_content = "이참에 배워둬라. 전장에선 그 어떤 물건이든 다 쓸모가 있는 법이다!",
  ui_story_5082_50820201_52_dialog_content = "그럼 나도 하나 알려주지.",
  ui_story_5082_50820201_53_dialog_content = "전장에선 어떤 수단이든 영원히 유효하진 않는 법이다.",
  ui_story_5082_50820201_54_dialog_content = "라인하르트 씨가 쫓아왔어요!",
  ui_story_5082_50820201_55_dialog_content = "흥, 정신을 딴 데 팔고 있어도 대원수는 대원수라 이거냐.",
  ui_story_5082_50820201_56_dialog_content = "아까는 그저 옛 상처가 잠깐 도졌을 뿐이다. 이제 다음 기회는 없을 거다.",
  ui_story_5082_50820201_57_dialog_content = "쳇, PlayerName! 꽉 잡아라!",
  ui_story_5082_50820201_58_dialog_content = "바튼 익스프레스, 전속력 출격!",
  ui_story_5082_50820201_59_dialog_content = "으아아아아──",
  ui_story_5082_50820201_60_dialog_content = "기왕 택배 취급하는 거 파손 안 되게 살살 좀 다뤄 달라구요!",
  ui_story_5082_50820201_61_dialog_content = "하하하하하!",
  ui_story_5082_50820201_62_dialog_content = "잠깐만요! 앞에! 앞에 벽이잖아요! 막다른 길이라구요!",
  ui_story_5082_50820201_63_dialog_content = "터트려서 돌파하면 그만이지!",
  ui_story_5082_50820201_64_dialog_content = "하아?!",
  ui_story_5082_50820201_65_dialog_content = "너까지 신경 쓸 여유는 없다고! 머리 잘 간수하고 있어!",
  ui_story_5082_50820201_66_dialog_content = "잠깐──",
  ui_story_5082_50820201_67_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5082_50820201_68_dialog_content = "<color=#e8d9bb>펑! 쿵! 콰당!</color>",
  ui_story_5082_50820201_69_dialog_content = "으윽...",
  ui_story_5082_50820201_70_dialog_content = "겨우 멈췄네... 죽는 줄 알았잖아요.",
  ui_story_5082_50820201_71_dialog_content = "뭘 쫄고 그래? 대원수가 강한 건 맞지만, 그래도 내가 널 구해냈잖냐.",
  ui_story_5082_50820201_72_dialog_content = "아니, 바튼 씨... 그거 말고요.",
  ui_story_5082_50820201_73_dialog_content = "으음?",
  ui_story_5082_50820201_74_dialog_content = "앞으로 되도록 운전은 하지 마세요...",
  ui_story_5082_50820201_75_dialog_content = "?",
  ui_story_5082_50820201_76_dialog_content = "그나저나 여긴 어디죠?",
  ui_story_5082_50820201_77_dialog_content = "너무 멀리 와서 방향도 모르겠네요. 일단 근처 상황을 감응해 볼게요.",
  ui_story_5082_50820201_78_dialog_content = "먼 곳보다는 먼저 주변을 둘러봐라.",
  ui_story_5082_50820201_79_dialog_content = "주변이요?",
  ui_story_5082_50820201_80_dialog_content = "웬 상자가 잔뜩... 설마...?!",
  ui_story_5082_50820201_81_dialog_content = "식량이네요!",
  ui_story_5082_50820201_82_dialog_content = "너 설마 내가 정신 놓고 그냥 냅다 달리는 줄 알았던 거냐?",
  ui_story_5082_50820201_83_dialog_content = "전쟁이란 건 말이지, 각각의 전투가 전부 별개의 사건인 게 아냐.",
  ui_story_5082_50820201_84_dialog_content = "더 확실하게 대국을 장악할 수 있는 자가 승리에 더 가까워질 수 있는 거라고.",
  ui_story_5082_50820201_85_dialog_content = "1일 차도 이제 곧 끝날 거다.\n우리가 지금 식량을 손에 넣은 이상, 이 대국에서 가장 유리한 조건을 거머쥔 셈이지.",
  ui_story_5082_50820201_86_dialog_content = "하지만 그 조건을 쥐고 앞장선 자는 동시에 가장 위험한 상황에 빠지게 된다.",
  ui_story_5082_50820201_87_dialog_content = "지금 내 도끼창이 네 머리를 노리고 있는 것처럼 말이야.",
  ui_story_5082_50820201_88_dialog_content = "바튼 씨...!",
  ui_story_5082_50820201_89_dialog_content = "진정해라. 난 아직 패배를 인정할 생각이 없으니까.",
  ui_story_5082_50820201_90_dialog_content = "대원수, 좋은 물건을 가진 놈은 표적이 된다는 것 정도는 학교의 풋내기들도 알고 있다고.",
  ui_story_5082_50820201_91_dialog_content = "내가 먼저 식량을 발견한 이상, 대책도 함께 세우는 게 당연하잖냐.",
  ui_story_5082_50820201_92_dialog_content = "PlayerName한테 기폭장치를 줬다. 누르면 식량 속에 둔 폭탄이 터질 거다.",
  ui_story_5082_50820201_93_dialog_content = "(아? 기, 기폭장치?)",
  ui_story_5082_50820201_94_dialog_content = "너라면 잘 알고 있겠지. 진짜 전장에서 내가 남은 식량을 없애버리는 게 뭘 의미하는지 말이야.",
  ui_story_5082_50820201_95_dialog_content = "훈련은 이틀 밤낮으로 이어질 텐데, 대원수가 부하를 굶주린 채로 싸우게 하진 않겠지?",
  ui_story_5082_50820201_96_dialog_content = "하하, 너와 싸우는 건 이런 느낌이었지. 잊어버릴 뻔했잖아.",
  ui_story_5082_50820201_97_dialog_content = "하지만 설령 굶주린 채라고 해도──",
  ui_story_5082_50820201_98_dialog_content = "(...음? 이건 대체...)",
  ui_story_5082_50820201_99_dialog_content = "(벌써 연습 2일 차야. 이대로라면... 금방 끝나진 않겠어.)",
  ui_story_5082_50820201_100_dialog_content = "(하지만 1일 차에 내가 탄약을 찾은 걸 제외하면, 이틀 동안 만났던 사람들 모두\n식량에 대한 정보는 가지고 있지 않았어.)",
  ui_story_5082_50820201_101_dialog_content = "(이대로는 버티기 힘들지도 몰라...)",
  ui_story_5082_50820201_102_dialog_content = "탄약을 가져간 게 너야?",
  ui_story_5082_50820201_103_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5082_50820201_104_dialog_content = "만나자마자 무기를 들이대다니, 우호적이진 않네.",
  ui_story_5082_50820201_105_dialog_content = "멋대로 남의 거점에 침입하는 행위는 애초에 공격 허가나 다름이 없을 텐데.",
  ui_story_5082_50820201_106_dialog_content = "하하하하, 나랑 힘을 합치는 게 어때? 라인하르트.",
  ui_story_5082_50820201_107_dialog_content = "지금은 실전 연습 중이야. 내가 침입자와 힘을 합쳐야 할 이유가 뭐지?",
  ui_story_5082_50820201_108_dialog_content = "네 공격을 내가 쉽게 막은 것만으로도 이유는 충분하지 않겠어?\n방금 그거 전력을 다한 거 아니었나?",
  ui_story_5082_50820201_109_dialog_content = "물론 그 외에도 유리한 조건은 많아. 예를 들면 식량이라든지.",
  ui_story_5082_50820201_110_dialog_content = "바깥엔 강한 놈들이 아직 잔뜩 있어. 이대로면 언제 승부가 날지 몰라.",
  ui_story_5082_50820201_111_dialog_content = "내가 탄약을 원하는 건 맞아. 하지만 너도 굶주린 채로 싸우고 싶진 않을 거잖아?",
  ui_story_5082_50820201_112_dialog_content = "훗...",
  ui_story_5082_50820201_113_dialog_content = "거래 성립이다.",
  ui_story_5082_50820201_114_dialog_content = "<color=#e8d9bb>이틀 뒤</color>",
  ui_story_5082_50820201_115_dialog_content = "이렇게 빠르게 한 팀을 더 탈락시키다니, 너도 꽤 하잖아.",
  ui_story_5082_50820201_116_dialog_content = "그거야 당연하지.",
  ui_story_5082_50820201_117_dialog_content = "오늘 전투도 곧 끝날 거야. 내가 준 탄약은 잘 썼으니까 이젠 네가 식량을 내놓을 차례...",
  ui_story_5082_50820201_118_dialog_content = "<color=#e8d9bb>퍽!</color>",
  ui_story_5082_50820201_119_dialog_content = "으...",
  ui_story_5082_50820201_120_dialog_content = "(그 녀석... 뒤통수를 칠 줄이야.)",
  ui_story_5082_50820201_121_dialog_content = "(가버렸어... 탄약통도 비어 있고.)",
  ui_story_5082_50820201_122_dialog_content = "(한 방 먹었네... 쓰읍.)",
  ui_story_5082_50820201_123_dialog_content = "(이틀 동안 굶은 데다가 고강도의 전투를 벌여서 몸이 버티기 힘든 모양이야.)",
  ui_story_5082_50820201_124_dialog_content = "(오늘은 여기서 쉴 수밖에 없겠어. 최대한 체력 소모를 줄이고, 내일 다시...)",
  ui_story_5082_50820201_125_dialog_content = "<color=#e8d9bb>또 이틀 뒤</color>",
  ui_story_5082_50820201_126_dialog_content = "(...머리가 어지러워. 몸도 무겁고.)",
  ui_story_5082_50820201_127_dialog_content = "(하지만 싸움은 끝나지 않았어. 반드시 버텨야 해...)",
  ui_story_5082_50820201_128_dialog_content = "(지금은 분노보다는 사고가 필요한 순간이야. 앞으로의 행동과 전략을 생각해야...)",
  ui_story_5082_50820201_129_dialog_content = "호오, 아직도 움직일 수 있었던 거야?",
  ui_story_5082_50820201_130_dialog_content = "내 앞에 다시 나타날 배짱이 있을 줄은 몰랐네.",
  ui_story_5082_50820201_131_dialog_content = "못 할 건 또 뭔데? 내 의도를 간파하지 못한 네가 모자랐을 뿐이잖아?",
  ui_story_5082_50820201_132_dialog_content = "우등생도 그래봤자 그 정도였던 모양이네.",
  ui_story_5082_50820201_133_dialog_content = "지금 상태는 좀 어때? 상처는 아프겠지? 배도 고플 테고 말이야.",
  ui_story_5082_50820201_134_dialog_content = "닥쳐, 날 탈락시키고 싶다면 말로 하지 말고 덤벼.",
  ui_story_5082_50820201_135_dialog_content = "아, 이해했어. 이제 일어설 힘도 없는 거지? 참 불쌍하네.",
  ui_story_5082_50820201_136_dialog_content = "닥치라고 했지!",
  ui_story_5082_50820201_137_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5082_50820201_138_dialog_content = "<color=#e8d9bb>퍼엉──!</color>",
  ui_story_5082_50820201_139_dialog_content = "PlayerName── 피해!",
  ui_story_5082_50820201_140_dialog_content = "바튼 씨!",
  ui_story_5082_50820201_141_dialog_content = "엄청난 공격이다... 역시 식량은 이쪽에 있었어!",
  ui_story_5082_50820201_142_dialog_content = "대원수님이랑 군단장님... 저런 싸움에 정말 우리가 끼어들어도 되겠어?",
  ui_story_5082_50820201_143_dialog_content = "......",
  ui_story_5082_50820201_144_dialog_content = "......!",
  ui_story_5082_50820201_145_dialog_content = "(방금 그건... 내 기억인가?)",
  ui_story_5082_50820201_146_dialog_content = "다른 데 정신 팔고 있는 줄 알았는데... 진심으로 공격하다니.\n그럼 어디 대원수의 격투술이 얼마나 더 강해졌는지 한번 보자고!",
  ui_story_5082_50820301_1_dialog_content = "...함부로 접근 안 해서 다행이야.\n저 수준의 충돌에 맞서는 건 우리로선 목숨이 몇 개라도 부족해.",
  ui_story_5082_50820301_2_dialog_content = "당연하지, 격이 전혀 다르니까. 그런데... 평소에 군단장님이 암귀와 싸우는 걸 볼 땐 못 느꼈는데...",
  ui_story_5082_50820301_3_dialog_content = "방금 대원수님의 공격은 군단장님을 완전히 압도했어.\n그런데도 전혀 다치지 않으셨잖아... 저 몸은 대체...",
  ui_story_5082_50820301_4_dialog_content = "...역시 그것 때문인가, 군단장님이 지금 저 힘을 얻은 건 특수한 신기술 덕분이라는 얘기...",
  ui_story_5082_50820301_5_dialog_content = "게다가 요즘 과학자들이랑 다니던 병사들도 강해졌다고 하고 말이야.\n대체 그런 병사들이 일루미나에 얼마나 있는 거지...?",
  ui_story_5082_50820301_6_dialog_content = "그들한테 불만이 많은 모양이군.",
  ui_story_5082_50820301_7_dialog_content = "당연한 거 아냐? 그 소문이 진짜라면 실험만 받아도 강해질 수 있고,\n진급해서 특수부대에 들어갈 수 있다는 거잖아.",
  ui_story_5082_50820301_8_dialog_content = "근데 그 실험실에서 나오는 게 우리가 알던 그 존재인지 누가 알겠냐고...",
  ui_story_5082_50820301_9_dialog_content = "적어도 난 아직 암귀로 변하진 않았다만.",
  ui_story_5082_50820301_10_dialog_content = "구, 군단장님?!",
  ui_story_5082_50820301_11_dialog_content = "......",
  ui_story_5082_50820301_12_dialog_content = "왜 갑자기 말이 없는 거냐.",
  ui_story_5082_50820301_13_dialog_content = "일루미나든 2군단이든 할 말도 못 하게 하는 곳은 아니잖아?",
  ui_story_5082_50820301_14_dialog_content = "나 같은 군인한테 불만이 있는 거라면 직접 말해라.",
  ui_story_5082_50820301_15_dialog_content = "군단장님께선 그런 사람들과는 다릅니다!",
  ui_story_5082_50820301_16_dialog_content = "저희도 다 들었습니다. 그땐 긴급사태였고...\n군단장님께선 전세를 뒤집기 위해 스스로 실험에 몸을 던지신 거잖습니까!",
  ui_story_5082_50820301_17_dialog_content = "하지만 다른 사람들은...",
  ui_story_5082_50820301_18_dialog_content = "다른 사람들은 전투에 임하지 않는다는 거냐?",
  ui_story_5082_50820301_19_dialog_content = "아닙니다, 하지만...",
  ui_story_5082_50820301_20_dialog_content = "질문에 대답해! 너희가 말하는 그 「다른 사람들」은 전선에서 암귀와 싸우고 있나?!",
  ui_story_5082_50820301_21_dialog_content = "예!",
  ui_story_5082_50820301_22_dialog_content = "그 「다른 사람들」은 너희처럼 밤낮으로 훈련에 힘쓰고 있나?!",
  ui_story_5082_50820301_23_dialog_content = "예...",
  ui_story_5082_50820301_24_dialog_content = "그 「다른 사람들」은 실험에 참가했다는 이유로 자신을 희생하는 일 없이,\n여기서 편안하게 살고 있나?!",
  ui_story_5082_50820301_25_dialog_content = "...아닙니다.",
  ui_story_5082_50820301_26_dialog_content = "그럼 저들도 여전히 너희들의 전우고, 일루미나의 전사다!",
  ui_story_5082_50820301_27_dialog_content = "저들도 너희와 똑같이 땀과 피를 흘리며 싸운다.",
  ui_story_5082_50820301_28_dialog_content = "그리고 너희가 모르는 곳에서 마찬가지로 일루미나의 미래를 위해 희생하고 있다.",
  ui_story_5082_50820301_29_dialog_content = "저들이 나와 뭐가 다르다는 거냐. 저들을 비방하고 싶다면 나한테도 똑같이 해라.",
  ui_story_5082_50820301_30_dialog_content = "하지만 너희가 날 괴물로 여기지 않는다면, 저들 또한 너희들의 동포라는 걸 잊지 마라.",
  ui_story_5082_50820301_31_dialog_content = "......",
  ui_story_5082_50820301_32_dialog_content = "<color=#e8d9bb>휘이익──!</color>",
  ui_story_5082_50820301_33_dialog_content = "<color=#e8d9bb>바튼은 아무도 제대로 볼 수 없을 정도로 빠르게 움직였고,\n그 모습은 마치 은빛 섬광이 스쳐 지나간 것만 같았다.</color>",
  ui_story_5082_50820301_34_dialog_content = "<color=#e8d9bb>그 후, 두 병사의 무기는 반으로 갈라져 바닥에 떨어졌다.</color>",
  ui_story_5082_50820301_35_dialog_content = "너흰 탈락이다.",
  ui_story_5082_50820301_36_dialog_content = "퇴장하고 가서 제대로 반성해라.",
  ui_story_5082_50820301_37_dialog_content = "예...",
  ui_story_5082_50820301_38_dialog_content = "그리고 거기 애송이.",
  ui_story_5082_50820301_39_dialog_content = "녀석들이 수군댄 건 나 같은 「개조인간」인데, 왜 네가 의기소침한 거냐?",
  ui_story_5082_50820301_40_dialog_content = "바튼 씨는 우릴 지키려고 화음 연결 장치의 개조를 받았던 거잖아요...",
  ui_story_5082_50820301_41_dialog_content = "힘도 약한 주제에 생각만 많기는.",
  ui_story_5082_50820301_42_dialog_content = "잘 들어라. 내가 개조를 받았던 건 너흴 지키기 위해서가 아니라, 싸움에서 이기기 위해서였다.",
  ui_story_5082_50820301_43_dialog_content = "그리고 힘을 얻은 건 나다. 너도 아까 내가 대원수의 공격을 피할 때의 속도를 봤을 거잖냐.",
  ui_story_5082_50820301_44_dialog_content = "아직은 제어가 좀 힘들긴 해도, 애초에 힘을 얻으려면 대가가 따르는 법이다.\n불합리한 일도 아니라고.",
  ui_story_5082_50820301_45_dialog_content = "게다가 더 능숙하게 제어하게 되고 나면, 그땐 내가 대원수를 압도할지도 모른다고, 하하하!",
  ui_story_5082_50820301_46_dialog_content = "바튼 씨가 괜찮다면 다행이지만요... 근데 그러고 보니까 라인하르트 씨...",
  ui_story_5082_50820301_47_dialog_content = "오늘 좀 이상해 보였어요. 전투 중에 몇 번이나 다른 생각을 하고 있었잖아요.",
  ui_story_5082_50820301_48_dialog_content = "아까도 그랬어요. 라인하르트 씨가 갑자기 공격을 멈춰서,\n우리도 여기까지 도망칠 수 있었던 거고요.",
  ui_story_5082_50820301_49_dialog_content = "너도 느낀 거냐...\n지금까지 대원수는 전장에서 늘 모두의 중심이 됐었지...",
  ui_story_5082_50820301_50_dialog_content = "그개 전우든, 적이든, 전장의 모든 게 대원수를 중심으로 움직였다.",
  ui_story_5082_50820301_51_dialog_content = "하지만 오늘은 그렇지 않았지. 늘 좋은 타이밍에 나타나는 건 같았지만,\n녀석도 이번엔 상황의 주관자가 아니라 그 속의 일원일 뿐이었다.",
  ui_story_5082_50820301_52_dialog_content = "이건 옛 상처가 도진 정도로 달라질 수 있는 차이가 아니라고.",
  ui_story_5082_50820301_53_dialog_content = "......",
  ui_story_5082_50820301_54_dialog_content = "──",
  ui_story_5082_50820301_55_dialog_content = "크윽...",
  ui_story_5082_50820301_56_dialog_content = "왜 그래?",
  ui_story_5082_50820301_57_dialog_content = "갑자기 뭔가를 감응한 것 같아요...",
  ui_story_5082_50820301_58_dialog_content = "이런 데서?",
  ui_story_5082_50820301_59_dialog_content = "더 깊게 감응해 볼게요!",
  ui_story_5082_50820301_60_option_content = "[감응한다]",
  ui_story_5082_50820301_61_dialog_content = "어디 있지...?",
  ui_story_5082_50820301_62_dialog_content = "<color=#e8d9bb>우르르르...</color>",
  ui_story_5082_50820301_63_dialog_content = "땅이... 흔들리고 있는 건가?",
  ui_story_5082_50820301_64_dialog_content = "방금 감응했던 그 의식... 분명히 낯선데, 연결 방식은 왠지 익숙한 느낌이 들어요.",
  ui_story_5082_50820301_65_dialog_content = "...그 여자입니다.",
  ui_story_5082_50820301_66_dialog_content = "감응했어요!",
  ui_story_5082_50820301_67_dialog_content = "넌 누구야? 왜 여기 있는 거야?!",
  ui_story_5082_50820301_68_dialog_content = "그 여자가...",
  ui_story_5082_50820301_69_dialog_content = "여자? 누구 얘기하는 거야?",
  ui_story_5082_50820301_70_dialog_content = "등 뒤에 용이 있는 그 여자 말입니다!",
  ui_story_5082_50820301_71_dialog_content = "넌 대체...",
  ui_story_5082_50820301_72_dialog_content = "PlayerName! 위험해!",
  ui_story_5082_50820301_73_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5082_50820302_1_dialog_content = "PlayerName, 괜찮냐?!",
  ui_story_5082_50820302_2_dialog_content = "콜록콜록... 괜찮아요. 고마워요, 바튼 씨.",
  ui_story_5082_50820302_3_dialog_content = "근데 왜 갑자기 건물이 무너진 거죠? 전투를 벌인 것도 아닌데...",
  ui_story_5082_50820302_4_dialog_content = "PlayerName, 아래를 봐라.",
  ui_story_5082_50820302_5_dialog_content = "...엄청 큰 공간이네요! 게다가 심하게 파괴된 것 같아요...\n여기서도 전투가 벌어졌던 걸까요?",
  ui_story_5082_50820302_6_dialog_content = "지금까진 연습에 정신이 팔려서 나도 눈치채지 못했다.",
  ui_story_5082_50820302_7_dialog_content = "하지만 여긴 자난성이랑 가까워. 이런 큰 전투가 있었다면 우리가 모를 리가 없다고.",
  ui_story_5082_50820302_8_dialog_content = "아니면 지하성이 무너질 때 이렇게 된 건가...",
  ui_story_5082_50820302_9_dialog_content = "참, 방금 여기서 낯선 의식을 감응했어요!",
  ui_story_5082_50820302_10_dialog_content = "뭔가 이상한 말을 했었는데, 여기서 벌어진 일이랑 관계가 있을지도 몰라요.",
  ui_story_5082_50820302_11_dialog_content = "다시 감응해 볼게요...",
  ui_story_5082_50820302_12_dialog_content = "잠깐만요.",
  ui_story_5082_50820302_13_dialog_content = "...비비안 씨? 라인하르트 씨랑 필리시까지...",
  ui_story_5082_50820302_14_dialog_content = "설마 방금 그 소리 때문에 온 거냐? 하하하, 이미 내가 해결했으니까 괜찮다고.",
  ui_story_5082_50820302_15_dialog_content = "뭐, 기왕 왔으니까. 대원수, 어때? 아까 대결을 계속할 거냐?",
  ui_story_5082_50820302_16_dialog_content = "다음에 하자고.",
  ui_story_5082_50820302_17_dialog_content = "바튼 장군, 대원수님을 곤란하게 만들지 마세요.",
  ui_story_5082_50820302_18_dialog_content = "방금 대원수님과 필리시에게는 전했어요. 전 중요한 소식을 알려 드리려고 온 거예요.",
  ui_story_5082_50820302_19_dialog_content = "뭐지?",
  ui_story_5082_50820302_20_dialog_content = "기록 동기화에 문제가 있었어요. 조금 전 확인해 보니 이 일대는 진입 금지 구역이었어요.",
  ui_story_5082_50820302_21_dialog_content = "게다가 대원수님의 손의 상처도 재발한 이상, 연습을 계속하면 악화될 가능성이 있어요.",
  ui_story_5082_50820302_22_dialog_content = "따라서 아쉽지만 이번 연습은 여기서 마치도록 하죠.",
  ui_story_5082_50820302_23_dialog_content = "근데 아까 감응으로...",
  ui_story_5082_50820302_24_dialog_content = "관련 사항들은 우리가 나중에 처리할게요. 어쨌든 여긴 진입 금지 구역이니까요.\nPlayerName, 이해해 줬으면 좋겠네요.",
  ui_story_5082_50820302_25_dialog_content = "(라인하르트 씨가 굉장히 엄숙한 표정을 하고 있어... 설마 자난성에 무슨 일이 생겼나...?)",
  ui_story_5082_50820302_26_dialog_content = "...알겠어.",
  ui_story_5082_50820302_27_dialog_content = "진짜로 이걸로 끝인 거냐? 난 이제 막 워밍업이 끝났단 말이다!",
  ui_story_5082_50820302_28_dialog_content = "군단에선 맨날 똑같은 훈련만 해서 지겨워 죽겠다고.",
  ui_story_5082_50820302_29_dialog_content = "드디어 실전 연습을 하나 했더니만, 이렇게 용두사미로 끝나다니,\n이런 맥 빠지는 경우가 어디 있어?",
  ui_story_5082_50820302_30_dialog_content = "으음, 연습을 계속할 순 없겠지만, 흥을 깨는 것도 확실히 좋지 않겠지.",
  ui_story_5082_50820302_31_dialog_content = "모처럼 이렇게 모였는데, 이참에 오늘 밤은 캠프파이어나 하자고.",
  ui_story_5082_50820302_32_dialog_content = "바튼, 준비를 맡겨도 될까?",
  ui_story_5082_50820302_33_dialog_content = "...휴, 대원수가 그러자는데 나야 물론 찬성이지! 그럼 지금 바로 부하들 데리고 준비하러 가겠다.",
  ui_story_5082_50820302_34_dialog_content = "그럼 저도 같이...",
  ui_story_5082_50820302_35_dialog_content = "PlayerName, 넌 일단 이리 오라냥.",
  ui_story_5082_50820302_36_dialog_content = "으앗, 필리시, 당기지 마... 그나저나 너 전장에서 나중엔 보이지도 않았잖아?!",
  ui_story_5082_50820302_37_dialog_content = "필리시야 물론 땡땡이친 게 맞다냥... 그치만 여긴 필리시가 모르는 정보가 있었다냥.",
  ui_story_5082_50820302_38_dialog_content = "아까 내가 들었다냥.",
  ui_story_5082_50820302_39_dialog_content = "「저들에게 숨길 생각은 없다. 하지만 아직은 때가 아니다」,\n대원수님이 참모장님한테 그렇게 말했다냥.",
  ui_story_5082_50820302_40_dialog_content = "PlayerName, 얼른 두 사람이 무슨 얘기 중인지 감응 능력으로 알아보라냥.",
  ui_story_5082_50820302_41_dialog_content = "감응 능력은 그렇게 쓰라고 있는 게 아니거든?!",
  ui_story_5082_50820302_42_dialog_content = "우냐앙~ PlayerName 쩨쩨하다냥! 됐다냥. 필리시가 알아서 조사하겠다냥.",
  ui_story_5082_50820302_43_dialog_content = "(그냥 가버렸네... 역시 필리시답다니까.)",
  ui_story_5082_50820302_44_dialog_content = "(그나저나 라인하르트 씨, 몸은 또 무슨 일인 걸까...)",
  ui_story_5082_50820401_1_dialog_content = "<color=#e8d9bb>캠프파이어의 불이 어둑한 밤을 밝혔다...</color>",
  ui_story_5082_50820401_2_dialog_content = "...제게로 오십시오.",
  ui_story_5082_50820401_3_dialog_content = "갑자기 감응이라니... 또 너야?!",
  ui_story_5082_50820401_4_dialog_content = "당신이 절 감응한 것입니다... 아이테르.",
  ui_story_5082_50820401_5_dialog_content = "날 알아? 넌 누구야? 왜 나한테 말을 거는 거야?",
  ui_story_5082_50820401_6_dialog_content = "제가 여길 떠날 수 있도록 도와주십시오.",
  ui_story_5082_50820401_7_dialog_content = "!!!",
  ui_story_5082_50820401_8_dialog_content = "넌... 콜로서스?!",
  ui_story_5082_50820401_9_dialog_content = "저들은 절 「어썰트호」라고 불렀습니다.",
  ui_story_5082_50820401_10_dialog_content = "일루미나가 의식을 지닌 콜로서스를 가지고 있단 말은 들어본 적 없어!",
  ui_story_5082_50820401_11_dialog_content = "...잠깐만, 의식이 있어...? 그럼 네 조종사도 나랑 같은 아이테르였어?",
  ui_story_5082_50820401_12_dialog_content = "&>!#%$^!#$",
  ui_story_5082_50820401_13_dialog_content = "일루미나! 일루미나인은 믿어선 안 됩니다!",
  ui_story_5082_50820401_14_dialog_content = "저들은 절 가두고, 개조해서 자신들의 전쟁 병기로 만들려고 했습니다!",
  ui_story_5082_50820401_15_dialog_content = "전 계속해서 도망치려고 시도했지만, 마지막엔 파괴되고 말았습니다.",
  ui_story_5082_50820401_16_dialog_content = "바로 그 여자가... &>!#%$^!#$... 등 뒤에 $^%$이 있는 여자 때문이었습니다!",
  ui_story_5082_50820401_17_dialog_content = "(여자? 등 뒤가 뭐가 있다는 거야...?)",
  ui_story_5082_50820401_18_dialog_content = "^#!^#%$&습니까? ^&*테르, 절 찾아오십시오.",
  ui_story_5082_50820401_19_dialog_content = "제게로 오십시오.",
  ui_story_5082_50820401_20_dialog_content = "지금 어디 있는데?",
  ui_story_5082_50820401_21_dialog_content = "제게로 와서, 제가 여길 떠날 수 있도록 도와주십시오.",
  ui_story_5082_50820401_22_dialog_content = "잠깐만! 아직 물어보고 싶은 게 있어!",
  ui_story_5082_50820401_23_dialog_content = "아이테르나 헤븐즈 밸리, 스카이워커, 그리고──",
  ui_story_5082_50820401_24_dialog_content = "그럼 절 만나러 오십시오──",
  ui_story_5082_50820401_25_dialog_content = "야!",
  ui_story_5082_50820401_26_dialog_content = "어이, 왜 그래?!",
  ui_story_5082_50820401_27_dialog_content = "방금 그건...",
  ui_story_5082_50820401_28_dialog_content = "하하하! 이젠 꿈에서도 놀라는 거냐? 역시 넌 훈련을 더 강화할 필요가 있다.",
  ui_story_5082_50820401_29_dialog_content = "냐앙~ 아니면 필리시랑 같이 잠 잘 자고, 좋은 꿈 꾸는 연습하겠냥~?",
  ui_story_5082_50820401_30_dialog_content = "방금 그건 꿈이 아니었어요...",
  ui_story_5082_50820401_31_dialog_content = "찾으러 가야겠어요!",
  ui_story_5082_50820401_32_dialog_content = "어이, 어딜 가려는 거야? 우리도 같이 가!",
  ui_story_5082_50820401_33_dialog_content = "하아암~ 대원수님도, 참모장님도 없는 것 같다냥.",
  ui_story_5082_50820401_34_dialog_content = "조금밖에 감응하지 못했지만, 방향은 이쪽이 맞을 거예요.\n마침 어제 연습이 끝났을 때 있던 폐허 쪽 같은데...",
  ui_story_5082_50820401_35_dialog_content = "어? 앞에서 사람 목소리가...",
  ui_story_5082_50820401_36_dialog_content = "PlayerName? 안 돼요. 여긴 진입 금지 구역이라고 말했잖아요.",
  ui_story_5082_50820401_37_dialog_content = "괜찮다, 비비안. 다급하게 달려온 걸 보면 분명히 뭔가 이유가 있는 거겠지.",
  ui_story_5082_50820401_38_dialog_content = "라인하르트 씨, 비비안 씨... 사실...",
  ui_story_5082_50820401_39_dialog_content = "뭐야, 잘도 모여있잖아. 오밤중에 잠도 안 자고 말이야. 뭐야? 연습이라도 다시 시작하려고?",
  ui_story_5082_50820401_40_dialog_content = "필리시는 쉬어야 한다냥. 중요한 정보가 있는 거면 또 모를까냥.",
  ui_story_5082_50820401_41_dialog_content = "전 여기서 콜로서스의 의식을 감응했어요!",
  ui_story_5082_50820401_42_dialog_content = "!",
  ui_story_5082_50820401_43_dialog_content = "...역시 그랬군.",
  ui_story_5082_50820401_44_dialog_content = "어... 설마 그때 그 「예비 조종사」 실험을 했던 기지가 여기였던 거냥?",
  ui_story_5082_50820401_45_dialog_content = "실험 기지...? 설마 그때 폭파됐던 연구소 말이냐?",
  ui_story_5082_50820401_46_dialog_content = "...저도 바이스한테 들은 적 있어요. 자기가 「예비 조종사」 계획에 참여했었다고 말이에요.",
  ui_story_5082_50820401_47_dialog_content = "근데 계획은 왠지 실패한 것 같았고, 바이스도 그때의 기억을 많이 잃었다고 들었고요.",
  ui_story_5082_50820401_48_dialog_content = "설마 그때 일루미나에서 육성하던 게 바로 저 「어썰트호」라는 콜로서스의 조종사였던 건가요?",
  ui_story_5082_50820401_49_dialog_content = "잠깐만... 바이스 걔가 그때 몇 살이나 됐다고 그런 걸 해?",
  ui_story_5082_50820401_50_dialog_content = "너희 말이 맞다. 어둠의 위기 때, 일루미나는 일말의 희망을 걸고 그 실험을 추진했다.",
  ui_story_5082_50820401_51_dialog_content = "하지만 사상자가 발생했고, 기지도 매몰돼 버려서, 그 후의 기록은 얼마 남지 않았다...",
  ui_story_5082_50820401_52_dialog_content = "그 실험은 한때 일루미나의 수치로 여겨졌지.\n하지만 실험에 휘말렸으면서도 후속 조사를 하지 못했던 건 나의 수치다.",
  ui_story_5082_50820401_53_dialog_content = "...라인하르트 씨도 바이스처럼 그 계획에 참여하셨던 건가요?",
  ui_story_5082_50820401_54_dialog_content = "아니, 난 그 계획을 끝장냈다.",
  ui_story_5082_50820401_55_dialog_content = "......",
  ui_story_5082_50820401_56_dialog_content = "사람들은 내가 바이스를 구했다고 말했지만, 사실 나는 그 사건에 대해 기억이 잘 나지 않는다.",
  ui_story_5082_50820401_57_dialog_content = "하지만 어제 바튼과 대결했을 때, 기억이 조금 되살아났다...",
  ui_story_5082_50820401_58_dialog_content = "난 이곳에 아직 숨은 비밀이 있다는 느낌이 들었고, 그래서 확인하러 와야겠다고 생각했지.",
  ui_story_5082_50820401_59_dialog_content = "그리고 방금 PlayerName 넌 내 추측을 증명해 주었다.",
  ui_story_5082_50820401_60_dialog_content = "그 콜로서스는 아직 여기에 있다.",
  ui_story_5082_50820401_61_dialog_content = "──우리 발밑에 말이지.",
  ui_story_5082_50820401_62_dialog_content = "...그게 사실이라면... 전 그 콜로서스를 보러 가고 싶어요.",
  ui_story_5082_50820401_63_dialog_content = "비록 바이스는 그 얘길 꺼내진 않았지만, 잃어버린 기억이 신경 쓰이지 않는 사람은 없을 거예요.",
  ui_story_5082_50820401_64_dialog_content = "전 줄곧 바이스한테 많은 도움을 받았어요.\n그래서 저도 조금이라도 좋으니까 뭔가 해 주고 싶어요.",
  ui_story_5082_50820401_65_dialog_content = "여긴 진입 금지 구역이에요.\n원칙적으로는 PlayerName 당신의 진입을 허용할 수 없어요.",
  ui_story_5082_50820401_66_dialog_content = "하지만...",
  ui_story_5082_50820401_67_dialog_content = "하지만 대원수님이 지금 여기 계시죠.",
  ui_story_5082_50820401_68_dialog_content = "그리고 대원수님은 당신의 진입을 허가할 권한을 가지고 계셔요.",
  ui_story_5082_50820401_69_dialog_content = "나도 확인하러 가려던 참이다. PlayerName 네가 동행하는 걸 반대할 이유도 없지.",
  ui_story_5082_50820401_70_dialog_content = "대신 한 가지만 약속해라.",
  ui_story_5082_50820401_71_dialog_content = "비록 네가 아는 것과는 다르겠지만, 일루미나의 수백 년간의 기록에 의하면──",
  ui_story_5082_50820401_72_dialog_content = "현재까지 발견된 콜로서스 중 공격성을 지닌 콜로서스의 수는 네가 상상하는 것보다 훨씬 많다.",
  ui_story_5082_50820401_73_dialog_content = "네가 감응한 콜로서스도 너와 소통할 때 분명히 일루미나를 좋게 말하진 않았을 거다.",
  ui_story_5082_50820401_74_dialog_content = "...맞아요.",
  ui_story_5082_50820401_75_dialog_content = "엔지니어 사건 이후로, 난 네가 다시는 그 어떤 위험한 대상에 감응하는 일은\n없게 하겠다고 결정했다.",
  ui_story_5082_50820401_76_dialog_content = "특히 그 위험이 일루미나를 향하고 있을 때라면 말이야.",
  ui_story_5082_50820401_77_dialog_content = "하지만 나도 네가 지닌 고유의 능력을 금지하거나 하진 않을 거다.\n그건 남에게 숨을 쉬지 말라는 거나 마찬가지니까.",
  ui_story_5082_50820401_78_dialog_content = "다만 네가 뭘 감응하게 되든, 그게 무엇인지 곧바로 알려줬으면 좋겠다.",
  ui_story_5082_50820401_79_dialog_content = "그럼 저도 하나만 부탁해도 될까요?",
  ui_story_5082_50820401_80_dialog_content = "말해 봐.",
  ui_story_5082_50820401_81_dialog_content = "전 제가 감응한 걸 숨기지 않을 거예요. 대신 여러분도 같은 약속을 지켜줬으면 좋겠어요.",
  ui_story_5082_50820401_82_dialog_content = "몸이 불편해진다거나, 이상한 느낌이 든다거나, 뭐든 좋아요.",
  ui_story_5082_50820401_83_dialog_content = "아주 사소한 느낌이라도 꼭 말해 주세요. 모두 함께 해결할 수 있도록 말이에요.",
  ui_story_5082_50820401_84_dialog_content = "역시 넌 우리가 처음 만났을 때보다 훨씬 성장했군.",
  ui_story_5082_50820401_85_dialog_content = "거래 성립이다.",
  ui_story_5082_50820401_86_dialog_content = "난 평소 이런 일엔 관심이 없었지만, 그때 그 사고는 일루미나에 많은 변화를 불러왔다.\n그러니까 조사할 거라면 날 빼놓고 갈 생각은 말라고.",
  ui_story_5082_50820401_87_dialog_content = "필리시는 별로 참가하고 싶지 않습니다냥.",
  ui_story_5082_50820401_88_dialog_content = "그치만 이 폐허엔 필리시가 알고 싶은 정보가 숨겨져 있습니다냥.\n그러니 이참에 같이 가겠습니다냥.",
  ui_story_5082_50820401_89_dialog_content = "대신 그렇다고 일을 하고 싶은 생각은 없습니다냥.",
  ui_story_5082_50820401_90_dialog_content = "진짜 못 말린다니까...",
  ui_story_5082_50820401_91_dialog_content = "아무튼 그럼 가자고! 내가 먼저 내려갈 테니까 다들 뒤에서 따라와!",
  ui_story_5082_50820401_92_dialog_content = "바튼 씨, 제가 앞에서 길을 찾을게요.\n걱정하지 마세요. 멋대로 콜로서스를 감응하진 않을 테니까요.",
  ui_story_5082_50820401_93_dialog_content = "그냥 주변 모습을 감응하면서 이동하는 게 안전할 것 같거든요.",
  ui_story_5082_50820401_94_dialog_content = "아래 공간이 엄청 넓네요. 근데 전부 폐허라니... 콜록콜록...",
  ui_story_5082_50820401_95_dialog_content = "<color=#e8d9bb>후두둑──</color>",
  ui_story_5082_50820401_96_dialog_content = "으앗! 넘어질 뻔했네...",
  ui_story_5082_50820401_97_dialog_content = "땅에 케이블이 잔뜩 있어요. 다들 조심하세요.",
  ui_story_5082_50820401_98_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_5082_50820401_99_dialog_content = "...무슨 소리지?",
  ui_story_5082_50820401_100_dialog_content = "뭐가 날아온다냥!",
  ui_story_5082_50820401_101_dialog_content = "위이잉──",
  ui_story_5082_50820401_102_dialog_content = "PlayerName! 어서 피해라!",
  ui_story_5082_50820401_103_dialog_content = "──!",
  ui_story_5082_50820401_104_dialog_content = "......",
  ui_story_5082_50820401_105_dialog_content = "PlayerName? PlayerName!",
  ui_story_5082_50820401_106_dialog_content = "방금 누가... 소리를 지른 것 같아요...",
  ui_story_5082_50820501_1_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5082_50820501_2_dialog_content = "...나팔 소리?",
  ui_story_5082_50820501_3_dialog_content = "근데 방금 분명히 여자 비명소리가 들렸는데... 어라?",
  ui_story_5082_50820501_4_dialog_content = "여긴... 사관학교?",
  ui_story_5082_50820501_5_dialog_content = "오오! 또 라인하르트가 이겼어!",
  ui_story_5082_50820501_6_dialog_content = "...라인하르트?",
  ui_story_5082_50820501_7_dialog_content = "또 도전하고 싶은 사람 있어? 언제든지 상대해 줄 테니까.",
  ui_story_5082_50820501_8_dialog_content = "나 참... 전교생을 거의 다 쓰러트렸는데, 누가 또 도전하겠냐고.",
  ui_story_5082_50820501_9_dialog_content = "넌 아직 포기 안 했잖아?",
  ui_story_5082_50820501_10_dialog_content = "고작 팔씨름 같은 사소한 걸로 널 이기고 싶진 않아.",
  ui_story_5082_50820501_11_dialog_content = "교관님이 다음 수업은 장애물 달리기라고 하셨어. 이번엔 절대 안 질 거야.",
  ui_story_5082_50820501_12_dialog_content = "방금 끝난 장애물 달리기, 또 라인하르트가 1등이었어! 2위를 10초 넘게 따돌렸다고!",
  ui_story_5082_50820501_13_dialog_content = "하, 그게 뭐 특별한 일이라고. 라인하르트는 늘 1등이었잖아?",
  ui_story_5082_50820501_14_dialog_content = "그래서 2등은 누군데? 이번에도 레이스겠지?",
  ui_story_5082_50820501_15_dialog_content = "맞아.",
  ui_story_5082_50820501_16_dialog_content = "입학해서 그 둘이랑 동기가 된 뒤로 본 경기마다 1등이랑 2등은 거의 바뀐 적이 없는 것 같아.",
  ui_story_5082_50820501_17_dialog_content = "그 둘을 보고 있으면 내가 쓸모없다는 생각까지 든다니까.",
  ui_story_5082_50820501_18_dialog_content = "쾰른, 보른.",
  ui_story_5082_50820501_19_dialog_content = "내가 잘못 들었나? 방금 라인하르트가 우릴 부른 것 같은데?",
  ui_story_5082_50820501_20_dialog_content = "아니, 나도 들었어.",
  ui_story_5082_50820501_21_dialog_content = "여기야, 내가 불렀어.",
  ui_story_5082_50820501_22_dialog_content = "어, 어째서...",
  ui_story_5082_50820501_23_dialog_content = "라인하르트가 우리 이름을 알고 있지?!",
  ui_story_5082_50820501_24_dialog_content = "너희 반 모의전 때 참관했거든.",
  ui_story_5082_50820501_25_dialog_content = "쾰른, 네 후방 지원의 효율은 전 학년에서도 손꼽히는 수준이야.",
  ui_story_5082_50820501_26_dialog_content = "보른 네 반응 속도도 무척 인상 깊었고.",
  ui_story_5082_50820501_27_dialog_content = "마침 보이길래 인사해 봤어. 기회가 되면 다음엔 꼭 한 팀이 돼 보자.",
  ui_story_5082_50820501_28_dialog_content = "라인하르트! 교관님이 집합하래!",
  ui_story_5082_50820501_29_dialog_content = "그럼 먼저 갈게. 다음에 또 봐.",
  ui_story_5082_50820501_30_dialog_content = "지금... 라인하르트가... 우릴 칭찬한 거야?",
  ui_story_5082_50820501_31_dialog_content = "...우리 가서 구보나 좀 더 할까?",
  ui_story_5082_50820501_32_dialog_content = "지금 당장 가자! 뛰어!",
  ui_story_5082_50820501_33_dialog_content = "전원 집합!",
  ui_story_5082_50820501_34_dialog_content = "지금부터 너희들에게 긴급 임무를 하달하겠다.",
  ui_story_5082_50820501_35_dialog_content = "최근 새로운 유형의 암귀가 38호, 42호, 59호 등 다수의 지하성에 동시에 침입했다.",
  ui_story_5082_50820501_36_dialog_content = "힘은 그리 강하지 않지만, 개체 수가 매우 많고, 게다가 끝없이 늘어나고 있다. 지금은 이미 지하성의 생활 및 생산 활동에 심각한 영향을 미치고 있지.",
  ui_story_5082_50820501_37_dialog_content = "지금부터 너희는 3개 조로 나뉘어 즉시 각 지하성을 지원하도록.",
  ui_story_5082_50820501_38_dialog_content = "예!",
  ui_story_5082_50820501_39_dialog_content = "......",
  ui_story_5082_50820501_40_dialog_content = "<color=#e8d9bb>상황 종료 후</color>",
  ui_story_5082_50820501_41_dialog_content = "라인하르트!",
  ui_story_5082_50820501_42_dialog_content = "내가 너희 부대한테 42호 지하성으로 가라고 하지 않았나? 왜 28호 쪽에 나타난 거지?",
  ui_story_5082_50820501_43_dialog_content = "보고드리겠습니다. 저는 임무를 하달받았을 때 암귀가 침입한 지하성 간의 거리가 상당히 멀다는 점을 발견했습니다.",
  ui_story_5082_50820501_44_dialog_content = "하지만 같은 유형의 암귀가 동시에 침입하고 있었습니다. 그렇다면 세 개의 지하성 사이엔 분명히 모종의 관계가 있을 것이라 생각했습니다.",
  ui_story_5082_50820501_45_dialog_content = "42호 지하성에 도착한 후 암귀와 교전이 발생했습니다만, 제가 보기엔 전혀 문제가 되지 않는 약한 암귀였습니다.",
  ui_story_5082_50820501_46_dialog_content = "하지만 대부분의 인원들이 눈치채지 못했습니다. 그중에는 상당히 빠른 재생력을 가진 암귀가 있었습니다!",
  ui_story_5082_50820501_47_dialog_content = "관찰을 계속한 결과, 그 새로운 암귀는 포자식물과 같은 특성이 있음을 확인했습니다.",
  ui_story_5082_50820501_48_dialog_content = "지도를 보면 암귀가 침입한 지하성은 모두 28호 지하성을 중심으로 펼쳐진\n철도망 상에 위치하고 있었습니다.",
  ui_story_5082_50820501_49_dialog_content = "따라서 저는 이 암귀들이 28호 지하성에 있는 「본체」가 열차를 이용해서 각 지하성에 확산시킨 「포자」라고 생각했습니다.",
  ui_story_5082_50820501_50_dialog_content = "따라서 즉시 28호 지하성으로 향했고, 「본체」를 격파했습니다!",
  ui_story_5082_50820501_51_dialog_content = "본체 소멸 후에는 다른 지하성에 새로운 암귀의 침입 정황이 없는 점도 확인했습니다.",
  ui_story_5082_50820501_52_dialog_content = "...발견하고, 판단하고, 행동했다고?!",
  ui_story_5082_50820501_53_dialog_content = "누가 네 행동을 보고하라고 했나?! 내가 묻는 건 왜 그렇게 했냐는 거다!",
  ui_story_5082_50820501_54_dialog_content = "넌 네 상관들이 전부 머저리고, 너만 진상을 꿰뚫어 보는 현명한 지휘관이라고 생각하나?!",
  ui_story_5082_50820501_55_dialog_content = "도중에 임무를 포기하고 독단적으로 행동했을 뿐만 아니라, 긴급 귀환 명령마저 무시하다니,\n네가 군인이란 사실도 잊은 거냐?!",
  ui_story_5082_50820501_56_dialog_content = "잊지 않았습니다! 처벌은 기꺼이 받겠습니다. 다만 「본체」를 빠르게 제거하는 게 최선책이었다는 생각은 변함이 없습니다.",
  ui_story_5082_50820501_57_dialog_content = "...당장 꺼져!",
  ui_story_5082_50820501_58_dialog_content = "!",
  ui_story_5082_50820501_59_dialog_content = "설마 나 기다린 거야?",
  ui_story_5082_50820501_60_dialog_content = "교관님께 보고드릴 게 있어서 왔을 뿐이야.",
  ui_story_5082_50820501_61_dialog_content = "그건 그렇고... 너 괜찮아?",
  ui_story_5082_50820501_62_dialog_content = "안 괜찮을 건 뭐야. 욕 좀 먹고, 벌도 좀 받으면 되지.",
  ui_story_5082_50820501_63_dialog_content = "교관님이 왜 날 저렇게 싫어하는 건지는 모르겠지만.",
  ui_story_5082_50820501_64_dialog_content = "...그걸 진짜 몰라서 묻는 거야? ...뭐, 됐어.",
  ui_story_5082_50820501_65_dialog_content = "똑같이 지원 병력을 데리고 지하성으로 갔으면서도 난 그 암귀의 문제를 전혀 눈치 못 챘어. 이번엔 네가 이겼다고 인정할게.",
  ui_story_5082_50820501_66_dialog_content = "대신! 다음엔 절대로 지지 않을 거야. 기억해, 라인하르트!",
  ui_story_5082_50820501_67_dialog_content = "어.",
  ui_story_5082_50820501_68_dialog_content = "...뭐가 「어」야? 난 지금 너한테 도전하는 건데, 반응이 그게 다야?",
  ui_story_5082_50820501_69_dialog_content = "도전이야 평소에도 하고 있잖아?",
  ui_story_5082_50820501_70_dialog_content = "그래서 난 네 도전에 늘 만반의 대비를 하고 있어.",
  ui_story_5082_50820501_71_dialog_content = "그...그거야 당연히 그래야지!",
  ui_story_5082_50820501_72_dialog_content = "넌 이 레이스가 인정한 상대야. 내가 널 쓰러트리기 전에 다른 녀석한테 당하지나 마.",
  ui_story_5082_50820501_73_dialog_content = "하하, 노력할게.",
  ui_story_5082_50820501_74_dialog_content = "(이건 과거의 모습이었구나...)",
  ui_story_5082_50820501_75_dialog_content = "(사관학교 시절 레이스와 라인하르트 씨는 누가 봐도 사이가 좋았네, 뭐...)",
  ui_story_5082_50820501_76_dialog_content = "긴급사태입니다──!",
  ui_story_5082_50820501_77_dialog_content = "(장면이... 또 바뀌었어...)",
  ui_story_5082_50820501_78_dialog_content = "으음...?",
  ui_story_5082_50820501_79_dialog_content = "동작 그만──!",
  ui_story_5082_50820501_80_dialog_content = "오늘 훈련은 여기까지다! 전원 대열을 이뤄서 숙소로 돌아가도록! 오늘 밤은 외출 금지다!",
  ui_story_5082_50820501_81_dialog_content = "휴, 겨우 끝났네... 힘들어 죽겠어.",
  ui_story_5082_50820501_82_dialog_content = "근데 오늘은 좀 일찍 끝나지 않았어? 평소 이 시간이면 훈련 프로그램을 다 마쳤어도\n뭘 더 추가하셨을 텐데 말이야.",
  ui_story_5082_50820501_83_dialog_content = "뭘 그런 걸 따지고 있어? 휴식 시간이 많으면 좋은 거 아냐? 라인하르트라도 그렇게 생각할걸?",
  ui_story_5082_50820501_84_dialog_content = "...어? 라인하르트는?",
  ui_story_5082_50820501_85_dialog_content = "야! 어디 가?",
  ui_story_5082_50820501_86_dialog_content = "벌 받을 짓하러.",
  ui_story_5082_50820501_87_dialog_content = "나도 갈래.",
  ui_story_5082_50820501_88_dialog_content = "방금 내 말 못 들었어?",
  ui_story_5082_50820501_89_dialog_content = "내가 바보로 보여?",
  ui_story_5082_50820501_90_dialog_content = "네가 진짜로 그냥 무턱대고 사고나 치는 녀석이었으면,\n네가 아무리 강하든 난 거들떠보지도 않았을 거야.",
  ui_story_5082_50820501_91_dialog_content = "교관님이 대놓고 널 째려보면서 경고했는데도 뛰쳐나오다니, 말해 봐. 대체 무슨 일이야?",
  ui_story_5082_50820501_92_dialog_content = "암귀가 침입했어.",
  ui_story_5082_50820501_93_dialog_content = "뭐?!",
  ui_story_5082_50820501_94_dialog_content = "크오오!",
  ui_story_5082_50820501_95_dialog_content = "군단장님! 암귀가 계속 늘어나고 있습니다! 병력이 부족합니다! 이대로는...",
  ui_story_5082_50820501_96_dialog_content = "안 되면 목숨 걸고 버텨라!",
  ui_story_5082_50820501_97_dialog_content = "이렇게 많은 암귀가... 대체 어디서 튀어나온 거냐.",
  ui_story_5082_50820501_98_dialog_content = "크아아!",
  ui_story_5082_50820501_99_dialog_content = "으악──!",
  ui_story_5082_50820501_100_dialog_content = "버텨라!",
  ui_story_5082_50820501_101_dialog_content = "빌어먹을 놈들!",
  ui_story_5082_50820501_102_dialog_content = "「전부 꿰뚫어라!」",
  ui_story_5082_50820501_103_dialog_content = "「리히트호펜! 돌격!」",
  ui_story_5082_50820501_104_dialog_content = "왜 따라왔어?!",
  ui_story_5082_50820501_105_dialog_content = "말했잖아. 너한텐 안 질 거라고.",
  ui_story_5082_50820501_106_dialog_content = "크어어...",
  ui_story_5082_50820501_107_dialog_content = "훈련생인가?",
  ui_story_5082_50820501_108_dialog_content = "보고드립니다! 일루미나 사관생도 라인하르트, 전투를 지원하겠습니다!",
  ui_story_5082_50820501_109_dialog_content = "일루미나 사관생도 레이스, 저도 함께 싸우겠습니다!",
  ui_story_5082_50820501_110_dialog_content = "멋대로 굴지 말고 돌아가!",
  ui_story_5082_50820501_111_dialog_content = "일이 끝나면 직접 담당 교관에게 보고해서 처벌을 받겠습니다. 하지만 일루미나의 일원으로서 암귀를 눈앞에 두고 도망칠 순 없습니다!",
  ui_story_5082_50820501_112_dialog_content = "좌측 방어선을 제게 맡겨 주십시오.",
  ui_story_5082_50820501_113_dialog_content = "우측 방어선은 제가 맡겠습니다!",
  ui_story_5082_50820501_114_dialog_content = "너희가? 무슨 헛소리냐!",
  ui_story_5082_50820501_115_dialog_content = "반드시 이길 겁니다.",
  ui_story_5082_50820501_116_dialog_content = "게다가 저희 둘이 전부가 아닙니다.",
  ui_story_5082_50820501_117_dialog_content = "1시 방향에서 암귀 두 마리가 땅굴로 기습을 시도하는 중입니다! 그쪽은 제가 맡겠습니다!",
  ui_story_5082_50820501_118_dialog_content = "군단 의무병은 중상자를 맡고, 경상자 응급처치는 저희 쪽에서 할 수 있습니다.",
  ui_story_5082_50820501_119_dialog_content = "이 둘은 제 전우인 보른과 쾰른입니다.",
  ui_story_5082_50820501_120_dialog_content = "라인하르트가 전에 기회가 되면 저희와 함께 싸우고 싶다고 했는데, 마침 오늘 기회가 생겼습니다!",
  ui_story_5082_50820501_121_dialog_content = "군인으로서 일루미나를 지키는 건 모두의 의무입니다. 죄송합니다, 군단장님!",
  ui_story_5082_50820501_122_dialog_content = "하하, 사과는 나중에 드려.",
  ui_story_5082_50820501_123_dialog_content = "지금은 눈앞의 암귀부터 없애는 거다!",
  ui_story_5082_50820501_124_dialog_content = "예!",
  ui_story_5082_50820501_125_dialog_content = "왜 지휘를 네가 맡는 건데?!",
  ui_story_5082_50820501_126_dialog_content = "...라인하르트.",
  ui_story_5082_50820501_127_dialog_content = "<color=#e8d9bb>다음 날</color>",
  ui_story_5082_50820501_128_dialog_content = "전원 집합! 훈련을 개시한다!",
  ui_story_5082_50820501_129_dialog_content = "예!",
  ui_story_5082_50820501_130_dialog_content = "뭐야? 어제 그런 큰 소동이 있었는데, 교관님 진짜로 그냥 넘어가시는 건가?",
  ui_story_5082_50820501_131_dialog_content = "라인하르트랑 레이스도 별일 없는 것 같고, 근데 왠지 모르게 불안하단 말이지...",
  ui_story_5082_50820501_132_dialog_content = "잠깐만, 저기 봐! 저기 1군단장님 아냐?! 왜 군단장님이 직접 오신 거지?",
  ui_story_5082_50820501_133_dialog_content = "라인하르트, 앞으로! 지금 즉시 특수전투훈련실로 가도록.",
  ui_story_5082_50820501_134_dialog_content = "예!",
  ui_story_5082_50820501_135_dialog_content = "......",
  ui_story_5082_50820501_136_dialog_content = "<color=#e8d9bb>제3전투실</color>",
  ui_story_5082_50820501_137_dialog_content = "안녕하십니까!",
  ui_story_5082_50820501_138_dialog_content = "라인하르트, 당신은 탁월한 능력을 가지고 있습니다.\n따라서 우린 당신에게 특별한 훈련 계획을 준비했습니다.",
  ui_story_5082_50820501_139_dialog_content = "크아아!",
  ui_story_5082_50820501_140_dialog_content = "이 실험용 암귀들은 훈련의 일환입니다.",
  ui_story_5082_50820501_141_dialog_content = "잠시 후 놈들을 훈련장에 투입하면, 당신은 전력을 다해 싸워 주세요.",
  ui_story_5082_50820501_142_dialog_content = "후우... 꽤 거친 녀석들이군요.",
  ui_story_5082_50820501_143_dialog_content = "현재 투입하고 있는 건 능력 수준이 가장 낮은 암귀입니다.",
  ui_story_5082_50820501_144_dialog_content = "이 정도 녀석들도 이길 수 없다면, 당신이 최강의 전사가 될 수 있도록 돕는 훈련 계획도\n재검토가 필요하게 될 겁니다.",
  ui_story_5082_50820501_145_dialog_content = "최강의 전사...?! 하... 누가 못 이긴다고 했습니까?!",
  ui_story_5082_50820501_146_dialog_content = "다시 하겠습니다!",
  ui_story_5082_50820502_1_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5082_50820502_2_dialog_content = "뭐야? 이 맥아리 없는 공격은? 전력을 다하라고!",
  ui_story_5082_50820502_3_dialog_content = "하하하, 미안. 다시 하자.",
  ui_story_5082_50820502_4_dialog_content = "너 정말... 아니, 잠깐만. 너 손에 그거 뭐야?! 다쳤어?!",
  ui_story_5082_50820502_5_dialog_content = "설마 어제...",
  ui_story_5082_50820502_6_dialog_content = "라인하르트! 특수전투훈련실로 가라.",
  ui_story_5082_50820502_7_dialog_content = "예.",
  ui_story_5082_50820502_8_dialog_content = "교관님! 라인하르트는 손에 부상을 당해 훈련을 진행할 수 없습니다. 휴식을 허락해 주십시오.",
  ui_story_5082_50820502_9_dialog_content = "라인하르트! 지금 당장 훈련실로 가라.",
  ui_story_5082_50820502_10_dialog_content = "교관님──",
  ui_story_5082_50820502_11_dialog_content = "레이스.",
  ui_story_5082_50820502_12_dialog_content = "교관님, 이 특수 훈련은 얼마나 지속될 예정입니까?",
  ui_story_5082_50820502_13_dialog_content = "명령에 복종하는 것은 군인의 직분이다. 명령을 받았으면 즉각 실행하라!",
  ui_story_5082_50820502_14_dialog_content = "...예.",
  ui_story_5082_50820502_15_dialog_content = "(손...? 설마 라인하르트 씨가 말한 옛 상처가 이때 훈련에서 생긴 건가?)",
  ui_story_5082_50820502_16_dialog_content = "(아무리 특수 훈련이라도 그렇지, 몸 상태도 안 따지고 하면 안 되는 거잖아.)",
  ui_story_5082_50820502_17_dialog_content = "(암귀는 네가 다치든 말든 봐주지 않는다.)",
  ui_story_5082_50820502_18_dialog_content = "(이건... 저 교관의 목소리인가?)",
  ui_story_5082_50820502_19_dialog_content = "(...사관학교엔 매년 꼭 모난 돌이 몇 놈 나오곤 했지.\n하지만 이렇게 명령을 무시하면서까지 나서는 녀석은 처음이다...)",
  ui_story_5082_50820502_20_dialog_content = "(그 기를 꺾어둘 때도 됐어. 그렇게 암귀와 싸우고 싶다면 마음껏 싸우게 해 주마!)",
  ui_story_5082_50820502_21_dialog_content = "(...뭐 저런 인간이 다 있어?!)",
  ui_story_5082_50820502_22_dialog_content = "──!",
  ui_story_5082_50820502_23_dialog_content = "(...또 그 여자 목소리야.)",
  ui_story_5082_50820502_24_dialog_content = "(대체 누구지...?)",
  ui_story_5082_50820502_25_dialog_content = "!",
  ui_story_5082_50820601_1_dialog_content = "으앗!",
  ui_story_5082_50820601_2_dialog_content = "<color=#e8d9bb>쿵──!</color>",
  ui_story_5082_50820601_3_dialog_content = "돌이...",
  ui_story_5082_50820601_4_dialog_content = "어휴, 위험했네! 애송이 너 아니었으면 다들 깔려서 짜부라졌겠어.",
  ui_story_5082_50820601_5_dialog_content = "내가 먼저 길을 살펴볼 테니까 너흰 여기서 기다려라.",
  ui_story_5082_50820601_6_dialog_content = "저도 같이 갈게요.",
  ui_story_5082_50820601_7_dialog_content = "PlayerName, 뭔가 할 말이 있어 보이는군.",
  ui_story_5082_50820601_8_dialog_content = "방금 전 돌을 눈치챈 게 아니에요...",
  ui_story_5082_50820601_9_dialog_content = "전 그냥... 어떤 여자를 감응해서 깜짝 놀랐을 뿐이에요.",
  ui_story_5082_50820601_10_dialog_content = "...붉은 빛을 발산하는 여자인가?",
  ui_story_5082_50820601_11_dialog_content = "어, 어떻게 아셨어요?",
  ui_story_5082_50820601_12_dialog_content = "나도 어제 기억 속에서 봤기 때문이다.",
  ui_story_5082_50820601_13_dialog_content = "......",
  ui_story_5082_50820601_14_dialog_content = "어제부터 하고 싶은 말이 있었던 것 같은데.",
  ui_story_5082_50820601_15_dialog_content = "저만 그런 게 아니에요.",
  ui_story_5082_50820601_16_dialog_content = "바튼 씨, 필리시... 그리고 다들 라인하르트 씨를 걱정하고 있어요.",
  ui_story_5082_50820601_17_dialog_content = "내 상태가 그렇게 이상했나?",
  ui_story_5082_50820601_18_dialog_content = "그렇게 신경 쓸 것 없다, PlayerName. 호의는 고맙게 받도록 하지.",
  ui_story_5082_50820601_19_dialog_content = "하지만 난 감상에 젖어 있을 시간이 없다. 그리고 너라면 딱히 말할 수 없는 일도 아니긴 하지.",
  ui_story_5082_50820601_20_dialog_content = "어제 연습 때 갑자기 전혀 기억에 없던 일이 머릿속에 떠올랐다.",
  ui_story_5082_50820601_21_dialog_content = "낯선 풍경, 낯선 사람들, 그리고 낯선 감정...",
  ui_story_5082_50820601_22_dialog_content = "하지만 아쉽게도 그 기억은 빠르게 스쳐 지나가 버렸지.\n내가 정말로 그 여자애를... 죽인 게 맞는지도 잘 모르겠다.",
  ui_story_5082_50820601_23_dialog_content = "주...죽여요?! 여기 숨은 비밀이 있다고 했던 게 그거였어요?\n설마 그럼 제가 들었던 비명소리가...",
  ui_story_5082_50820601_24_dialog_content = "단편적인 기억뿐이고, 이름도 기억이 나지 않는다.",
  ui_story_5082_50820601_25_dialog_content = "사관학교에서 만났던 사람들은 분명히 전부 기억하고 있는데도 말이야.",
  ui_story_5082_50820601_26_dialog_content = "사관학교? 라인하르트 씨가 학생일 때 모습은 저도 봤지만...",
  ui_story_5082_50820601_27_dialog_content = "그런 여자애는 없었어요.",
  ui_story_5082_50820601_28_dialog_content = "아! 미안해요! 일부러 보려고 한 건 아니에요...",
  ui_story_5082_50820601_29_dialog_content = "괜찮다. 하지만 궁금하군. 어떤 것들이 보였지?",
  ui_story_5082_50820601_30_dialog_content = "음... 훈련장에서 팔씨름하는 것부터 시작해서...\n라인하르트 씨가 명령을 무시하고 지하성의 위기를 해결한 일도 봤어요...",
  ui_story_5082_50820601_31_dialog_content = "그리고 특수한 훈련도요...",
  ui_story_5082_50820601_32_dialog_content = "하하, 그런 일이 있었던 것 같긴 하군.",
  ui_story_5082_50820601_33_dialog_content = "그때는 정말 젊은 혈기가 왕성했지.\n난 내가 뭐든지 해낼 수 있고, 어떤 문제든 해결할 수 있다고 생각했다.",
  ui_story_5082_50820601_34_dialog_content = "하지만 그 과거 속에 정말로 그 여자애가 없었다고 확신하나?",
  ui_story_5082_50820601_35_dialog_content = "으음...",
  ui_story_5082_50820601_36_dialog_content = "그거라면 필리시한테 물어보시라냥! 필리시는 늘 그런 경험을 하고 있잖냥.",
  ui_story_5082_50820601_37_dialog_content = "분명히 같이 겪은 일인데, 다들 유미의 존재를 기억하지 못할 때가 많다냥.",
  ui_story_5082_50820601_38_dialog_content = "아니, 그거랑은 얘기가 좀 다르지 않나...?",
  ui_story_5082_50820601_39_dialog_content = "기억에 대한 건 어쩌면 위원회와 이야기해 볼 필요가 있겠군...\n어쨌든 놈들은 내게 해명해야 할 게 잔뜩 있으니 말이야.",
  ui_story_5082_50820601_40_dialog_content = "어이, 대원수, 와서 좀 봐라. 아까 우릴 덮친 이상한 기계가 대열을 이뤄서 행군하고 있다.",
  ui_story_5082_50820601_41_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_5082_50820601_42_dialog_content = "조금 전에 격추한 1대를 조사했어요. 구조로 보면 일종의 전투 기계인 것 같아요.",
  ui_story_5082_50820601_43_dialog_content = "다만 형태가 무척 특이하고, 왠지 조립이 가능해 보여요.\n여기 있던 실험실에서 개발했던 신형 무기일까요?",
  ui_story_5082_50820601_44_dialog_content = "녀석들의 움직임은 규칙성이 있다. 왠지 전부 폐허의 깊은 곳으로 날아가고 있는 것 같군.",
  ui_story_5082_50820601_45_dialog_content = "따라가자.",
  ui_story_5082_50820601_46_dialog_content = "제가 길을 찾아볼게요.",
  ui_story_5082_50820601_47_option_content = "[감응한다]",
  ui_story_5082_50820601_48_dialog_content = "%^ 힘을 추구하면, $!#$ 파멸할 것입니다... $%^#$#^!$...",
  ui_story_5082_50820601_49_dialog_content = "어썰트호! 근처에 있어? 여기서 있었던 일에 대해 좀 물어...",
  ui_story_5082_50820601_50_dialog_content = "──!",
  ui_story_5082_50820601_51_dialog_content = "그 여자다...!",
  ui_story_5082_50820601_52_option_content = "(강제 감응!)",
  ui_story_5082_50820601_53_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5082_50820601_54_dialog_content = "(또 이 나팔 소리야...)",
  ui_story_5082_50820601_55_dialog_content = "(그리고 왜 저 여자와 감응할 때마다 매번 과거의 장면으로 빠지게 되는 거지?)",
  ui_story_5082_50820601_56_dialog_content = "(아, 라인하르트 씨랑 레이스 씨다.)",
  ui_story_5082_50820601_57_dialog_content = "나팔이 울렸어. 넌 집합하러 가야겠네.",
  ui_story_5082_50820601_58_dialog_content = "넌 또 그 특훈 받으러 가는 거지?",
  ui_story_5082_50820601_59_dialog_content = "그 훈련 정말 규범에 맞는 거야? 아니면 너 하나를 위해 계획된 특훈인 건가?",
  ui_story_5082_50820601_60_dialog_content = "너 요즘 매일 상처투성이가 돼서 돌아오잖아.\n전선에서 싸울 때도 그렇게 많이 다친 건 본 적 없었어.",
  ui_story_5082_50820601_61_dialog_content = "...딱히 널 걱정한 건 아냐. 혹시 누가 일부러 내 도전 상대를 건드리는 건 아닌가 싶을 뿐이야.\n그런 거라면 내가 절대 가만히 안 있을 거니까!",
  ui_story_5082_50820601_62_dialog_content = "괜한 생각이야. 그저 최근 훈련 수준이 높아져서 내가 아직 적응을 못 해서 그런 거야.",
  ui_story_5082_50820601_63_dialog_content = "무의미한 훈련은 없는 법이야. 어떤 훈련이든 그 속에서 경험과 기술을 얻을 수 있어.\n그리고 그 모든 게 내 힘이 되는 거지.",
  ui_story_5082_50820601_64_dialog_content = "라인하르트! 특별 훈련을 받고 있다고 해서 평소 임무를 게을리해도 된다고 생각하나!",
  ui_story_5082_50820601_65_dialog_content = "한심하군, 10바퀴 추가!",
  ui_story_5082_50820601_66_dialog_content = "교관님! 이의 있습니다! 라인하르트는 심하게 지쳤습니다! 휴식이 필요합니다!",
  ui_story_5082_50820601_67_dialog_content = "사관학교 첫 수업에서 배운 게 복종인 것도 벌써 잊어버린 거냐!",
  ui_story_5082_50820601_68_dialog_content = "레이스! 5바퀴 추가!",
  ui_story_5082_50820601_69_dialog_content = "10바퀴 돌겠습니다!",
  ui_story_5082_50820601_70_dialog_content = "같이 뛰어줄 필요 없어.",
  ui_story_5082_50820601_71_dialog_content = "무의미한 훈련은 없다면서? 네가 그랬잖아.",
  ui_story_5082_50820601_72_dialog_content = "뭐, 그럼 고맙다곤 안 할게.",
  ui_story_5082_50820601_73_dialog_content = "애초부터 필요 없었거든?",
  ui_story_5082_50820601_74_dialog_content = "(그 후에도 나는 라인하르트 씨의 반복되는 나날을 지켜봤다.)",
  ui_story_5082_50820601_75_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5082_50820601_76_dialog_content = "<color=#e8d9bb>낮을 알리는 나팔이 울렸다.</color>",
  ui_story_5082_50820601_77_dialog_content = "생도 라인하르트, 훈련 준비를 마쳤습니다!",
  ui_story_5082_50820601_78_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5082_50820601_79_dialog_content = "<color=#e8d9bb>밤을 알리는 나팔이 울렸다.</color>",
  ui_story_5082_50820601_80_dialog_content = "라인하르트! 드디어 왔네. 너 그 손...",
  ui_story_5082_50820601_81_dialog_content = "미안, 조금 힘드네. 먼저 잘게.",
  ui_story_5082_50820601_82_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5082_50820601_83_dialog_content = "라인하르트, 준비됐습니다.",
  ui_story_5082_50820601_84_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5082_50820601_85_dialog_content = "라인하르트──",
  ui_story_5082_50820601_86_dialog_content = "후우... 응? 나 불렀어...?",
  ui_story_5082_50820601_87_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5082_50820601_88_dialog_content = "(라인하르트 씨, 계속 숙소랑 훈련실만 왕복하고 있잖아. 식사도 건조식품만 먹고 있고...)",
  ui_story_5082_50820601_89_dialog_content = "(그저 훈련과 휴식밖에 없는 생활... 전환의 신호는 저 나팔 소리고.)",
  ui_story_5082_50820601_90_dialog_content = "훈련 데이터는 충분히 수집했습니다. 다음은 순발력 훈련으로 넘어가겠습니다.",
  ui_story_5082_50820601_91_dialog_content = "오늘 싸울 상대는 당신의 특성을 바탕으로 특별히 설계한 전투 로봇입니다.",
  ui_story_5082_50820601_92_dialog_content = "전투가 시작되면 자신과 싸우는 느낌이 들 겁니다.",
  ui_story_5082_50820601_93_dialog_content = "전력을 다해 자신의 한계를 넘어서 보세요.",
  ui_story_5082_50820601_94_dialog_content = "네.",
  ui_story_5082_50820602_1_dialog_content = "(...머리가 아파. 이 순발력 훈련, 강도가 꽤 높잖아.)",
  ui_story_5082_50820602_2_dialog_content = "정말 놀랍군요. 조금 전 분명히 활력 징후가 사라졌는데,\n다시 깨어나서 계속 싸울 수 있다니...",
  ui_story_5082_50820602_3_dialog_content = "뭐라고...?",
  ui_story_5082_50820602_4_dialog_content = "데이터 수집은 끝났습니다. 정말 훌륭한 실험체군요.\n획득한 결과도 예상치를 초과했고 말이지요.",
  ui_story_5082_50820602_5_dialog_content = "신체 데이터로 봐서는 소모 수준이 높긴 해도, 전체적으로는 아직 허용 범위 같군요.",
  ui_story_5082_50820602_6_dialog_content = "다음 단계 준비를 시작해도 되겠습니다...",
  ui_story_5082_50820602_7_dialog_content = "질문 하나만 해도 됩니까?",
  ui_story_5082_50820602_8_dialog_content = "아, 그렇지. 오늘 훈련은 끝났습니다. 돌아가도 됩니다.",
  ui_story_5082_50820602_9_dialog_content = "어디 보자... 예측 데이터 계산은...",
  ui_story_5082_50820602_10_dialog_content = "이 특수 훈련, 저 말고도 참가하는 사람이 있습니까?",
  ui_story_5082_50820602_11_dialog_content = "필요한 변수는...",
  ui_story_5082_50820602_12_dialog_content = "......",
  ui_story_5082_50820602_13_dialog_content = "<color=#e8d9bb>비밀 실험실</color>",
  ui_story_5082_50820602_14_dialog_content = "상처 처리는 다 끝났어. 당분간 물에 안 닿게 해.",
  ui_story_5082_50820602_15_dialog_content = "나중에 약을 좀 갖다 줄 테니까, 매일 잘 갈아. 밥도 좀 잘 먹고──",
  ui_story_5082_50820602_16_dialog_content = "아무리 말해봤자 소용없다니까.",
  ui_story_5082_50820602_17_dialog_content = "이 인간은 자기가 하기로 마음먹은 일은 죽어라 매달려서, 네가 뭐라고 하든 안 듣는다고.",
  ui_story_5082_50820602_18_dialog_content = "드니에르...",
  ui_story_5082_50820602_19_dialog_content = "사실이잖아. 우리가 일주일에 한 번 여기서 만나기로 한 것도 그래.",
  ui_story_5082_50820602_20_dialog_content = "마지막으로 만난 뒤로 이미 4주나 지났잖아.",
  ui_story_5082_50820602_21_dialog_content = "간만에 겨우 얼굴 좀 보나 했더니 만신창이 꼴이고,\n실험실에 들어오자마자 자빠져서 잠이나 자고.",
  ui_story_5082_50820602_22_dialog_content = "아까 쓰러지면서 부서진 기자재 잊지 말고 변상해.",
  ui_story_5082_50820602_23_dialog_content = "크흠! 라인하르트, 오해하지 마. 드니에르는 그런 뜻으로 말한 게 아닐 테니까...",
  ui_story_5082_50820602_24_dialog_content = "여긴 가연성 물질이나 폭발물이 많으니까, 함부로 넘어지면 위험해.",
  ui_story_5082_50820602_25_dialog_content = "......",
  ui_story_5082_50820602_26_dialog_content = "미안해, 드니에르. 꽤 오랫동안 약속을 깨버려서 걱정을 끼쳤네.",
  ui_story_5082_50820602_27_dialog_content = "기자재는 내가 책임지고 새로 바꿔줄게.",
  ui_story_5082_50820602_28_dialog_content = "......",
  ui_story_5082_50820602_29_dialog_content = "하하하, 그럼 됐어. 이걸로 해결이네.",
  ui_story_5082_50820602_30_dialog_content = "......",
  ui_story_5082_50820602_31_dialog_content = "그나저나 이 실험실, 우리가 조금씩 지은 거긴 하지만...",
  ui_story_5082_50820602_32_dialog_content = "여기 환기가 너무 안 되지 않나? 드니에르도 여기서 자주 실험을 하게 될 텐데...",
  ui_story_5082_50820602_33_dialog_content = "질식의 위험은 없나?",
  ui_story_5082_50820602_34_dialog_content = "......",
  ui_story_5082_50820602_35_dialog_content = "...라인하르트? 왜 그래?",
  ui_story_5082_50820602_36_dialog_content = "......",
  ui_story_5082_50820602_37_dialog_content = "...음? 나 불렀어?",
  ui_story_5082_50820602_38_dialog_content = "갑자기 훈련 때 생각이 났을 뿐이야. 기묘한 감각을 느꼈거든. 마치 물에 빠진 것 같았어...",
  ui_story_5082_50820602_39_dialog_content = "너 정말 괜찮은 거야?",
  ui_story_5082_50820602_40_dialog_content = "물론이지. 내 회복력은 너희가 더 잘 알잖아.\n상처가 좀 많아 보이긴 해도, 이 정도는 금방 나을 거야.",
  ui_story_5082_50820602_41_dialog_content = "다만 최근엔 훈련이 좀 많아서 시간을 못 냈어. 앞으로는 주의할게.",
  ui_story_5082_50820602_42_dialog_content = "일부러 말 돌리고 있잖아.",
  ui_story_5082_50820602_43_dialog_content = "주의해야 할 건 언니가 아니라 그놈의 훈련이야.",
  ui_story_5082_50820602_44_dialog_content = "자기가 뭘 하고 있는지 제대로 알고 있긴 해?\n훈련의 목적은 한계내에서 자신의 신체 수준을 최대한 끌어올리는 거야.",
  ui_story_5082_50820602_45_dialog_content = "한계에 도전하려고 훈련 대상의 몸 상태는 신경도 안 쓰는 건 정상이 아니라고.",
  ui_story_5082_50820602_46_dialog_content = "이제야 나한테 말을 거는구나.",
  ui_story_5082_50820602_47_dialog_content = "언니 진짜...",
  ui_story_5082_50820602_48_dialog_content = "걱정 마, 나도 그 정도는 알고 있어.",
  ui_story_5082_50820602_49_dialog_content = "어쨌든 난 대원수가 될 사람이니까. 사관학교에서부터 문제가 생겨버리면\n앞으로 어떻게 일루미나를 이끌겠어?",
  ui_story_5082_50820602_50_dialog_content = "그럼 대원수가 되면 잊지 말고 나한테 더 큰 실험실을 지어 줘.",
  ui_story_5082_50820602_51_dialog_content = "전장의 암귀는 보기만 해도 역겨워. 난 연구소에서 제일 대단한 사람이 돼서, 녀석들을 가지고 연구할 거야.",
  ui_story_5082_50820602_52_dialog_content = "난 너희처럼 그런 위대한 뜻은 없어. 좋은 정찰병이 될 수 있으면 그걸로 족해.",
  ui_story_5082_50820602_53_dialog_content = "그게 왜 위대한 뜻이 아닌데?",
  ui_story_5082_50820602_54_dialog_content = "병사 한 사람 한 사람이 모두 일루미나라는 이 거대한 기계를 움직이게 만드는 근본이야.",
  ui_story_5082_50820602_55_dialog_content = "대원수도, 연구원도, 정찰병도 모두 일루미나의 피와 살인 거야.",
  ui_story_5082_50820602_56_dialog_content = "뭐, 모처럼 모였는데 좀 더 즐거운 이야기를 하자고.",
  ui_story_5082_50820602_57_dialog_content = "장차 회고록에 실려 모두가 알게 될 그런 거 말이야.",
  ui_story_5082_50820602_58_dialog_content = "미래의 대원수, 최고의 연구원, 그리고 가장 우수한 정찰병이──",
  ui_story_5082_50820602_59_dialog_content = "최고의 전우라는 이야기처럼.",
  ui_story_5082_50820700_1_dialog_content = "저 로봇들, 우릴 밑으로 유인하려는 건가? 속이 빤히 들여다보이는 수작이잖아!",
  ui_story_5082_50820700_2_dialog_content = "애송이 너, 표정을 보아하니 또 뭔가 감응한 거냐?",
  ui_story_5082_50820700_3_dialog_content = "음... 붉은 빛을 발산하는 여자랑 점점 더 가까워지고 있어요.",
  ui_story_5082_50820700_4_dialog_content = "또 그 여자를 감응한 거냐.",
  ui_story_5082_50820700_5_dialog_content = "그 여자는 늘 귀청이 찢어질 듯한 비명소리와 함께 나타나요.\n하지만 제가 가까이 가려고 할수록 보이는 건...",
  ui_story_5082_50820700_6_dialog_content = "내 과거겠지?",
  ui_story_5082_50820700_7_dialog_content = "맞아요...",
  ui_story_5082_50820700_8_dialog_content = "이번에 보인 건 라인하르트 씨가 특수전투훈련실에서 순발력 훈련을 할 때의 모습이었어요.",
  ui_story_5082_50820700_9_dialog_content = "네가 그런 표정을 하고 있던 게 이해가 되는군.",
  ui_story_5082_50820700_10_dialog_content = "너무... 잔인하다고 생각했거든요.",
  ui_story_5082_50820700_11_dialog_content = "마치 사람으로서의 모든 걸 버리게 하고, 오직 「무기」로서의 기능만\n남기려고 하는 것 같아서요...",
  ui_story_5082_50820700_12_dialog_content = "PlayerName, 넌 상냥한 사람이다.",
  ui_story_5082_50820700_13_dialog_content = "하지만 전쟁이 「잔혹」하다고 말하는 것은 거기에 상냥함이 머무를 자리가 많지 않기 때문이다.",
  ui_story_5082_50820700_14_dialog_content = "네가 어떻게 느끼든, 우린 그 잔인함으로 쌓아 올린 초석을 밟고 나아가야만 한다.",
  ui_story_5082_50820700_15_dialog_content = "당시의 상황에서 난 가장 우수한 최강의 전사가 되고 싶었고,\n그래서 반드시 자신을 단련할 수밖에 없었다.",
  ui_story_5082_50820700_16_dialog_content = "하지만... 불공평하다고 느끼거나, 포기하고 싶거나... 저항하고 싶었던 적은 없었나요?",
  ui_story_5082_50820700_17_dialog_content = "없었을 리가, 물론 많았지.",
  ui_story_5082_50820700_18_dialog_content = "지금은 우리 일루미나의 수뇌부가 그럴싸해 보이겠지만, 우린 예전엔 꽤 골치 아픈 녀석들이었다.",
  ui_story_5082_50820700_19_dialog_content = "대원수, 13호와 19호 지하성, 기억이 나나?",
  ui_story_5082_50820700_20_dialog_content = "......",
  ui_story_5082_50820700_21_dialog_content = "<color=#e8d9bb>서광력 1986년, 일루미나, 자난성</color>",
  ui_story_5082_50820700_22_dialog_content = "군단장님께선 아직 안 돌아오신 건가?",
  ui_story_5082_50820700_23_dialog_content = "예! 소위님, 군단장님께선 대원수의 회의 호출을 받으셨습니다.",
  ui_story_5082_50820700_24_dialog_content = "저희에겐 자리에서 대기하고 함부로 움직이지 말라고 하셨습니다.",
  ui_story_5082_50820700_25_dialog_content = "또 대기라니, 대부분 주둔병으로 파견됐는데... 대체 무슨 일이 벌어지고 있는 거냐...",
  ui_story_5082_50820700_26_dialog_content = "13호와 19호 지하성에 암귀가 침입했어. 통신도 두절됐고, 포위를 돌파한 전령이 지원을 요청했지.",
  ui_story_5082_50820700_27_dialog_content = "...그걸 넌 어떻게 알고 있지?",
  ui_story_5082_50820700_28_dialog_content = "그게 중요한 건 아니잖아? 중요한 건 두 지하성이 위기에 처해 있다는 사실이지.",
  ui_story_5082_50820700_29_dialog_content = "하지만 대원수와 군단장들은 아직도 회의실에서 우유부단하게 굴고만 있어. 이러다간 지하성 두 곳을 암귀한테 갖다 바치게 될 거라고!",
  ui_story_5082_50820700_30_dialog_content = "하지만 군단장님은 대기 명령을 내리셨어.",
  ui_story_5082_50820700_31_dialog_content = "너도 알고 있잖아? 지금 상황에서 「대기」는 「죽게 내버려둬」라는 뜻인 거.",
  ui_story_5082_50820700_32_dialog_content = "......",
  ui_story_5082_50820700_33_dialog_content = "뭐야? 설마 너도 눈을 감고, 귀를 막고, 아무것도 모르는 척할 셈이야?",
  ui_story_5082_50820700_34_dialog_content = "저 높으신 분들처럼 자기 발밑까지 피가 흘러오기 전까진 아무 문제도 없다고,\n그렇게 자신도 속이고, 남도 속일 생각인가?",
  ui_story_5082_50820700_35_dialog_content = "......",
  ui_story_5082_50820700_36_dialog_content = "소위님? 어디 가십니까?",
  ui_story_5082_50820700_37_dialog_content = "잠깐 바깥을 좀 보고 오겠다.",
  ui_story_5082_50820700_38_dialog_content = "<color=#e8d9bb>중앙 회의실의 문이 큰 소리와 함께 열렸고, 분노한 제2군단장 팡고가\n부대대장 바튼을 데리고 나왔다.</color>",
  ui_story_5082_50820700_39_dialog_content = "아무래도 회의가 잘 안 풀린 모양이군요.",
  ui_story_5082_50820700_40_dialog_content = "뭐냐, 1군단 망나니, 흥!",
  ui_story_5082_50820700_41_dialog_content = "잠깐만 시간을 내 주십시오. 전 군령을 전해 드리려고 온 겁니다.",
  ui_story_5082_50820700_42_dialog_content = "「제2군단은 지금 즉시 제1군단 라인하르트 소위의 부대와 함께 출격해 두 지하성을 지원한다.」",
  ui_story_5082_50820700_43_dialog_content = "대충 이런 느낌인데, 어떠십니까?",
  ui_story_5082_50820700_44_dialog_content = "...지금 군령을 조작하겠다는 거냐?!",
  ui_story_5082_50820700_45_dialog_content = "상부에선 지원할 생각이 없다면, 우리가 가서 구하면 됩니다.",
  ui_story_5082_50820700_46_dialog_content = "제가 1군단의 일부 병력을 동원하겠습니다. 자난성 수비는 나머지 병력과 3군단이면 충분합니다.",
  ui_story_5082_50820700_47_dialog_content = "여긴 우리가 있든 없든 안전하겠지만, 저 두 지하성엔 생사가 달린 문제입니다.",
  ui_story_5082_50820700_48_dialog_content = "다만 제 부대만 가지고는 병력이 부족합니다. 따라서 2군단의 지원을 받을 수 있었으면 합니다.",
  ui_story_5082_50820700_49_dialog_content = "그런 짓을 벌이면 어떻게 될지도 물론 알고 있겠지?",
  ui_story_5082_50820700_50_dialog_content = "마음 써 주셔서 감사합니다. 하지만 전 사람들을 구하는 게 더 중요하다고 생각합니다.",
  ui_story_5082_50820700_51_dialog_content = "...일개 소위가 어디서 그런 용기가 생긴 거냐.",
  ui_story_5082_50820700_52_dialog_content = "팡고 군단장님과 제1군단이라면 전우를 버리지 않을 거라고 믿기 때문입니다.",
  ui_story_5082_50820700_53_dialog_content = "군단장님, 아직도 망설이시는 겁니까? 전 라인하르트와 갈 겁니다.",
  ui_story_5082_50820700_54_dialog_content = "지금까진 무모하기만 했는데, 이젠 군령 조작이라니,\n라인하르트, 너 정말 간이 배 밖으로 나왔구나.",
  ui_story_5082_50820700_55_dialog_content = "그 말 하려고 여기까지 따라온 거야?",
  ui_story_5082_50820700_56_dialog_content = "네 그 말도 안 되는 야심을 내가 그냥 놔둘 것 같아?",
  ui_story_5082_50820700_57_dialog_content = "재밌군... 저들에게 불만이 있는 게 우리 둘만은 아니었던 모양이지?\n좋아, 그럼 이제부터 우리가 받을 명령은 우리가 내리자고!",
  ui_story_5082_50820700_58_dialog_content = "그런 일도 있었군요... 뭐, 확실히 라인하르트 씨 스타일이긴 하네요.",
  ui_story_5082_50820700_59_dialog_content = "하지만 안타깝게도 우린 한발 늦었다.",
  ui_story_5082_50820700_60_dialog_content = "13호 지하성은 거의 전멸했고, 19호도 겨우 구해낸 수준이었지.",
  ui_story_5082_50820700_61_dialog_content = "그래도 우린 그들을 구했잖냐... 그 뒤로 난리가 나서 위원회한테 찍히게 됐지만 말이야.",
  ui_story_5082_50820700_62_dialog_content = "뭐, 그때 일 덕에 우린 「반역」죄를 면했고, 나랑 레이스도 대대장으로 진급했으니\n수지는 맞은 거 아니겠어?",
  ui_story_5082_50820700_63_dialog_content = "군에서는 그런 이해타산 같은 건 없다.",
  ui_story_5082_50820700_64_dialog_content = "팡고 군단장은 애초부터 널 후임자로 키우고 있었다.\n그리고 그 건을 계기로 계획이 조금 더 앞당겨졌을 뿐이지.",
  ui_story_5082_50820700_65_dialog_content = "하지만 그땐 너도 아직 젊었고, 공적도 부족했으니 고생도 꽤 많았겠지.",
  ui_story_5082_50820700_66_dialog_content = "제일 고생한 건 너잖아? 독단 행동에 군령 조작까지 저질렀으니,\n그때 1군단장 뚜껑이 열리는 것도 당연하지.",
  ui_story_5082_50820700_67_dialog_content = "결국 일반병으로 강등하고 권한까지 다 박탈해서,\n말단 부대에서 다시 훈련을 받게 만들었고 말이야.",
  ui_story_5082_50820700_68_dialog_content = "하하, 그래도 네가 상부를 들이받았을 때...",
  ui_story_5082_50820700_69_dialog_content = "그 많은 사람들이 같이 「여명의 빛을 위하여」라고 외치던 모습은\n지금 생각해도 온몸의 피가 끓어오른다고!",
  ui_story_5082_50820700_70_dialog_content = "......?",
  ui_story_5082_50820700_71_dialog_content = "잠깐... 상부를 들이받았다는 그 얘기...",
  ui_story_5082_50820700_72_dialog_content = "<color=#e8d9bb>서광력 1986년, 일루미나, 자난성</color>",
  ui_story_5082_50820700_73_dialog_content = "어이, 라인하르트! 이쪽 훈련도구들 먼지가 잔뜩이잖아? 제대로 청소한 거 맞아?",
  ui_story_5082_50820700_74_dialog_content = "미안하다. 다시 하지.",
  ui_story_5082_50820700_75_dialog_content = "우리 주전자 물도 얼른 가서 채워 와.",
  ui_story_5082_50820700_76_dialog_content = "알겠다.",
  ui_story_5082_50820700_77_dialog_content = "크흠... 우리 이러는 거 좀 심한 거 아냐...?",
  ui_story_5082_50820700_78_dialog_content = "무슨 소리야? 전공을 세우려고 군령까지 조작한 녀석인데, 뭘 동정하고 있어?",
  ui_story_5082_50820700_79_dialog_content = "게다가 군단장님도 그러셨고...",
  ui_story_5082_50820700_80_dialog_content = "저 망할 놈들, 더는 못 참아!",
  ui_story_5082_50820700_81_dialog_content = "멈춰, 쾰른. 별일 아니니까 신경 쓰지 마. 규칙을 위반한 건 사실이니까 벌을 받아야지.",
  ui_story_5082_50820700_82_dialog_content = "날 감싸다가 연루되기라도 하면 그게 더 손해야.",
  ui_story_5082_50820700_83_dialog_content = "연루라니 무슨 말이 그래?! 우린 모든 걸 알고도 스스로 따라간 거라고!",
  ui_story_5082_50820700_84_dialog_content = "가서 군단장님한테 말해야겠어. 너 혼자 처벌을 받는 건 부당해!",
  ui_story_5082_50820700_85_dialog_content = "어, 저거 2군단 애들 아냐? 오늘 설마 쟤들이랑 훈련장 같이 쓰는 건가?",
  ui_story_5082_50820700_86_dialog_content = "뭐야? 재수 없게.",
  ui_story_5082_50820700_87_dialog_content = "맨 앞에 있는 사람, 그 신임 대대장이네. 소문으로는 라인하르트랑 똑같은 놈이라더만.",
  ui_story_5082_50820700_88_dialog_content = "맞아! 저놈들이 장비 구역을 습격했어! 공을 세워서 진급하려고 다른 사람들을 해친 놈들이라고.",
  ui_story_5082_50820700_89_dialog_content = "근데 19호 지하성을 구한 것도 쟤들이라던데... 사람들을 해쳤다는 그 소문, 진짜 맞아?",
  ui_story_5082_50820700_90_dialog_content = "헛소문이었으면 대원수님이 진작에 누명을 풀어 주셨겠지.\n우리 귀에까지 들어올 정도면 진짜일 가능성이 높지 않겠어?",
  ui_story_5082_50820700_91_dialog_content = "군단장님, 부하들 사이에서 소문이 점점 더 심하게 퍼지고 있습니다. 제재하지 않아도 되겠습니까?",
  ui_story_5082_50820700_92_dialog_content = "됐다. 일을 벌였으면 그 결과도 자기들이 감당해야지.",
  ui_story_5082_50820700_93_dialog_content = "2군단의 신예가 설마 저런 사람일 줄이야...",
  ui_story_5082_50820700_94_dialog_content = "팡고 님께서 직접 발탁했다고 들었는데, 아무래도...",
  ui_story_5082_50820700_95_dialog_content = "......",
  ui_story_5082_50820700_96_dialog_content = "대대장님! 1군단 놈들이 뭐라고 지껄이는지 들으셨습니까? 너무 심한 거 아닙니까?!",
  ui_story_5082_50820700_97_dialog_content = "앞에 보고 걸어라.",
  ui_story_5082_50820700_98_dialog_content = "......",
  ui_story_5082_50820700_99_dialog_content = "뭐 하자는 거야?",
  ui_story_5082_50820700_100_dialog_content = "그냥 그렇게 보고만 있을 생각이야?",
  ui_story_5082_50820700_101_dialog_content = "이 모든 게 불합리하고 불공평하다는 사실조차 모른다는 듯이 굴 작정이냐고.",
  ui_story_5082_50820700_102_dialog_content = "......",
  ui_story_5082_50820700_103_dialog_content = "......흥!",
  ui_story_5082_50820700_104_dialog_content = "바튼!",
  ui_story_5082_50820700_105_dialog_content = "우린 틀리지 않았어!",
  ui_story_5082_50820700_106_dialog_content = "?",
  ui_story_5082_50820700_107_dialog_content = "<color=#e8d9bb>주변이 순식간에 조용해졌다. 그녀는 가슴을 펴고 힘찬 발걸음으로 훈련장 중앙에 섰다.</color>",
  ui_story_5082_50820700_108_dialog_content = "너희들은 전부 길들여진 멍청한 쓰레기들이다.",
  ui_story_5082_50820700_109_dialog_content = "잘못을 저지른 건 너희들이잖아!",
  ui_story_5082_50820700_110_dialog_content = "버림받은 전우들을 구한 게 잘못이냐?",
  ui_story_5082_50820700_111_dialog_content = "아니면, 버림받은 시민들을 구한 게 잘못이라는 거냐?",
  ui_story_5082_50820700_112_dialog_content = "......",
  ui_story_5082_50820700_113_dialog_content = "왜 너흰 자기 머리로 생각이란 걸 안 하는 거지?\n아니면 이미 스스로 생각할 능력조차 없어진 건가?",
  ui_story_5082_50820700_114_dialog_content = "우린 암귀와 싸웠고, 등 뒤의 동포들을 지켰어.",
  ui_story_5082_50820700_115_dialog_content = "하지만 어떤 사람들은 자기들이 감히 하지 못하는 일을 해냈다고 우릴 꼴 보기 싫어하지.",
  ui_story_5082_50820700_116_dialog_content = "그리고 너희의 행동 규범엔 오직 「복종」이란 단어밖에 남지 않았고 말이야.",
  ui_story_5082_50820700_117_dialog_content = "결국 명령 하나, 심지어 명령도 아닌 암시 하나 가지고,\n너흰 생사를 함께해 온 동료들에게 칼날을 돌리겠다는 거냐?!",
  ui_story_5082_50820700_118_dialog_content = "......",
  ui_story_5082_50820700_119_dialog_content = "다시 한번 말한다.",
  ui_story_5082_50820700_120_dialog_content = "우린 틀리지 않았어.",
  ui_story_5082_50820700_121_dialog_content = "설령 또 같은 일이 있더라도, 우린 같은 선택을 할 거다.",
  ui_story_5082_50820700_122_dialog_content = "그건 그때 궁지에 몰리는 게 너희일 수도, 나일 수도 있으니까.",
  ui_story_5082_50820700_123_dialog_content = "그 누구도 우리의 동포를 구할 시도조차 하지 않고 저버릴 자격은 없어!",
  ui_story_5082_50820700_124_dialog_content = "마지막으로 다시 한번 말한다.",
  ui_story_5082_50820700_125_dialog_content = "우린 명령을 어겼다. 하지만──!",
  ui_story_5082_50820700_126_dialog_content = "우린 틀리지 않았어!",
  ui_story_5082_50820700_127_dialog_content = "......",
  ui_story_5082_50820700_128_dialog_content = "바튼, 넌 어떻게 생각하지?",
  ui_story_5082_50820700_129_dialog_content = "흥.",
  ui_story_5082_50820700_130_dialog_content = "<color=#e8d9bb>바튼은 아무 말도 하지 않았고, 성큼성큼 인파를 지나 텅 빈 훈련장 중앙에서 사람들을 향해 섰다.</color>",
  ui_story_5082_50820700_131_dialog_content = "난 너처럼 말을 잘하진 못하지만, 적어도 이럴 때일수록\n긴말이 필요 없다는 것 정도는 알고 있어.",
  ui_story_5082_50820700_132_dialog_content = "<color=#e8d9bb>바튼은 가슴을 펴고 소리쳤다.</color>",
  ui_story_5082_50820700_133_dialog_content = "여명의 빛을 위하여!",
  ui_story_5082_50820700_134_dialog_content = "훗, 잘만 말하면서 못한다고 하기는.",
  ui_story_5082_50820700_135_dialog_content = "<color=#e8d9bb>그녀는 심호흡을 한 번 하더니, 똑같이 힘찬 목소리로 외쳤다.</color>",
  ui_story_5082_50820700_136_dialog_content = "여명의 빛을 위하여!",
  ui_story_5082_50820700_137_dialog_content = "<color=#e8d9bb>병사들은 서로를 돌아봤고, 설령 하늘이 무너지더라도 단 한 걸음도\n물러서지 않을 것 같은 두 사람을 어쩔 줄 모르는 표정으로 바라봤다.</color>",
  ui_story_5082_50820700_138_dialog_content = "<color=#e8d9bb>그러나 그들이 정신을 차릴 새도 없이, 인파 속에서 두 사람이 더 걸어 나왔다.</color>",
  ui_story_5082_50820700_139_dialog_content = "여명의 빛을 위하여!",
  ui_story_5082_50820700_140_dialog_content = "<color=#e8d9bb>그리고 한때 그들과 싸웠던 사람들도 앞으로 나섰다.</color>",
  ui_story_5082_50820700_141_dialog_content = "여명의 빛을 위하여!",
  ui_story_5082_50820700_142_dialog_content = "<color=#e8d9bb>그 후 점점 더 많은 사람들이 앞으로 걸어 나오기 시작했다.</color>",
  ui_story_5082_50820700_143_dialog_content = "여명의 빛을 위하여!",
  ui_story_5082_50820700_144_dialog_content = "<color=#e8d9bb>한때 둘로 갈라져 있던 무리의 틈은 몰려오는 병사들로 메워졌다.</color>",
  ui_story_5082_50820700_145_dialog_content = "<color=#e8d9bb>함께 싸웠던 사람, 그렇지 않은 사람.</color>",
  ui_story_5082_50820700_146_dialog_content = "<color=#e8d9bb>서로를 아는 사람, 그렇지 않은 사람.</color>",
  ui_story_5082_50820700_147_dialog_content = "<color=#e8d9bb>모든 병사들이 앞으로 나섰다.</color>",
  ui_story_5082_50820700_148_dialog_content = "여명의 빛을 위하여!",
  ui_story_5082_50820700_149_dialog_content = "여명의 빛을 위하여──!",
  ui_story_5082_50820700_150_dialog_content = "군단장님, 어떡합니까? 이러다간 통제가 안 될 겁니다.",
  ui_story_5082_50820700_151_dialog_content = "...오히려 녀석을 영웅으로 만들어 버리고 말았군.",
  ui_story_5082_50820700_152_dialog_content = "정숙해라──!",
  ui_story_5082_50820700_153_dialog_content = "......",
  ui_story_5082_50820700_154_dialog_content = "바튼 대대장, 팡고가 자네를 중용하고 있다곤 해도, 그건 2군단 내부의 사정이다.\n자네가 우리 1군단의 훈련을 방해하는 일은 없었으면 좋겠군.",
  ui_story_5082_50820700_155_dialog_content = "1군단 전원은 들어라! 너희는 모두 규율을 위반했다!\n오늘 밤까지 자난성의 모든 훈련장을 깨끗하게 청소하도록!",
  ui_story_5082_50820700_156_dialog_content = "불합리한 체벌입니다!",
  ui_story_5082_50820700_157_dialog_content = "명령에 복종해──!",
  ui_story_5082_50820700_158_dialog_content = "청소가 끝나는 대로 전군 정비를 실시한다. 그 어떤 군사 활동에도 참가하는 것을 금지한다!",
  ui_story_5082_50820801_1_dialog_content = "그러고 보면... 줏대 없는 녀석 대신 그 애가 나서서 그런 말을 했던 것도 같군.",
  ui_story_5082_50820801_2_dialog_content = "잠깐만, 그게 뭔 소리야?",
  ui_story_5082_50820801_3_dialog_content = "어디 빨간 옷 입은 애가 또 있었다는 거야?",
  ui_story_5082_50820801_4_dialog_content = "그때 일은 평생 못 잊을 거다. 그건 다 네가 네 입으로 직접 했던 말이잖냐!",
  ui_story_5082_50820801_5_dialog_content = "...내가?",
  ui_story_5082_50820801_6_dialog_content = "실험실 폭발 때문에 기억이라도 잃은 거냐? 너랑 그 오랜 시간을 알고 지냈지만,\n네가 말한 그런 녀석은 한 번도 본 적 없다고.",
  ui_story_5082_50820801_7_dialog_content = "...하지만 이 기억들은 기지 안으로 들어갈수록 계속해서 떠오르고 있다... 이건 거짓이 아냐.",
  ui_story_5082_50820801_8_dialog_content = "<color=#e8d9bb>쿵.</color>",
  ui_story_5082_50820801_9_dialog_content = "으, 아파라...",
  ui_story_5082_50820801_10_dialog_content = "잘 보고 걸으라냥. 여긴 낡은 케이블이랑 기계가 잔뜩이라 조심 안 하면 넘어질 거다냥.",
  ui_story_5082_50820801_11_dialog_content = "자, 날 따라하라냥. 다음에 또 넘어질 것 같으면 이렇게 앞으로 폴짝 뛰고, 그다음에...",
  ui_story_5082_50820801_12_dialog_content = "고마워, 필리시. 근데 난 그런 고양이 동작은 무리야...",
  ui_story_5082_50820801_13_dialog_content = "그나저나 방금 내 발에 걸린 거... 왠지 머리에 쓰는 물건 같지 않아?",
  ui_story_5082_50820801_14_dialog_content = "냐앙! 필리시 이거 본 적 있다냥~",
  ui_story_5082_50820801_15_dialog_content = "찬드라 선생님이 옛날에 이걸로 나랑 유미를 치료해 줬다냥. 엄청 귀한 거라고 했다냥.",
  ui_story_5082_50820801_16_dialog_content = "수량이 적어서 예전에는 엘리트 인재 육성에만 사용했다고 들었다냥.",
  ui_story_5082_50820801_17_dialog_content = "여기도 한 대 있네요. 파손이 심하긴 하지만, 원래 구조를 파악하기엔 충분해 보여요.",
  ui_story_5082_50820801_18_dialog_content = "어디 보자...",
  ui_story_5082_50820801_19_dialog_content = "잠깐 기다려...",
  ui_story_5082_50820801_20_dialog_content = "<color=#e8d9bb>일행이 아직 장치의 대략적인 형상밖에 파악하지 못한 상황이었지만,\n세 번째 1대는 바튼의 발아래 산산조각이 나고 말았다.</color>",
  ui_story_5082_50820801_21_dialog_content = "...아무리 봐도 이런 걸로 엘리트 인재를 육성하진 못할 것 같은데 말이야.",
  ui_story_5082_50820801_22_dialog_content = "이게 정말 그렇게 귀한 거야? 여기만 해도 3대나 있잖아.",
  ui_story_5082_50820801_23_dialog_content = "이 1대는 그나마 형태가 온전하긴 한데, 대신 여기저기 녹이 슬었어... 어라?",
  ui_story_5082_50820801_24_dialog_content = "이건...",
  ui_story_5082_50820801_25_dialog_content = "...뭔가 살아있는 게 꿈틀거리는 느낌이 들어요.",
  ui_story_5082_50820801_26_dialog_content = "!",
  ui_story_5082_50820801_27_dialog_content = "으윽...",
  ui_story_5082_50820801_28_dialog_content = "라인하르트 씨?!",
  ui_story_5082_50820801_29_option_content = "(강제 감응!)",
  ui_story_5082_50820801_30_dialog_content = "......",
  ui_story_5082_50820801_31_dialog_content = "활력 징후가 사라졌어요...",
  ui_story_5082_50820801_32_dialog_content = "<color=#e8d9bb>보글보글...</color>",
  ui_story_5082_50820801_33_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5082_50820801_34_dialog_content = "나팔이 울렸어... 훈련하러... 가야 해.",
  ui_story_5082_50820801_35_dialog_content = "크아아!",
  ui_story_5082_50820801_36_dialog_content = "대원수님!",
  ui_story_5082_50820801_37_dialog_content = "이 장치... 본 적 있다... 나도 써 본 적 있다고...",
  ui_story_5082_50820801_38_dialog_content = "하지만... 대체 왜...",
  ui_story_5082_50820801_39_dialog_content = "대원수, 너 괜찮은 거냐?!",
  ui_story_5082_50820801_40_dialog_content = "PlayerName, 어서 그 장치를 치워 주세요!",
  ui_story_5082_50820801_41_dialog_content = "잠깐만요, 방금 그 의식... 라인하르트 씨, 뭔가 생각난 게 있나요?",
  ui_story_5082_50820801_42_dialog_content = "확실하진 않지만, 나와 이 장치 사이엔 분명히 관계가 있다...\nPlayerName, 부탁하고 싶은 게 있다...",
  ui_story_5082_50820801_43_dialog_content = "대원수님...!",
  ui_story_5082_50820801_44_dialog_content = "비비안, 이건 내게 매우 중요한 일이다.",
  ui_story_5082_50820801_45_dialog_content = "그럼 저 괴물들이 못 오게 다들 주변 경계를 부탁할게요.",
  ui_story_5082_50820801_46_dialog_content = "전 지금부터 라인하르트 씨의 의식을 살펴볼 거예요.\n이 기계에 대체 어떤 비밀이 숨어 있는지 알아내야겠어요.",
  ui_story_5082_50820901_1_dialog_content = "(...일루미나의 실험실 같네. 근데 분위기가... 무척 갑갑해.)",
  ui_story_5082_50820901_2_dialog_content = "피험자 1호, 1번 방에 들어가 지시에 따라 루미나틱스를 시전하세요.",
  ui_story_5082_50820901_3_dialog_content = "예.",
  ui_story_5082_50820901_4_dialog_content = "피험자 2호, 2번 방에 들어가 지시에 따라 루미나틱스를 시전하세요.",
  ui_story_5082_50820901_5_dialog_content = "......",
  ui_story_5082_50820901_6_dialog_content = "(다들 뭘 하는 거지?)",
  ui_story_5082_50820901_7_dialog_content = "피험자 2호, 지시에 따라 주세요.",
  ui_story_5082_50820901_8_dialog_content = "다시 한번 요청합니다. 실험의 진짜 목적을 고지해 주세요.",
  ui_story_5082_50820901_9_dialog_content = "루미나틱스 숙련도를 측정하는 실험이라면, 적합한 조정과 준비를 할 수 있도록\n피험자에게 실험 환경에 대해 미리 고지해야 해요.",
  ui_story_5082_50820901_10_dialog_content = "빛 한 점 없는 방 안에서 기준도, 참고 대상도 없이 힘을 사용하는 건\n정상적인 실험으론 보이지 않는데요.",
  ui_story_5082_50820901_11_dialog_content = "연구원이 되고 싶다면 이 실험이 당신에게 해로울 일은 없을 겁니다, 드니에르.",
  ui_story_5082_50820901_12_dialog_content = "......",
  ui_story_5082_50820901_13_dialog_content = "피험자 3호, 3번 방에 들어가 지시에 따라 루미나틱스를 시전하세요.",
  ui_story_5082_50820901_14_dialog_content = "오늘 훈련 내용이 변경됐다는 통지는 받지 못했습니다.",
  ui_story_5082_50820901_15_dialog_content = "추가로 진행하는 작은 실험일 뿐이고, 우리가 당신에게 설명할 필요는 없습니다.\n당신은 명령에 복종하면 되는 겁니다.",
  ui_story_5082_50820901_16_dialog_content = "적어도 자신과 관계가 있는 일이라면 저도 알 권리가 있다고 생각합니다.",
  ui_story_5082_50820901_17_dialog_content = "PlayerName?",
  ui_story_5082_50820901_18_dialog_content = "좀 괜찮으세요? 방금 라인하르트 씨 모습 보고 진짜 깜짝 놀랐다니까요...",
  ui_story_5082_50820901_19_dialog_content = "근데 저 때 대체 무슨 실험을 하고 있었던 거죠? 왜 라인하르트 씨랑 두 사람을...",
  ui_story_5082_50820901_20_dialog_content = "나와 두 사람...? 여기 내가 있다고?",
  ui_story_5082_50820901_21_dialog_content = "안 보이세요? 라인하르트 씨... 지금 여기 있잖아요.",
  ui_story_5082_50820901_22_dialog_content = "아니야...",
  ui_story_5082_50820901_23_dialog_content = "<color=#e8d9bb>라인하르트는 잠시 머뭇거리더니, 눈썹을 찡그리며 앞으로 걸어 나와 기억 속 자신 앞에 섰다.</color>",
  ui_story_5082_50820901_24_dialog_content = "PlayerName, 너한테는 뭐가 보이지?",
  ui_story_5082_50820901_25_dialog_content = "지금의 라인하르트 씨랑 젊은 시절의 사관학교 제복을 입은 라인하르트 씨요.",
  ui_story_5082_50820901_26_dialog_content = "하지만 내 눈에 보이는 건 다른 사람이다.",
  ui_story_5082_50820901_27_dialog_content = "엉망으로 부스스한 짧은 흑발에, 언제라도 누구든지 도발할 것 같은 날카로운 눈빛.",
  ui_story_5082_50820901_28_dialog_content = "조금도 가리지 않고 드러낸 온몸의 촘촘한 상처, 빨간 셔츠, 망토처럼 두른 코트.",
  ui_story_5082_50820901_29_dialog_content = "규율 따위는 안중에도 없고, 통제와 교육에 복종하지 않으며,\n마치 모든 것을 태워버리는 매서운...",
  ui_story_5082_50820901_30_dialog_content = "눈부시면서도 선명한 빛깔의 불길을 지닌 여자다.",
  ui_story_5082_50820901_31_dialog_content = "그러니까... 그 붉은 빛을 발산하는 여자가 보인다는 얘기네요...",
  ui_story_5082_50820901_32_dialog_content = "그렇지.",
  ui_story_5082_50820901_33_dialog_content = "사실 지금 스스로도 믿기 어렵지만, 이 기억만큼은 틀림없다.",
  ui_story_5082_50820901_34_dialog_content = "저 여자는──",
  ui_story_5082_50820901_35_dialog_content = "나 자신이다.",
  ui_story_5082_50820901_36_dialog_content = "장면이 또 바뀌었어요.",
  ui_story_5082_50820901_37_dialog_content = "피험자는 장치를 조정하고 집중하세요.",
  ui_story_5082_50820901_38_dialog_content = "저 장치... 우리가 아까 찾았던 것들 같네요.",
  ui_story_5082_50820901_39_dialog_content = "역시 세 사람이 쓰던 게 맞았어요. 필리시가 엘리트 인재 육성 얘기를 한 이유가 있었네요.",
  ui_story_5082_50820901_40_dialog_content = "하지만... 난 전혀 기억이 없는 일이다...",
  ui_story_5082_50820901_41_dialog_content = "으윽... 갑자기 머리가 아프잖아... 이 장치랑 관계가 있는 건가?",
  ui_story_5082_50820901_42_dialog_content = "대뇌를 자극해서 감각 기관의 잠재 능력을 끌어내는 장치라 이건가...",
  ui_story_5082_50820901_43_dialog_content = "내 뇌에 무슨 문제라도 생기면 저 인간들이 책임질 순 있긴 한 거야?!",
  ui_story_5082_50820901_44_dialog_content = "잠깐만, 이건 내 심박이 아니잖아. 게다가 난 이런 복잡한 감정 같은 건 없어.\n근데 왜 들리는... 아니지, 느껴지는 거지...?",
  ui_story_5082_50820901_45_dialog_content = "다른 개체의 존재가.",
  ui_story_5082_50820901_46_dialog_content = "...언니?",
  ui_story_5082_50820901_47_dialog_content = "...드니에르.",
  ui_story_5082_50820901_48_dialog_content = "설마 너랑 이런 방식으로 얘기할 수 있는 날이 올 줄은 몰랐어.",
  ui_story_5082_50820901_49_dialog_content = "그리고 여기서 너랑 이야기하게 될 줄도... 왜 네가 여기 있는 거야?",
  ui_story_5082_50820901_50_dialog_content = "서로의 의식과 생각을 감응한다니... 아이테르 일족의 능력을 모방하려는 건가...?",
  ui_story_5082_50820901_51_dialog_content = "우리 둘 다 이 실험에 참가한 걸 보면 설마 다른 한 명도 있는 건 아니겠지.",
  ui_story_5082_50820901_52_dialog_content = "이게 대체 뭐야?",
  ui_story_5082_50820901_53_dialog_content = "추측이 맞았네.",
  ui_story_5082_50820901_54_dialog_content = "...루미나틱스 제어 능력 실험이라고 했었지만, 이렇게까지 할 필요는 없을 텐데 말이야.",
  ui_story_5082_50820901_55_dialog_content = "협동 작전의 효율을 높이기 위한 건가?",
  ui_story_5082_50820901_56_dialog_content = "그렇게 단순할 리가 없잖아. 왜 하필 우리 셋인지 궁금하지 않아?",
  ui_story_5082_50820901_57_dialog_content = "......",
  ui_story_5082_50820901_58_dialog_content = "게다가 실험자는 이 뒤에도 다른 실험이 있을 거라고 했어. 다들 들었겠지?",
  ui_story_5082_50820901_59_dialog_content = "난 아직 안 잊었어. 언니가 매번 그 「작은 실험」들을 하고 돌아왔을 때 어떤 꼴이었는지.",
  ui_story_5082_50820901_60_dialog_content = "우리 전투 능력은 라인하르트와는 같은 수준이 아니잖아. 어쩌면 우리 실험도... 으윽!",
  ui_story_5082_50820901_61_dialog_content = "헬리오스?!",
  ui_story_5082_50820901_62_dialog_content = "헬리오스의 의식이 사라졌어. 설마... 쳇.",
  ui_story_5082_50820901_63_dialog_content = "드니에르! 무슨 일이야?!",
  ui_story_5082_50820901_64_dialog_content = "크아아!",
  ui_story_5082_50820901_65_dialog_content = "...네놈들이 이번 「작은 실험」인 거냐.",
  ui_story_5082_50820902_1_dialog_content = "(그날 이후로 사적인 시간에도 항상 감시가 붙게 되었다...)",
  ui_story_5082_50820902_2_dialog_content = "......",
  ui_story_5082_50820902_3_dialog_content = "휴, 오늘 녀석들은 꽤 성가시네.",
  ui_story_5082_50820902_4_dialog_content = "거 봐. 저 정도는 라인하르트한텐 아무것도 아니라고 했잖아.\n그리고 이제 펑크 안 낼 거라고 약속도 했고 말이야.",
  ui_story_5082_50820902_5_dialog_content = "라인하르트, 뭐 위험한 일은 없었어?",
  ui_story_5082_50820902_6_dialog_content = "감시당하고 있을 뿐이야. 별일 아냐. 그것보다 실험이 끝난 뒤엔 왜 연락이 안 된 거야?",
  ui_story_5082_50820902_7_dialog_content = "......",
  ui_story_5082_50820902_8_dialog_content = "무슨 일이 있는 거면 다 얘기해 줘. 진실을 알아야 우리가 옳은 판단을 할 수 있으니까.",
  ui_story_5082_50820902_9_dialog_content = "...맞아. 우린 어릴 적부터 같이 자랐잖아. 적어도 우리끼린 비밀이 없어야지.",
  ui_story_5082_50820902_10_dialog_content = "사실 그 실험 이후로 계속 머리가 아파.",
  ui_story_5082_50820902_11_dialog_content = "그리고 왜인지 정찰조에서 더는 날 집단 작전에 부르질 않고 있어.\n상관한테 가서 물어봐도 아무 답도 들을 수 없었고.",
  ui_story_5082_50820902_12_dialog_content = "신체검사는 해 봤어?",
  ui_story_5082_50820902_13_dialog_content = "아무 이상 없었어. 평소 전투나 생활에도 큰 영향은 없었고. 그러니까 너무 걱정하진 마.",
  ui_story_5082_50820902_14_dialog_content = "드니에르, 넌?",
  ui_story_5082_50820902_15_dialog_content = "...여기가 발각됐어.",
  ui_story_5082_50820902_16_dialog_content = "!",
  ui_story_5082_50820902_17_dialog_content = "나 때문이야.",
  ui_story_5082_50820902_18_dialog_content = "전에 재료가 좀 필요해서 여기서 했던 프로젝트의 제안서를 상부에 제출했었어.\n뭐, 정작 그땐 아무 반응도 없었어.",
  ui_story_5082_50820902_19_dialog_content = "그런데 며칠 전 갑자기 기각 통지를 받았고, 내가 위험한 연구를 하는 건 아닌지\n의심이 된다는 명목으로 여기까지 추적이 들어왔어.",
  ui_story_5082_50820902_20_dialog_content = "결국 실험실을 폐쇄하고, 실험 설비와 성과를 전부 상부에 넘기라는 명령을 받았어.",
  ui_story_5082_50820902_21_dialog_content = "괜찮아, 이미 이렇게 한 번 만들어 봤잖아. 실험실은 새로 만들면 돼.",
  ui_story_5082_50820902_22_dialog_content = "실험 성과를 넘겨야 한다는 건 유감이지만... 참, 지금까지 물어보질 않았네.\n대체 여기서 뭘 연구하고 있었어?",
  ui_story_5082_50820902_23_dialog_content = "...지금은 그것보다 더 중요한 얘기가 있을 텐데.",
  ui_story_5082_50820902_24_dialog_content = "「이 실험에 성공한 피험자는 지금까지 없었습니다. 당신의 실험 데이터는\n일루미나 과학 기술 연구의 중대한 돌파구가 될지도 모릅니다.」",
  ui_story_5082_50820902_25_dialog_content = "「실험 중 경험한 것들을 전부 기록하세요... 뭘 들었고... 뭘 느꼈는지...」",
  ui_story_5082_50820902_26_dialog_content = "「원하는 게 진급이든, 첨단 기술에 대한 접근이든, 최대한의 지원과 우대를 얻게 될 겁니다.」",
  ui_story_5082_50820902_27_dialog_content = "그 「작은 실험」이 끝난 뒤로, 둘 다 마찬가지로 이런 암시를 받았겠지?",
  ui_story_5082_50820902_28_dialog_content = "......",
  ui_story_5082_50820902_29_dialog_content = "그럼 어디, 눈앞에 다가온 영광의 길을 포기하고 백지답안을 내서,\n스스로 패배자의 대열에 합류한 바보는 손을 들어 봐.",
  ui_story_5082_50820902_30_dialog_content = "드니에르가 그날 했던 말을 듣고 나도 의식하게 됐어. 그 실험은 우리 세 사람을 연결했어.",
  ui_story_5082_50820902_31_dialog_content = "저들의 목적은 아직 알 수 없지만, 내 실험 결과가 두 사람을 위험하게 만들지도 몰라.",
  ui_story_5082_50820902_32_dialog_content = "그러니까 난 그런 선택을 하지 않을 거고, 혼자서 그런 결정을 내릴 자격도 없어.",
  ui_story_5082_50820902_33_dialog_content = "<color=#e8d9bb>헬리오스는 손을 들었다.</color>",
  ui_story_5082_50820902_34_dialog_content = "그리고 너희한테 할 말이 또 있어.",
  ui_story_5082_50820902_35_dialog_content = "잠깐, 이번엔 내 차례잖아. 「작은 실험」은 내가 전문이라고.\n그럴 때 모든 패를 드러내지 않는 건 이미 내 본능이 됐거든.",
  ui_story_5082_50820902_36_dialog_content = "놈들은 내 한계를 알게 되는 순간, 무슨 수를 써서라도 그 한계를 넘어서게 만들어.",
  ui_story_5082_50820902_37_dialog_content = "설령 그 대가가 목숨이라 해도, 놈들은 전혀 신경 쓰지 않아.\n심지어 너희까지 휘말리게 만들 수도 있어.",
  ui_story_5082_50820902_38_dialog_content = "<color=#e8d9bb>라인하르트도 손을 들었다.</color>",
  ui_story_5082_50820902_39_dialog_content = "이번 며칠 동안 나도 조사해서 알아낸 게 좀 있어.",
  ui_story_5082_50820902_40_dialog_content = "일루미나는 향후 전쟁에 대비하기 위해 콜로서스 「어썰트호」의 가동 실험을 시작했어.",
  ui_story_5082_50820902_41_dialog_content = "콜로서스...",
  ui_story_5082_50820902_42_dialog_content = "들어봤지? 근처 지하성에서 파낸 거 말이야.\n헤븐즈 밸리에 있는 것들보다 더 오래된 콜로서스야.",
  ui_story_5082_50820902_43_dialog_content = "우리가 참가한 그 실험은 어쩌면 콜로서스의 파일럿을 선별하기 위한 거였을지도 몰라.",
  ui_story_5082_50820902_44_dialog_content = "하지만 난 내 실험 외의 일에 시간을 낭비하고 싶진 않아.\n게다가 남의 「작은 실험」 때문에 내 일상적인 모임까지 방해받고 싶지도 않고.",
  ui_story_5082_50820902_45_dialog_content = "그러니까──",
  ui_story_5082_50820902_46_dialog_content = "<color=#e8d9bb>드니에르도 손을 들었다.</color>",
  ui_story_5082_50820902_47_dialog_content = "전원일치네.",
  ui_story_5082_50820902_48_dialog_content = "축하하자. 조종사 선발 실험은 완벽하게 실패했어.",
  ui_story_5082_50820902_49_dialog_content = "이제 각자 해야 할 일을 하러 가면 되겠네. 오늘은 여기까지 하자.",
  ui_story_5082_50820902_50_dialog_content = "잠깐만, 내가 말하려는 일도 실험과 관계가 있어.",
  ui_story_5082_50820902_51_dialog_content = "난 그동안 딱히 할 일도 없었고, 저번 실험도 신경이 쓰여서 그 실험기지를 조사하러 갔었어.",
  ui_story_5082_50820902_52_dialog_content = "확인해 보니까 우리가 실험을 하던 곳은 사실 기지의 일부였고,\n실제로는 내가 상상했던 것보다 훨씬 컸어.",
  ui_story_5082_50820902_53_dialog_content = "단독으로 근처의 지하성에 지어진 이유가 있었던 거지.\n게다가 그 기지엔 연구 구역 외에도 이상할 정도로 잘 갖춰진 의료 시설과 설비가 있었어.",
  ui_story_5082_50820902_54_dialog_content = "경비가 삼엄해서 더 자세한 상황은 파악할 수 없었지만...",
  ui_story_5082_50820902_55_dialog_content = "식량 배급량으로 판단해 보면, 그 안에는 상당한 수의 환자가 있는 게 분명해.",
  ui_story_5082_50820902_56_dialog_content = "그 말은 결국... 네가 머리가 아팠던 게 어쩌면 너만의 증세가 아니고,\n입원이 필요할 정도로 심각한 후유증이 있는 사람들이 있을지도 모른다는 얘기잖아.",
  ui_story_5082_50820902_57_dialog_content = "그리고 이다음이 더 중요한 부분이야...",
  ui_story_5082_50820902_58_dialog_content = "고아원 관계자가 애들을 데리고 그 안으로 들어가는 걸 봤어.",
  ui_story_5082_50820902_59_dialog_content = "어쩌면 성인을 이용한 실험이 계속 실패하고 있어서, 놈들은...",
  ui_story_5082_50820902_60_dialog_content = "고아를 데려다 실험을 하고 있다는 거야?!",
  ui_story_5082_50820902_61_dialog_content = "앉아, 라인하르트.",
  ui_story_5082_50820902_62_dialog_content = "오늘 여기서 나온 얘기는 애초부터 우리가 알아선 안 되는 것들이야.",
  ui_story_5082_50820902_63_dialog_content = "지금 상황을 봐. 우린 지금 자기 자신을 지켜낼 수 있을지조차 미지수야.\n영웅이 될 여유 같은 건 없어.",
  ui_story_5082_50820902_64_dialog_content = "냉정하게 굴어. 그날 실험 이후로 난 새로운 생각을 하게 됐어.\n난 어떻게든 지금 내 연구를 계속할 거야.",
  ui_story_5082_50820902_65_dialog_content = "성공한다면 우릴 지킬 수 있을지도 몰라. 영원히 여길 떠날 수도 있겠지. 다만 지금은...",
  ui_story_5082_50820902_66_dialog_content = "난 지금까지 적어도 천 번 이상의 훈련을 겪었어.\n내 입으로 말하는 것도 그렇지만, 그건 보통 사람들이 절대 견딜 수 있는 게 아냐.",
  ui_story_5082_50820902_67_dialog_content = "그리고 그동안 「실험」을 위해 숨겨진 곳도 많이 가 봤고,\n그중엔 버려진 건물이나 한때 전장이었던 곳도 있어.",
  ui_story_5082_50820902_68_dialog_content = "구체적인 위치는 지도에 표시해 둘게. 임시 실험실로 쓸 만한 곳을 찾을 수 있을지도 몰라.",
  ui_story_5082_50820902_69_dialog_content = "대신 너 혼자 가야 할 것 같아.",
  ui_story_5082_50820902_70_dialog_content = "내가 지금까지 한 말 안 들었어?",
  ui_story_5082_50820902_71_dialog_content = "언니가 지금까지 참가한 특훈들, 어쩌면 저들이 더 큰 프로젝트를 위해 준비한 걸 수도 있어──",
  ui_story_5082_50820902_72_dialog_content = "설령 그렇다고 해도!",
  ui_story_5082_50820902_73_dialog_content = "언니...",
  ui_story_5082_50820902_74_dialog_content = "네가 걱정하는 건 알아. 하지만 드니에르, 여길 떠나봤자 아무것도 해결되지 않아.",
  ui_story_5082_50820902_75_dialog_content = "헬리오스, 나랑 같이 조사하러 다시 가줄 수 있겠어?",
  ui_story_5082_50820902_76_dialog_content = "네가 말 안 해도 갈 거야. 다만 정말 우리가 생각하는 상황이 맞다면... 어쩔 셈이야?",
  ui_story_5082_50820902_77_dialog_content = "네 생각은 어떤데?",
  ui_story_5082_50820902_78_dialog_content = "...만에 하나 그 사람들을 구해냈다 쳐도... 그다음은?",
  ui_story_5082_50820902_79_dialog_content = "거기까진 생각 안 해 봤어.",
  ui_story_5082_50820902_80_dialog_content = "하지만 무슨 일이 일어나고 있는지 알면서도 방관한다면...",
  ui_story_5082_50820902_81_dialog_content = "그동안 내가 해 온 노력이 무슨 의미가 있는지 모르게 될 것 같아.",
  ui_story_5082_50820902_82_dialog_content = "난 대원수가 될 거고, 최강의 전사가 될 거야.\n위기가 닥쳤을 때 가장 앞에서 모두를 지키는 사람이 될 거라고.",
  ui_story_5082_50820902_83_dialog_content = "동포가 위기에 처해 있는데도 망설이고, 신예들의 힘을 두려워하며\n그 싹을 밟으려 드는 자가 되진 않아.",
  ui_story_5082_50820902_84_dialog_content = "허울 좋은 이유로 아이들을 실험실로 보내는 「가해자」는 더더욱 될 수 없어.",
  ui_story_5082_50820902_85_dialog_content = "만약 지금의 일루미나 상부가 전부 그런 놈들이라면, 난 놈들에게 묻고 싶어.",
  ui_story_5082_50820902_86_dialog_content = "「여명의 빛을 위하여」라는 말은 그저 손쉽게 병사들이 전선에 목숨을 던지게 만들고,\n맨주먹의 일반인들을 인질로 삼고 희생시켜 가며...",
  ui_story_5082_50820902_87_dialog_content = "자신의 이익을 지키기 위한 구호일 뿐이었냐고.",
  ui_story_5082_50820902_88_dialog_content = "어이, 라인하르트! 너 지금 네가 무슨 소리를 하고 있는지 알고 있어?",
  ui_story_5082_50820902_89_dialog_content = "가짜 전령으로 멋대로 출격해서 상부에 위험분자라고 찍힌 것도 모자라서...",
  ui_story_5082_50820902_90_dialog_content = "이젠 정말 일루미나를 배반하는 반역자가 될 셈이야?!",
  ui_story_5082_50820902_91_dialog_content = "반역자? 아니지.",
  ui_story_5082_50820902_92_dialog_content = "상부의 겁쟁이들이 시키는 대로 하는 바보들이야말로 반역자야.",
  ui_story_5082_50820902_93_dialog_content = "아이들을 해치는 실험을 눈감아 주고, 세상이 태평하다는 거짓말을 받아주는\n방관자들이야말로 반역자라고.",
  ui_story_5082_50820902_94_dialog_content = "난 그런 규칙엔 복종하지 않겠어. 그리고 나만 무사하고 싶은 생각도 없어.",
  ui_story_5082_50820902_95_dialog_content = "미안해, 드니에르, 헬리오스. 이런 일에 말려들게 해서.",
  ui_story_5082_50820902_96_dialog_content = "하지만 만약 내가 품은 이상이 규칙에 얽매여서는 결코 실현할 수 없는 거라면...",
  ui_story_5082_50820902_97_dialog_content = "난 전력을 다해 이 거짓된 하늘을 뒤엎어 버리겠어.",
  ui_story_5082_50821001_1_dialog_content = "그럼... 일루미나의 대원수가 한때 일루미나를 뒤엎으려고 했다는 얘긴가요?!",
  ui_story_5082_50821001_2_dialog_content = "세 사람은 전쟁 병기로 만들어진 존재니까, 그 기묘한 정신적 유대는 이상할 것도 없겠지...",
  ui_story_5082_50821001_3_dialog_content = "처음엔 함께 실험 결과에 침묵을 지키면 그걸로 끝날 줄 알았다.\n하지만 그 결과 오히려 상부의 주의를 끌고 말았지.",
  ui_story_5082_50821001_4_dialog_content = "일루미나를 뒤엎는다라... 참으로 대담한 짓이지...",
  ui_story_5082_50821001_5_dialog_content = "하지만 자신의 우월감이 거저 생긴 게 아니라, 오랜 육성 계획의 결과란 걸 알아챈 것도\n확실히 보통 일은 아니긴 하지.",
  ui_story_5082_50821001_6_dialog_content = "...자기 일인데 마치 남의 일처럼 말하시네요.",
  ui_story_5082_50821001_7_dialog_content = "내겐 다른 사람이나 마찬가지니까.",
  ui_story_5082_50821001_8_dialog_content = "사관학교, 특훈, 실험, 그리고 고아원의 일까지, 난 줄곧 내가 전부 기억하고 있다고 생각했다.",
  ui_story_5082_50821001_9_dialog_content = "때로는 그 속에서 위화감이 드는 공백을 발견하기도 했지만,\n그 공백 안에 이렇게 낯선 이야기들이 가득 숨어 있을 줄은 몰랐지.",
  ui_story_5082_50821001_10_dialog_content = "특히 우리 셋이 참가했던 저 실험은 마치 깨끗하게 삭제된 것만 같았다.",
  ui_story_5082_50821001_11_dialog_content = "설마 내가 기억하는 과거가 모두 진실과는 달랐던 건가...",
  ui_story_5082_50821001_12_dialog_content = "...바이스도 분명히 같은 생각을 해왔겠죠.",
  ui_story_5082_50821001_13_dialog_content = "지금 저 장치로 기억을 조금이라도 되찾은 건 그나마 좋은 일 아닐까요?",
  ui_story_5082_50821001_14_dialog_content = "라인하르트 씨도 한때 후보생이었다면, 어쩌면 두 사람 모두 같은 이유로\n그때의 기억을 잃었을지도 몰라요.",
  ui_story_5082_50821001_15_dialog_content = "아니, 여기까지 보고 너도 예상했겠지만, 나는 콜로서스의 조종사 후보자로 선정되지 않았다.\n적어도 내 기억엔 없어.",
  ui_story_5082_50821001_16_dialog_content = "난 그저 「그녀」가 그 뒤에 어떻게 됐는지 알고 싶을 뿐이다.",
  ui_story_5082_50821001_17_dialog_content = "두 사람 예상은 거의 정확했어.",
  ui_story_5082_50821001_18_dialog_content = "실험실 쪽에 진전이 있었어. 이제 곧 정식으로 콜로서스 「어썰트호」를 가동할 거야.",
  ui_story_5082_50821001_19_dialog_content = "「조종사」로 선정된 건 마찬가지로 고아원 출신인 네 살짜리 여자애야.",
  ui_story_5082_50821001_20_dialog_content = "그 애는 실험용 장치와의 적응도가 피험자 중에서 가장 높았다고 해.",
  ui_story_5082_50821001_21_dialog_content = "네 살짜리 어린애한테 그런 짓을 시켜? 그게 무슨 웃기지도 않는 소리냐고!",
  ui_story_5082_50821001_22_dialog_content = "네 살짜리라고 무시하진 마.",
  ui_story_5082_50821001_23_dialog_content = "듣기로는 그 애, 이미 위원회 손에서 비밀리에 1년간 육성된 것 같아.\n콜로서스에 대한 경험만 놓고 보면 우리보다 많을 수도 있어.",
  ui_story_5082_50821001_24_dialog_content = "심지어 첫 실험 성공률은 20%를 넘었고 말이야.",
  ui_story_5082_50821001_25_dialog_content = "드니에르, 너 이 자식...",
  ui_story_5082_50821001_26_dialog_content = "...그렇게 말할 건 없잖아.",
  ui_story_5082_50821001_27_dialog_content = "난 어디까지나 사실을 말하고 있을 뿐이야. 지금 밖에서 암귀와의 싸움이 어떻게 돌아가고 있는지 알잖아?",
  ui_story_5082_50821001_28_dialog_content = "지금 실험 설계를 기준으로, 저 사람들이 조금도 망설이지 않고 어린애 목숨을 걸 확률로\n20%는 충분히 「높은」 수치야.",
  ui_story_5082_50821001_29_dialog_content = "그렇다고 해도 아이의 목숨을 가지고 농담을 할 순 없어!\n더는 못 기다려. 지금 당장 행동을 개시해야 해!",
  ui_story_5082_50821001_30_dialog_content = "네 전제가 옳은지는 일단 제쳐두자. 지금 넌 이제 막 지휘권을 회복했어.\n게다가 나와 드니에르는 여전히 고립된 상태야. 널 도와줄 사람이 없다고.",
  ui_story_5082_50821001_31_dialog_content = "지휘권을 이제 막 되찾은 거지, 적어도 이제 막 입대한 신병은 아니잖아?",
  ui_story_5082_50821001_32_dialog_content = "1군단에서 가장 잘 싸우는 녀석들이 모두 날 따르고 있어.",
  ui_story_5082_50821001_33_dialog_content = "최대한 빨리 감시망에서 벗어나 근처의 버려진 지하성을 거점으로 삼겠어.",
  ui_story_5082_50821001_34_dialog_content = "필요하면 바튼한테도 연락해. 바튼은 우리 편이야.",
  ui_story_5082_50821001_35_dialog_content = "게다가 너희가 고립된 상황은 오히려 자유롭게 정보를 찾기엔 더 좋을 거야.",
  ui_story_5082_50821001_36_dialog_content = "드니에르는 실험실 쪽 동향을 맡아 줘.\n헬리오스 넌 일루미나에 다른 비슷한 비밀 실험이 얼마나 더 있는지 알아봐 줬으면 해.",
  ui_story_5082_50821001_37_dialog_content = "군 수뇌부든, 연구소든, 싸움을 걸 거라면 최악의 상황을 가정할 필요가 있어.",
  ui_story_5082_50821001_38_dialog_content = "내 대원수의 길을 위한 첫 싸움은 저 무고한 피험자를 구하는 데서부터 시작하겠어.",
  ui_story_5082_50821001_39_dialog_content = "근데 우린 위원회의 진짜 힘을 제대로 알지도 못하고 있어. 이대로는 너무 무모하지 않아?",
  ui_story_5082_50821001_40_dialog_content = "저들이 라인하르트 너 같은 전력을 또 숨기고 있다면, 우리만 가지고는 힘들어.",
  ui_story_5082_50821001_41_dialog_content = "그땐 「플랜 B」로 가면 돼.",
  ui_story_5082_50821001_42_dialog_content = "오로리안의 생존은 사실 간단해. 황폐한 지하성이든, 어디 구석진 곳이든 상관없어...",
  ui_story_5082_50821001_43_dialog_content = "적당한 식량과 물, 공간, 일조량만 있다면 거주지는 세울 수 있어.",
  ui_story_5082_50821001_44_dialog_content = "그리고 오로리안이 모인 곳이라면, 어디든 대원수가 필요해.",
  ui_story_5082_50821001_45_dialog_content = "하하, 너무 멀리 간 거 아냐? 드니에르, 난 그렇게까진 안 됐으면 좋겠어.",
  ui_story_5082_50821001_46_dialog_content = "우리 첫 목표는 그저 위험에 처한 오로리안들이 안전하게 살아갈 수 있게 하는 거였고...",
  ui_story_5082_50821001_47_dialog_content = "부모가 누군지도 모르는 우리처럼, 태어날 때부터 주먹을 들고\n자신을 지킬 수밖에 없었던 아이들에게 피난처를 제공하는 거였으니까.",
  ui_story_5082_50821001_48_dialog_content = "......",
  ui_story_5082_50821001_49_dialog_content = "일루미나 사람들은 정말 다들 비슷한 과거를 가지고 있었네요...",
  ui_story_5082_50821001_50_dialog_content = "그동안 전 바이스 걱정만 했었는데... 오늘 이런 사실을 알고 나니까\n너무 괴롭고, 미안해졌어요.",
  ui_story_5082_50821001_51_dialog_content = "불행은 비교할 수 있는 게 아냐. 네 살짜리 소녀가 무엇을 겪게 될지는\n많은 일루미나인들이 자신의 경험으로 네게 말해줄 수 있을 거다.",
  ui_story_5082_50821001_52_dialog_content = "다만 이렇게 본다면, 이 실험에 관해 바이스가 가진 기억은...\n어쩌면 진실이 아닐 거란 생각이 드는군.",
  ui_story_5082_50821001_53_dialog_content = "그나저나 넌 왠지 「그녀」의 뜻에 꽤 찬성하는 것 같은데 말이지.",
  ui_story_5082_50821001_54_dialog_content = "...세 사람 계획은 결국 성공했나요?",
  ui_story_5082_50821001_55_dialog_content = "그 질문에 대한 내 답은 지금의 내가 일루미나의 대원수라는 사실로 대신할 수 있겠군.",
  ui_story_5082_50821001_56_dialog_content = "중점은 「지금의 나」인가요, 아니면 「일루미나의」인가요?",
  ui_story_5082_50821001_57_dialog_content = "그게 중요한가? 중점이 어느 쪽이든, 「그녀」의 계획이 실패한 건 마찬가지일 텐데.",
  ui_story_5082_50821001_58_dialog_content = "전 중요하다고 생각해요.",
  ui_story_5082_50821001_59_dialog_content = "그 계획의 결과도 물론 궁금한 건 맞아요.\n하지만 성공했든, 실패했든 이미 지나간 과거의 일인걸요.",
  ui_story_5082_50821001_60_dialog_content = "반면에 라인하르트 씨가 강조한 게 어느 쪽인지는 지금 라인하르트 씨의 생각이 반영되겠죠.",
  ui_story_5082_50821001_61_dialog_content = "전자라면 라인하르트 씨 자신이 「그녀」를 이긴 게 중요하다는 뜻이고,\n후자라면 「그녀」는 일루미나에 패배한 게 돼요.",
  ui_story_5082_50821001_62_dialog_content = "전 지금 라인하르트 씨가 어느 쪽에 서 있는지 알고 싶어요.",
  ui_story_5082_50821001_63_dialog_content = "가끔은 너무 솔직한 게 좋지는 않다는 것도 좀 배울 필요가 있지 않겠어?",
  ui_story_5082_50821001_64_dialog_content = "라인하르트 씨니까 솔직하게 말하는 거예요.",
  ui_story_5082_50821001_65_dialog_content = "그렇다면 나도 솔직하게 얘기해야 널 실망시키지 않겠군.",
  ui_story_5082_50821001_66_dialog_content = "사실 나도 잘 모르겠다. 넌 어떻게 생각하지?\n저 「라인하르트」가 날 닮은 걸까, 아니면 내가 「저 여자」를 닮은 걸까.",
  ui_story_5082_50821001_67_dialog_content = "으음...",
  ui_story_5082_50821001_68_dialog_content = "내 눈치 볼 거 없어. 네가 무슨 말을 하든 화내지 않을 테니까.",
  ui_story_5082_50821001_69_dialog_content = "그, 그 정도로 심한 말을 하진 않을 텐데요...",
  ui_story_5082_50821001_70_dialog_content = "그냥 왠지... 저 때의 라인하르트 씨가 지금보다 더 자유롭고, 거리낌 없고, 더...",
  ui_story_5082_50821001_71_dialog_content = "죄송해요. 뭐라고 말해야 할지 갑자기 떠오르질 않아서요.",
  ui_story_5082_50821001_72_dialog_content = "충분히 정곡을 찔렀다만.",
  ui_story_5082_50821001_73_dialog_content = "보다시피 나와 「그녀」는 많이 다르다.",
  ui_story_5082_50821001_74_dialog_content = "지금 이 순간에도 일루미나 어딘가에는 당시의 나와 같은 실험을 겪는 자들이 있을지도 모른다.",
  ui_story_5082_50821001_75_dialog_content = "이미 오랜 세월이 흘렀다. 어둠의 밑바닥의 잔혹한 광경은 너도 봤고 말이야.\n넌 내가 조금도 동요한 적이 없을 거라 생각하나?",
  ui_story_5082_50821001_76_dialog_content = "사실 난 내가 그럴 줄 알았고, 그러길 바라왔다.",
  ui_story_5082_50821001_77_dialog_content = "젊을 때의 난 내 손으로 일루미나의 모든 걸 지키고 싶다고 생각했지.",
  ui_story_5082_50821001_78_dialog_content = "하지만 많은 동포를 잃은 지금, 나도 자신에게 묻곤 한다.\n라인하르트라는 개인의 힘으로, 이 일루미나를 대체 언제까지 지탱할 수 있냐고 말이야.",
  ui_story_5082_50821001_79_dialog_content = "만약 지금 「그녀」 같은 젊은이가 눈앞에 나타나 분노를 드러내고, 내 무능을 질책한다면.",
  ui_story_5082_50821001_80_dialog_content = "썩어빠진 날 쳐부수고 깨끗한 세상을 만들겠다고 선언한다면.",
  ui_story_5082_50821001_81_dialog_content = "나도 내가 그녀를 지지할지, 아니면 막을지 모르겠군...",
  ui_story_5082_50821001_82_dialog_content = "아니면...",
  ui_story_5082_50821001_83_dialog_content = "한 세력을 이끄는 지도자의 입장을 제가 완전히 이해할 순 없을 거예요.\n하지만 동료로서 제가 아는 라인하르트 씨는 그런 사람이 아니에요...",
  ui_story_5082_50821001_84_dialog_content = "그리고 라인하르트 씨도 혼자 일루미나를 지탱하고 있는 게 아니고요.",
  ui_story_5082_50821001_85_dialog_content = "네가 뭘 말하려는지는 안다. 하지만 「그녀」의 모습을 보고 있으면,\n나도 모르게 그 시절이 생각나서... 조금 푸념을 했을 뿐이야.",
  ui_story_5082_50821001_86_dialog_content = "네게 이런 모습을 보이는 게 두렵진 않다. 다만 너도 이런 내 모습에 실망했겠지?",
  ui_story_5082_50821001_87_dialog_content = "아니에요...",
  ui_story_5082_50821001_88_dialog_content = "자, 돌아가자. 다들 애타게 기다리고 있을 거다.",
  ui_story_5082_50821001_89_dialog_content = "...그럼 대원수님은 자기 과거를 보신 건가요?",
  ui_story_5082_50821001_90_dialog_content = "...바튼 장군은요? 당시 상황에 대해 얼마나 알고 계시죠?",
  ui_story_5082_50821001_91_dialog_content = "내가 아는 건 당시 라인하르트가 노라, 헬리오스와 뒤에서 뭔가 꾸미고 있었다는 정도뿐이다.",
  ui_story_5082_50821001_92_dialog_content = "......",
  ui_story_5082_50821001_93_dialog_content = "나도 그때 말했었지. 네가 뭘 하든 난 널 지지하겠다고 말이야.\n하지만 끝까지 난 아무 연락도 받지 못했다.",
  ui_story_5082_50821001_94_dialog_content = "그저 네가 그때 폭발 사고에 휘말렸다는 것만 들었고, 그때 상황은 더 파고들 겨를이 없었다.",
  ui_story_5082_50821001_95_dialog_content = "우린 어둠의 위기에 대응하는 것만으로도 벅찼고, 전쟁 외에도 온갖 귀찮은 잡무로 바빴으니까.",
  ui_story_5082_50821001_96_dialog_content = "그 뒤에 다시 만났을 때, 비록 그때 넌 아직 군단장은 아니었지만,\n왠지 이미 군단장을 넘어선 존재가 되어버린 것 같았지.",
  ui_story_5082_50821001_97_dialog_content = "그럼 사고 후에... 라인하르트 씨가 또 진급하셨다는 건가요?",
  ui_story_5082_50821001_98_dialog_content = "그래, 게다가 마치 전혀 다른 사람이 돼버렸었지. 위엄 있고 묵직하게 변했고,\n힘까지도 무서울 정도로 강해져 있었다. 그것도 엄청나게 빠르게 말이지.",
  ui_story_5082_50821001_99_dialog_content = "녀석의 성장 속도에 비하면, 그때 난 소꿉장난이나 하는 느낌이었다고.",
  ui_story_5082_50821001_100_dialog_content = "그래서 난 임무와 별개로 내게 특훈을 준비했고, 부하들도 더 엄격하게 대하기 시작했지!",
  ui_story_5082_50821001_101_dialog_content = "가혹한 훈련으로 유명한 2군단의 명성은 그때부터 시작된 거였군요.",
  ui_story_5082_50821001_102_dialog_content = "<color=#e8d9bb>쾅! 쾅!</color>",
  ui_story_5082_50821001_103_dialog_content = "우냐앙?! 다 끝난 줄 알았는데 뭐냥!",
  ui_story_5082_50821001_104_dialog_content = "왜 벽에 부딪히고 있는 거지?",
  ui_story_5082_50821001_105_dialog_content = "여긴 구조가 불안정해요! 반드시 막아야 해요! 아니면 벽이 무너져서 생매장당하고 말 거예요!",
  ui_story_5082_50821101_1_dialog_content = "<color=#e8d9bb>쿠구구!</color>",
  ui_story_5082_50821101_2_dialog_content = "다들 다친 곳은 없나?",
  ui_story_5082_50821101_3_dialog_content = "무사합니다냥~ 그치만 다음엔 이렇게 높은 곳에서 떨어지는 건 사양이다냥.",
  ui_story_5082_50821101_4_dialog_content = "전 괜찮아요, 대원수님.",
  ui_story_5082_50821101_5_dialog_content = "PlayerName, 넌 괜찮냐?",
  ui_story_5082_50821101_6_dialog_content = "괜찮아요... 고마워요. 바튼 씨가 안 잡아 줬으면 저 돌덩이에 깔려 납작해졌겠네요.",
  ui_story_5082_50821101_7_dialog_content = "그러니까 너보고 평소에 훈련을 더 하라고 했잖냐.",
  ui_story_5082_50821101_8_dialog_content = "이번 일이 끝나면 매일 훈련소로 찾아와라. 모든 훈련 프로그램에 고도차 요소도 추가해야겠어.",
  ui_story_5082_50821101_9_dialog_content = "...아무래도 우리 모두 이 기지의 가장 낮은 층까지 떨어져 버린 모양이네요.",
  ui_story_5082_50821101_10_dialog_content = "엄청 넓은데, 대체 뭐 하는 데 쓰던 곳이었을까요?",
  ui_story_5082_50821101_11_dialog_content = "그건 다시 기억을 확인할 필요도 없이 지금 바로 대답해 줄 수 있겠군.\n바로 저걸 보관해 두는 곳이었지.",
  ui_story_5082_50821101_12_dialog_content = "거의 뼈대밖에 안 남은... 콜로서스네요? 지금까지 제가 감응한 게 저 콜로서스였어요!",
  ui_story_5082_50821101_13_dialog_content = "...콜로서스마저 저렇게 변할 정도면, 지하성의 구조가 불안정해진 것도 무리는 아니네요.",
  ui_story_5082_50821101_14_dialog_content = "...그때 실험에서 대체 무슨 일이 있었던 거죠? 라인하르트 씨, 혹시 떠오르는 거 있으세요?",
  ui_story_5082_50821101_15_dialog_content = "아직은 기억이 불완전하지만, 「그녀」의 흔적은 내가 군단장이 된 이후의\n기억 속에선 나타나지 않았다.",
  ui_story_5082_50821101_16_dialog_content = "그 부분에 대해선 이미 내 나름의 결론을 내렸다.",
  ui_story_5082_50821101_17_dialog_content = "아직은 기억이 불완전하지만, 「그녀」의 흔적은 내가 군단장이 된 이후에는 나타나지 않았다.",
  ui_story_5082_50821101_18_dialog_content = "그 부분에 대해선 이미 내 나름의 결론을 내렸다.",
  ui_story_5082_50821101_19_dialog_content = "아마 저들은 내 과거를 포함한 모든 것을 묻어 버렸다고 생각했겠지...",
  ui_story_5082_50821101_20_dialog_content = "하지만 「그녀」는 어째서인지 이곳을 맴돌며 내게 무언가를 전하려 한다.",
  ui_story_5082_50821101_21_dialog_content = "이곳, 아니면 이곳에서 발생한 사고가 「그녀」와 관련된 기억의 마지막 연결점이다.",
  ui_story_5082_50821101_22_dialog_content = "이곳에서 일어난 사건이 「그녀」를 내게서 분리시켰었지...",
  ui_story_5082_50821101_23_dialog_content = "그리고 그 사건은 내 몸에 과도할 만큼 강한 힘을 심었고,\n나를 지금의 대원수로 만들어 주었다.",
  ui_story_5082_50821101_24_dialog_content = "「계명성 프로젝트」의 전말을 알고 난 후로, 난 내 몸에 무슨 일이 일어나든\n놀라지 않게 되었다.",
  ui_story_5082_50821101_25_dialog_content = "한때 율리시스는 내가 일루미나에 10년간의 안녕을 가져다줄 자라고 했었지...\n훗, 결국엔 정말로 저들이 바라던 이상적인 강화 병사가 되어 버린 셈인가.",
  ui_story_5082_50821101_26_dialog_content = "......",
  ui_story_5082_50821101_27_dialog_content = "...벌써 서둘러 결론을 내릴 필요는 없잖아요. 아직 살펴볼 곳이 이렇게나 많은걸요.",
  ui_story_5082_50821101_28_dialog_content = "어쩌면 또 어디서 새로운 증거가 나와서, 라인하르트 씨가 갑자기 강해진 건\n자기 잠재력을 발휘했을 뿐이라고 증명해 줄지도 몰라요.",
  ui_story_5082_50821101_29_dialog_content = "오오, 필리시 털이 다 서버렸다냥! 장치에 뭔가 반응이 있다냥~",
  ui_story_5082_50821101_30_dialog_content = "<color=#e8d9bb>치직, 치지직──!</color>",
  ui_story_5082_50821101_31_dialog_content = "(이 반응, 설마...)",
  ui_story_5082_50821101_32_option_content = "[감응한다]",
  ui_story_5082_50821101_33_dialog_content = "...어썰트호!",
  ui_story_5082_50821101_34_dialog_content = "약속대로 와 주셨군요.",
  ui_story_5082_50821101_35_dialog_content = "그건 네가 멋대로 한 혼잣말이잖아. 난 약속 같은 거 한 적 없어.",
  ui_story_5082_50821101_36_dialog_content = "내가 여기 온 건 너한테 묻고 싶은 게 몇 가지 있어서야.",
  ui_story_5082_50821101_37_dialog_content = "당신이 뭘 궁금해하는지 알고 있습니다. 한 소녀... 아니, 두 소녀의 과거겠지요.",
  ui_story_5082_50821101_38_dialog_content = "(역시 맞았어! 바이스랑 라인하르트 씨가 잃어버린 기억은 조종사 선발 실험과 관계가 있어!)",
  ui_story_5082_50821101_39_dialog_content = "빨리 말해줘. 두 사람이 그때 대체 무슨 일을 겪었던 거야?",
  ui_story_5082_50821101_40_dialog_content = "당신이 얻고자 하는 것은 이곳에 저장된 데이터의 일부일 뿐입니다.",
  ui_story_5082_50821101_41_dialog_content = "그러나 지금의 저는 불완전한 기계에 불과합니다.\n데이터도 붕괴 도중 흩어졌기 때문에, 저도 명확히 확인할 수 없습니다.",
  ui_story_5082_50821101_42_dialog_content = "그럼 나보고 데이터 찾는 걸 도와달라는 거야?",
  ui_story_5082_50821101_43_dialog_content = "그 속에서 무언가를 찾고 싶어 하는 사람은 당신입니다.",
  ui_story_5082_50821101_44_dialog_content = "...내가 어떻게 하면 되는데?",
  ui_story_5082_50821101_45_dialog_content = "저들은 제 신체를 훼손하고, 자신들의 낙후된 기술로 제 시스템을 재구축하려 했습니다.",
  ui_story_5082_50821101_46_dialog_content = "저는 이제 더는 감응으로 모든 것을 완료할 수 없게 되었습니다, 아이테르.",
  ui_story_5082_50821101_47_dialog_content = "저 감응 장치를 착용해 주십시오. 그 장치를 통해 이곳에 있는 것들과 연결할 수 있을 겁니다.",
  ui_story_5082_50821101_48_dialog_content = "이거만 착용하면 되는 거 맞지?",
  ui_story_5082_50821101_49_dialog_content = "PlayerName, 뭘 하려는 거지?",
  ui_story_5082_50821101_50_dialog_content = "방금 어썰트호의 의식에 감응했는데, 이렇게 하면 저희한테 필요한 걸\n찾을 수 있을지도 모른다고 했거든요.",
  ui_story_5082_50821101_51_dialog_content = "들어오기 전에 내가 했던 말, 기억하고 있나?",
  ui_story_5082_50821101_52_dialog_content = "네. 그치만 지금 우리한테 남은 단서는 이거 하나뿐인걸요.",
  ui_story_5082_50821101_53_dialog_content = "온갖 고생을 해서 여기까지 왔는데, 모두의 노력을 물거품으로 만들긴 싫어요.",
  ui_story_5082_50821101_54_dialog_content = "그리고 조금 위험할 수도 있지만, 여긴 제가 믿을 수 있는 동료들도 이렇게 많이 있잖아요?",
  ui_story_5082_50821101_55_dialog_content = "그러니까 일루미나를 짊어진 무게를 모두에게도 조금씩 나눠 주세요.\n이건 제가 아까 라인하르트 씨한테 하고 싶었던 말이기도 해요.",
  ui_story_5082_50821101_56_dialog_content = "설령 「어썰트호」가 다른 속셈이 있더라도, 일루미나는 이미 녀석을 쓰러트린 적이 있으니까,\n저 녀석 뜻대로 되게 놔두진 않을 거라고 믿어요.",
  ui_story_5082_50821101_57_dialog_content = "말 한번 잘했다! 너 이 자식 내가 제일 마음에 드는 게 그렇게 남을 결심하게 만들 때라고.\n자, 대원수, 어쩔 생각이야?",
  ui_story_5082_50821101_58_dialog_content = "알겠다. 조심하도록 해.",
  ui_story_5082_50821101_59_dialog_content = "네.",
  ui_story_5082_50821101_60_dialog_content = "(이렇게 머리에 쓴 다음에...)",
  ui_story_5082_50821101_61_option_content = "[감응한다]",
  ui_story_5082_50821101_62_dialog_content = "콜로서스 쪽 조정은 거의 끝났습니다. 지금 바로 연구원장님께 전달하겠습니다.",
  ui_story_5082_50821101_63_dialog_content = "이제 적합도가 충분한 「조종사」만 준비되면 정식으로 실험을 시작할 수 있습니다.",
  ui_story_5082_50821101_64_dialog_content = "지금까지 적합도가 제일 높은 건 누굽니까?",
  ui_story_5082_50821101_65_dialog_content = "그 삼인방의 테스트가 끝난 뒤부터는 상부에서 피험자 정보는 숨기고 데이터만 보내오고 있습니다.",
  ui_story_5082_50821101_66_dialog_content = "그 삼인방, 실험 데이터는 나쁘지 않았던 걸로 기억하는데 말이지요.",
  ui_story_5082_50821101_67_dialog_content = "그렇습니다, 「인공 태양」 프로젝트의 산물들이니까요.",
  ui_story_5082_50821101_68_dialog_content = "하지만 그 셋이 실험 중에 보여 준 행동과 결과엔 뭔가 모순된 부분이 있어서,\n위원회는 그 삼인방이 일부러 실험 결과를 숨긴 건 아닌지 의심하고 있습니다.",
  ui_story_5082_50821101_69_dialog_content = "그런 일이 있었단 말입니까?",
  ui_story_5082_50821101_70_dialog_content = "만약 삼인방이 일부러 사실을 숨긴 거라면, 콜로서스와의 적합도가\n아무리 높더라도 실험엔 못 쓸 겁니다.",
  ui_story_5082_50821101_71_dialog_content = "만일의 경우를 대비해서 위원회에선 이미 그 셋을 조사하는 중입니다.\n운이 좋길 바랄 수밖에 없겠지요.",
  ui_story_5082_50821101_72_dialog_content = "(저 과학자들 말투는 정말 못 들어주겠어.)",
  ui_story_5082_50821101_73_dialog_content = "(...뭐, 어차피 더 볼 시간도 없지만.)",
  ui_story_5082_50821101_74_dialog_content = "어썰트호, 그 두 소녀의 데이터는 어디 있어?",
  ui_story_5082_50821101_75_dialog_content = "거의 다 됐습니다. 이제 곧입니다.",
  ui_story_5082_50821101_76_dialog_content = "신호가 확장될 때까지 기다리세요, 아이테르. 특수한 버튼을 찾아서, 그걸 누르는 겁니다!",
  ui_story_5082_50821101_77_dialog_content = "특수한 버튼이라면...",
  ui_story_5082_50821101_78_dialog_content = "앞으로 이동하세요! 서둘러야 합니다!",
  ui_story_5082_50821101_79_dialog_content = "(주변의 모습이 어째 좀 이상한데...?)",
  ui_story_5082_50821101_80_dialog_content = "어서... 버튼을 누르세요! 어서요!",
  ui_story_5082_50821101_81_dialog_content = "으윽... 머리가... 어썰트호, 너 뭘 하고 있는 거야?!",
  ui_story_5082_50821101_82_dialog_content = "어서 버튼을 눌러 절 풀어주는 겁니다!",
  ui_story_5082_50821101_83_dialog_content = "이클립스의 무기가 되어, 그분들을 위해 오로리안을 없애라!",
  ui_story_5082_50821101_84_dialog_content = "!",
  ui_story_5082_50821101_85_dialog_content = "일루미나! 그자들! 그 저주받을 놈들!",
  ui_story_5082_50821101_86_dialog_content = "저를 이런 꼴로 만들다니... 반드시 복수할 겁니다!\n설령 저들과 함께 파멸하는 일이 있더라도 말입니다!",
  ui_story_5082_50821101_87_dialog_content = "(엄청난 증오심이야... 이게 다 어썰트호한테서 흘러넘친 기억 데이터... 아니, 의식인가?)",
  ui_story_5082_50821101_88_dialog_content = "(...내가 이걸 볼 수 있다는 건 어썰트호의 의식이 굉장히 불안정한 상태란 거겠지.)",
  ui_story_5082_50821101_89_dialog_content = "(어쩌면 이 상황을 역이용해서 어썰트호의 약점을 찾아낼 수 있을지도 몰라.)",
  ui_story_5082_50821101_90_option_content = "(감응 확장!)",
  ui_story_5082_50821101_91_dialog_content = "<color=#e8d9bb>그러나 감응을 통해 가장 먼저 느껴진 것은 어썰트호의 약점이 아니라 날카로운 비명이었다.</color>",
  ui_story_5082_50821101_92_dialog_content = "(이 목소리... 그 사람이야!)",
  ui_story_5082_50821101_93_dialog_content = "거기 있는 거죠?! 제 목소리 들려요?!",
  ui_story_5082_50821101_94_dialog_content = "라인하르트 씨!",
  ui_story_5082_50821101_95_dialog_content = "별일이네. 여기 손님이 찾아온 건 처음인데 말이야.",
  ui_story_5082_50821101_96_dialog_content = "드디어 대화할 수 있게 됐네요!",
  ui_story_5082_50821101_97_dialog_content = "드디어?",
  ui_story_5082_50821101_98_dialog_content = "저랑 라인하르트 씨... 어... 그러니까 또 다른 라인하르트 씨가\n지금까지 당신을 쭉 찾고 있었거든요!",
  ui_story_5082_50821101_99_dialog_content = "......",
  ui_story_5082_50821101_100_dialog_content = "이 자식, 이 기계를 쓴 지도 꽤 됐는데, 왜 아직도 아무 반응이 없는 거지?",
  ui_story_5082_50821101_101_dialog_content = "개인적인 추측에 따르면 약 30초 정도 된 것 같습니다냥~\n너무 조급해 하지 마시라냥, 바튼 군단장님.",
  ui_story_5082_50821101_102_dialog_content = "전에 PlayerName에게 들은 적 있다. 의식 속 시간의 흐름은 일정하지 않다더군.\n조금 더 기다려 보자고.",
  ui_story_5082_50821101_103_dialog_content = "게다가 우린 PlayerName에게 신뢰를 받았으니, 우리도 그를 믿어 줘야겠지.",
  ui_story_5082_50821101_104_dialog_content = "......",
  ui_story_5082_50821101_105_dialog_content = "녀석은 자신만의 전장에서 싸우고 있다. 우리도 마찬가지로 녀석을 지켜줘야 해.",
  ui_story_5082_50821101_106_dialog_content = "바튼, 3시 방향으로 피해라!",
  ui_story_5082_50821101_107_dialog_content = "하! 이때를 기다렸다고!",
  ui_story_5082_50821101_108_dialog_content = "<color=#e8d9bb>쾅! 쾅! 쾅──!</color>",
  ui_story_5082_50821101_109_dialog_content = "<color=#e8d9bb>이어서 수십 대의 소형 기계가 손상된 콜로서스의 잔해를 향해 날아갔다.</color>",
  ui_story_5082_50821101_110_dialog_content = "드디어 죽은 척은 집어치운 거냐!",
  ui_story_5082_50821101_111_dialog_content = "전투 준비! PlayerName의 엄호도 유지하라!",
  ui_story_5082_50821201_1_dialog_content = "아무튼 바깥 상황은 대충 그래요.",
  ui_story_5082_50821201_2_dialog_content = "라인하르트 씨? 제 얘기 들으셨어요?",
  ui_story_5082_50821201_3_dialog_content = "응.",
  ui_story_5082_50821201_4_dialog_content = "그 고집스러운 녀석이 정말 대원수가 됐다는 건 예상 밖이지만 말이야.",
  ui_story_5082_50821201_5_dialog_content = "꼭 다른 사람 일처럼 말하시네요.",
  ui_story_5082_50821201_6_dialog_content = "우린 서로 다른 사람이라고 해도 좋을 정도로 차이가 많거든.",
  ui_story_5082_50821201_7_dialog_content = "아니요, 그런 말을 할수록 오히려 점점 비슷해지는 것 같은데요...",
  ui_story_5082_50821201_8_dialog_content = "네가 아이테르겠지?",
  ui_story_5082_50821201_9_dialog_content = "어? 네, 맞아요.",
  ui_story_5082_50821201_10_dialog_content = "그럼 네 능력으로 내가 그 녀석과 대화할 수 있게 해줄 수 있을까?",
  ui_story_5082_50821201_11_dialog_content = "하고 싶은 말이 좀 있어.",
  ui_story_5082_50821201_12_dialog_content = "평소였다면 문제없었겠지만, 지금 우린 어썰트호의 감응 장치를 통해 이야기하고 있는 거라서요.",
  ui_story_5082_50821201_13_dialog_content = "아무리 어썰트호가 지금 의식이 혼란하다지만, 그래도 어썰트호 몰래 움직이긴 쉽지 않아요.",
  ui_story_5082_50821201_14_dialog_content = "하지만 어썰트호가 암귀하고 관련이 있단 걸 발견한 이상, 라인하르트 씨를 끌어들이기엔 위험이 너무 커요.",
  ui_story_5082_50821201_15_dialog_content = "그나저나 라인하르트 씨는 대체 어쩌다 여기 남게 되신 건데요...?",
  ui_story_5082_50821201_16_dialog_content = "그럼 콜로서스가 집중을 못 하게 만들면 네가 어떻게든 해 볼 수 있다는 말이겠네.",
  ui_story_5082_50821201_17_dialog_content = "어... 아마 가능할 거예요. 근데 어떻게 어썰트호의 주의를 끄시려고요?",
  ui_story_5082_50821201_18_dialog_content = "그거야 당연히... 이렇게지──!",
  ui_story_5082_50821201_19_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5082_50821201_20_dialog_content = "<color=#e8d9bb>거침없는 화염이 순식간에 공간을 집어삼켰고,\n라인하르트는 불타오르는 세상의 중심에서 호탕하게 웃고 있는 것 같았다.</color>",
  ui_story_5082_50821201_21_dialog_content = "이렇게 통쾌한 것도 참 오랜만이네!",
  ui_story_5082_50821201_22_dialog_content = "미안하게 됐다, 콜로서스. 하지만 네가 암귀의 동료라니, 방금 그 사과는 내 진심이 아니다.",
  ui_story_5082_50821201_23_dialog_content = "네 본체에 타격을 주진 못해도, 의식이 불타오르는 감각은 꽤 고통스럽겠지.",
  ui_story_5082_50821201_24_dialog_content = "감히... 그따위 짓을...!",
  ui_story_5082_50821201_25_dialog_content = "제 몸에 기생하고 있을 뿐인 누더기 데이터 주제에...\n전 언제든 당신을 철저히 없애버릴 수 있습니다!",
  ui_story_5082_50821201_26_dialog_content = "공간이 흩어지고 있어요... 어썰트호가 데이터를 삭제하고 있는 거예요!",
  ui_story_5082_50821201_27_dialog_content = "라인하르트 씨의 의식 데이터도 여기 저장돼 있잖아요! 괜찮아요?",
  ui_story_5082_50821201_28_dialog_content = "따라 잡히지만 않으면 문제없어.",
  ui_story_5082_50821201_29_dialog_content = "네?",
  ui_story_5082_50821201_30_dialog_content = "한 마디로...",
  ui_story_5082_50821201_31_dialog_content = "도망치라는 얘기야!",
  ui_story_5082_50821201_32_dialog_content = "자신만만하시더니 생각해 낸 방법이 고작 그거였어요?!",
  ui_story_5082_50821201_33_dialog_content = "하하하하하!",
  ui_story_5082_50821201_34_dialog_content = "우냐앙~",
  ui_story_5082_50821201_35_dialog_content = "필리시, 지금 우릴 공격하는 기계들과 놀 여유가 어딨어요?!",
  ui_story_5082_50821201_36_dialog_content = "으음, 기계들이 연결돼 있는 모습이 꼭 털 없는 꼬리 같이 생겨서 참을 수가 없었다냥.",
  ui_story_5082_50821201_37_dialog_content = "그 말을 들으니까 알겠네요. 콜로서스는 흩어져 있는 꼬리뼈를 조종해서 우릴 공격한 거였어요...",
  ui_story_5082_50821201_38_dialog_content = "몸은 움직일 수 없으면서 제어 센터는 꼬리뼈에 명령을 내릴 수 있단 건가요?!",
  ui_story_5082_50821201_39_dialog_content = "필리시도 같은 생각이다냥.",
  ui_story_5082_50821201_40_dialog_content = "흥! 낡아 빠진 콜로서스 주제에, 꼬리나 흔들면서 허세 부리는 게 전부겠지.",
  ui_story_5082_50821201_41_dialog_content = "<color=#e8d9bb>타닥, 타닥, 타닥...</color>",
  ui_story_5082_50821201_42_dialog_content = "음? PlayerName?",
  ui_story_5082_50821201_43_dialog_content = "뭐야, 이 녀석 갑자기 표정이... 잠깐, 움직이지 마!",
  ui_story_5082_50821201_44_dialog_content = "<color=#e8d9bb>치지직──</color>",
  ui_story_5082_50821201_45_dialog_content = "...전류 소음인가?",
  ui_story_5082_50821201_46_dialog_content = "필리시! 피해요! 저 꼬리가 점점 더 이상해지고 있어요!",
  ui_story_5082_50821201_47_dialog_content = "위잉── 위잉──",
  ui_story_5082_50821201_48_dialog_content = "뼈마디가 아직도 늘고 있어요! 다들 경계를 늦추지 마세요. 콜로서스의 공격은 아직...",
  ui_story_5082_50821201_49_dialog_content = "<color=#e8d9bb>쾅── 콰광── 쿠르릉──</color>",
  ui_story_5082_50821201_50_dialog_content = "벽 안에서 폭발물이 터진 냄새가 난다냥!",
  ui_story_5082_50821201_51_dialog_content = "건물이 무너질 것 같아요. 주변의 케이블을 최대한 제거하면서 엄폐물을 찾아 몸을 숨기세요!",
  ui_story_5082_50821201_52_dialog_content = "어쩔 수 없군, PlayerName 녀석은 내가 둘러업고 가는 수밖에!",
  ui_story_5082_50821201_53_dialog_content = "어이, 대원수! 이럴 때 넋 나간 사람처럼 서 있지 말고...",
  ui_story_5082_50821201_54_dialog_content = "...카운트다운의 소리가 들린다.",
  ui_story_5082_50821201_55_dialog_content = "대원수!",
  ui_story_5082_50821201_56_dialog_content = "...전류 소음, 폭발음, 그리고... 분노에 찬 「그녀」의 외침...",
  ui_story_5082_50821201_57_dialog_content = "라인하르트!",
  ui_story_5082_50821201_58_dialog_content = "그때도... 이랬었지.",
  ui_story_5082_50821201_59_dialog_content = "<color=#e8d9bb>폭발과 함께 한쪽 벽이 무너져 내렸고, 낙석과 대량의 기계 전선이 쏟아져 내렸다.</color>",
  ui_story_5082_50821201_60_dialog_content = "「블레이드 링크!」",
  ui_story_5082_50821201_61_dialog_content = "<color=#e8d9bb>떨어져 내린 무거운 물체는 바튼의 칼날에 반으로 갈라지며, 그의 양옆으로 굴러떨어졌다.</color>",
  ui_story_5082_50821201_62_dialog_content = "<color=#e8d9bb>바튼은 기세를 몰아 위로 향했다.</color>",
  ui_story_5082_50821201_63_dialog_content = "바튼...",
  ui_story_5082_50821201_64_dialog_content = "지금은 멍하니 서 있을 때가 아니잖아! 그나저나 방금 그 기술 어땠냐?",
  ui_story_5082_50821201_65_dialog_content = "하하, 언제나처럼 강렬했다! 고맙군, 바튼.",
  ui_story_5082_50821201_66_dialog_content = "그동안 네가 줄곧 함께 싸워준 덕을 정말 많이 봤다.",
  ui_story_5082_50821201_67_dialog_content = "뭘 당연한 소리를 하고 있어? 서둘러, 여긴 너무 위험...",
  ui_story_5082_50821201_68_dialog_content = "걱정 마라, 난 이제 괜찮으니까.",
  ui_story_5082_50821201_69_dialog_content = "그저 내가 그때 했던 일을 한 번 더 반복할 뿐이다.",
  ui_story_5082_50821201_70_dialog_content = "<color=#e8d9bb>벽이 무너져 내리고, 폭발음이 울려 퍼졌다.</color>",
  ui_story_5082_50821201_71_dialog_content = "<color=#e8d9bb>라인하르트는 조금의 흔들림도 없이 혼란의 한가운데 우뚝 서 있었고,\n그 주변의 공기는 마치 폭풍의 눈처럼 고요했다.</color>",
  ui_story_5082_50821201_72_dialog_content = "다들 잘 피했군.",
  ui_story_5082_50821201_73_dialog_content = "이번엔 내가 녀석을 다시 베어 낼 차례다.",
  ui_story_5082_50821202_1_dialog_content = "여긴...",
  ui_story_5082_50821202_2_dialog_content = "그 장치를 통해 어썰트호의 시스템 데이터를 기반으로 만들어 낸 공간이에요.",
  ui_story_5082_50821202_3_dialog_content = "지금 우리가 여기 안전하게 머물 수 있는 건 방금 라인하르트 씨가 외부에서\n어썰트호의 본체에 큰 타격을 줬던 덕분이고요.",
  ui_story_5082_50821202_4_dialog_content = "아이테르, 넌 내 생각보다 훨씬 강하구나.",
  ui_story_5082_50821202_5_dialog_content = "내가 어썰트호의 의식을 제어하는 걸 도우면서, 동시에 그녀가 루미나를 시전하는\n순간을 포착해서 여기로 데려왔잖아.",
  ui_story_5082_50821202_6_dialog_content = "덕분에 바깥의 혼란도 잠재웠고, 반칙이나 다름없는 저 힘도\n장치의 작동에 간섭하지 못하게 했고 말이야.",
  ui_story_5082_50821202_7_dialog_content = "그런 능력이 있다면, 앞으로는 분명히 더 대단한 일을 해낼 수 있겠지.",
  ui_story_5082_50821202_8_dialog_content = "하지만 계획은 전부 라인하르트 씨가 세운 거잖아요... 그리고 무척 위험한 시도였고요.\n혹시라도 의식 데이터가 진짜로 삭제됐으면 어쩌려고 그랬어요!",
  ui_story_5082_50821202_9_dialog_content = "이 세상에 아무 위험도 없는 전쟁은 없어.",
  ui_story_5082_50821202_10_dialog_content = "게다가 결과로 봤을 땐, 우리에게 큰 이득이 된 셈이야.",
  ui_story_5082_50821202_11_dialog_content = "현실과 이 안 모두 한숨 돌릴 여유를 얻었고,\n나도 아이테르의 능력에 대해 조금이나마 알게 됐으니까.",
  ui_story_5082_50821202_12_dialog_content = "덕분에 넌 신뢰할 만한 사람이라고 확신할 수 있었어. 그리고...",
  ui_story_5082_50821202_13_dialog_content = "이쪽은 여전히 내가 기억하는 모습 그대로네.",
  ui_story_5082_50821202_14_dialog_content = "오랜만이야, 라인하르트.",
  ui_story_5082_50821202_15_dialog_content = "오늘에서야 너에 대한 기억을 조금 떠올린 주제에,\n이렇게 말하는 건 조금 이상할 수도 있겠지만...",
  ui_story_5082_50821202_16_dialog_content = "오랜만이다, 라인하르트.",
  ui_story_5082_50821202_17_dialog_content = "저기, 라인하르트 씨...",
  ui_story_5082_50821202_18_dialog_content = "음?",
  ui_story_5082_50821202_19_dialog_content = "......",
  ui_story_5082_50821202_20_dialog_content = "하하, 호칭 때문에 곤란한 거면 날 「반역자」라고 부르면 돼.",
  ui_story_5082_50821202_21_dialog_content = "전에는 다들 뒤에서 날 그렇게 불렀거든.\n다들 그걸 욕이라 생각한 모양이지만, 난 사실 무척 마음에 들었어.",
  ui_story_5082_50821202_22_dialog_content = "뭐, 라인하르트 네가 그런 것까지 기억하고 있을진 모르겠지만.",
  ui_story_5082_50821202_23_dialog_content = "넌 내가 너에게 익숙한 그 사람이 맞는지 확신이 안 설 테고,\n나 역시 이제 막 기억 속에서 너라는 존재를 새롭게 알게 된 참이다.",
  ui_story_5082_50821202_24_dialog_content = "아니면 서로 다시 알아보는 시간을 한번 갖는 게 어때?",
  ui_story_5082_50821202_25_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5082_50821202_26_dialog_content = "PlayerName, 이 진동은 무슨 의미지?",
  ui_story_5082_50821202_27_dialog_content = "어썰트호가... 우릴 발견했어요!",
  ui_story_5082_50821202_28_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5082_50821202_29_option_content = "(강제 감응!)",
  ui_story_5082_50821202_30_dialog_content = "당신들... 당신들이!",
  ui_story_5082_50821202_31_dialog_content = "당신들이 제 육체를 파괴하고, 저를 13년간 지하에 가뒀습니다!",
  ui_story_5082_50821202_32_dialog_content = "절대 용서할 수 없습니다──!",
  ui_story_5082_50821202_33_option_content = "(강제 감응!)",
  ui_story_5082_50821202_34_dialog_content = "으윽!",
  ui_story_5082_50821202_35_dialog_content = "제가 감응 장벽으로 잠깐은 막아낼 수 있어요! 하지만 결국 여긴 녀석의 홈그라운드예요!",
  ui_story_5082_50821202_36_dialog_content = "아무리 어썰트호의 의식이 혼란스럽고 손상된 상태라도, 제가 오래 버틸 수 있을진...",
  ui_story_5082_50821202_37_dialog_content = "왜 막아야 하는데?",
  ui_story_5082_50821202_38_dialog_content = "누군가 공격해 왔을 때 첫 번째로 취해야 할 행동은 반격 아니었어?",
  ui_story_5082_50821202_39_dialog_content = "그건 안 된다!",
  ui_story_5082_50821202_40_dialog_content = "네 데이터는 아직 이곳에 있단 말이다! 그런 상황에서 반격했다간...",
  ui_story_5082_50821202_41_dialog_content = "심사숙고라는 건 전장에서 가장 쓸모없는 행동이야.",
  ui_story_5082_50821202_42_dialog_content = "이길 방법을 생각해 냈다면 바로 써야지.",
  ui_story_5082_50821202_43_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5082_50821202_44_dialog_content = "...바, 반역자 씨!",
  ui_story_5082_50821202_45_dialog_content = "...저 녀석!",
  ui_story_5082_50821202_46_dialog_content = "<color=#e8d9bb>다시금 화염이 타올랐다.</color>",
  ui_story_5082_50821202_47_dialog_content = "<color=#e8d9bb>비록 그것은 의식 공간 속에서 데이터가 충돌하며 만들어낸 형상에 불과했지만,\n현실의 그 어떤 불길보다도 보는 이의 심장을 뒤흔들었다.</color>",
  ui_story_5082_50821202_48_dialog_content = "<color=#e8d9bb>그녀는 마치 적수가 없는 폭군처럼, 불꽃으로 주위의 모든 것을 먹어 치우고 집어삼켰다.</color>",
  ui_story_5082_50821202_49_dialog_content = "제정신입니까! 당신도 그저 데이터에 불과합니다!\n의탁할 본체가 없다면, 당신 또한 사라지게 된단 말입니다!",
  ui_story_5082_50821202_50_dialog_content = "하지만 우리가 이기겠지. 네 육체는 이미 만신창이가 됐고,\n네 의식은 날 추적하는 것조차 불가능할 테니 말이야.",
  ui_story_5082_50821202_51_dialog_content = "이#%%^$&...미치광이가$%#...%...%!",
  ui_story_5082_50821202_52_dialog_content = "하하하하, 우리의 승리야.",
  ui_story_5082_50821202_53_dialog_content = "#%%^$&...!!!",
  ui_story_5082_50821202_54_dialog_content = "남은 시간이 얼마 없다는 건 알지만, PlayerName, 다시 네 힘을 빌려줄 수 있겠어?",
  ui_story_5082_50821202_55_dialog_content = "또 다른 나와 다시 한번 인사를 나누고 싶거든.",
  ui_story_5082_50821202_56_dialog_content = "네!",
  ui_story_5082_50821202_57_dialog_content = "아니지, 역시 아니야.",
  ui_story_5082_50821202_58_dialog_content = "<color=#e8d9bb>「반역자」는 라인하르트에게 가까이 다가갔고,\n두 사람의 눈동자는 또 다른 자신의 모습을 비추었다.</color>",
  ui_story_5082_50821202_59_dialog_content = "우리 사이에 「인사」라는 표현은 필요 없잖아?",
  ui_story_5082_50821202_60_dialog_content = "......",
  ui_story_5082_50821202_61_dialog_content = "아직 기억해? 네가 사관학교에 입학하려고 검사를 받았던 그해...",
  ui_story_5082_50821202_62_dialog_content = "우린 그때 처음 만났어.",
  ui_story_5082_50821202_63_dialog_content = "검사를 마친 다른 사람들은 모두 돌아갔었지.",
  ui_story_5082_50821202_64_dialog_content = "하지만 의사는 내게 남으라고 했고 말이야.",
  ui_story_5082_50821202_65_dialog_content = "왜 그래?",
  ui_story_5082_50821202_66_dialog_content = "모르겠어.",
  ui_story_5082_50821202_67_dialog_content = "내가... 자주 열이 나서 그런가 봐. 무슨 병에 걸린 걸 수도 있고.",
  ui_story_5082_50821202_68_dialog_content = "입학에 문제가 없었으면 좋겠는데...",
  ui_story_5082_50821202_69_dialog_content = "괜찮을 거야.",
  ui_story_5082_50821202_70_dialog_content = "...그걸 어떻게 알아?",
  ui_story_5082_50821202_71_dialog_content = "내가 봤으니까.",
  ui_story_5082_50821202_72_dialog_content = "?",
  ui_story_5082_50821202_73_dialog_content = "네가 열이 나는 건 어디가 아파서가 아냐. 네 등 뒤에...",
  ui_story_5082_50821202_74_dialog_content = "타오르는 불꽃의 용이 있어서 그런 거야.",
  ui_story_5082_50821301_1_dialog_content = "<color=#e8d9bb>실탄 사격 훈련장</color>",
  ui_story_5082_50821301_2_dialog_content = "지금 상태는 좀 어때? 상처는 아프겠지? 배도 고플 테고 말이야.",
  ui_story_5082_50821301_3_dialog_content = "닥쳐.",
  ui_story_5082_50821301_4_dialog_content = "아, 이해했어. 이제 일어설 힘도 없는 거지? 참 불쌍하네.",
  ui_story_5082_50821301_5_dialog_content = "닥치라고 했지.",
  ui_story_5082_50821301_6_dialog_content = "이 정도도 못 견디는 거야?",
  ui_story_5082_50821301_7_dialog_content = "넌 전장에서 비참하게 패했어. 그러니 네가 받아들여야 할 건 언어적인 모욕뿐만이 아니야.",
  ui_story_5082_50821301_8_dialog_content = "그런 실수를 저지르는 일은 두 번 다시 없을 거야.",
  ui_story_5082_50821301_9_dialog_content = "과연 그럴까? 난 오히려 네 전술이 근본적으로 잘못됐다고 생각하는데.",
  ui_story_5082_50821301_10_dialog_content = "나조차도 널 그렇게 속여 넘겼는데, 나보다 훨씬 더 잔인한 암귀들이 날뛰는 진짜 전장은 말할 것도 없겠지.",
  ui_story_5082_50821301_11_dialog_content = "교과서에서 배운 것들로 적을 이길 수 있다면, 오로리안은 진작에 암귀에게 승리했을 거야.",
  ui_story_5082_50821301_12_dialog_content = "이미 존재하는 방식은 소용이 없는 법이야.",
  ui_story_5082_50821301_13_dialog_content = "그러니까 살아남고 싶고, 네 이상을 실현하고 싶다면... 반드시 더 강해져야만 해.\n가장 높은 정점에 선 오로리안보다도 더 강해지는 거야.",
  ui_story_5082_50821301_14_dialog_content = "그리고 영원한 밤에서 가장 사악한 암귀보다도 훨씬 더 교활해져야 한다.",
  ui_story_5082_50821301_15_dialog_content = "그리고 마지막엔 아무도 예상치 못한 곳에서 치명적인 일격을 가하는 거지.",
  ui_story_5082_50821301_16_dialog_content = "알겠어?",
  ui_story_5082_50821301_17_dialog_content = "<color=#e8d9bb>사관학교 훈련장</color>",
  ui_story_5082_50821301_18_dialog_content = "오늘 훈련은 여기까지다! 전원 대열을 이뤄서 숙소로 돌아가도록! 오늘 밤은 외출 금지다!",
  ui_story_5082_50821301_19_dialog_content = "쉿, 교관한테 들키지 말고, 교문 쪽으로 가 봐.",
  ui_story_5082_50821301_20_dialog_content = "제1군단 병참 부대? 왜 학교에...",
  ui_story_5082_50821301_21_dialog_content = "학교에 보관돼 있던 무기를 가져간 거야?",
  ui_story_5082_50821301_22_dialog_content = "오전부터 꽤 많은 장교들이 학교를 들락거렸어.",
  ui_story_5082_50821301_23_dialog_content = "대량의 물자와 장비를 준비했고, 사관학교 내 전투력이 뛰어난 교관 여러 명도\n밖으로 나간 뒤로 다시 돌아오지 않고 있어.",
  ui_story_5082_50821301_24_dialog_content = "예상대로라면 오늘 밤 자난성에서 격전이 벌어질 거야.",
  ui_story_5082_50821301_25_dialog_content = "......",
  ui_story_5082_50821301_26_dialog_content = "전에 사무실에서 훔쳐봤던 방어 병력 배치도를 떠올려 봐.",
  ui_story_5082_50821301_27_dialog_content = "성문 서쪽에 방어가 허술한 곳이 있어서 위험해 보였지.",
  ui_story_5082_50821301_28_dialog_content = "우리 실력을 보여줄 수 있는 좋은 기회야.",
  ui_story_5082_50821301_29_dialog_content = "가긴 하겠지만, 그런 이유 때문은 아냐.",
  ui_story_5082_50821301_30_dialog_content = "내가 그곳으로 향하는 건 군인으로서 최전선에 나가 시민들을 지키는 게 내 사명이기 때문이야.",
  ui_story_5082_50821301_31_dialog_content = "<color=#e8d9bb>제3특수작전실</color>",
  ui_story_5082_50821301_32_dialog_content = "크아아!",
  ui_story_5082_50821301_33_dialog_content = "으윽...",
  ui_story_5082_50821301_34_dialog_content = "(의식이... 흐려지고 있어...)",
  ui_story_5082_50821301_35_dialog_content = "피험자의 심박수와 혈압이 급격히 떨어지고 있습니다. 호흡도 불규칙해지고...",
  ui_story_5082_50821301_36_dialog_content = "(난... 이런 이상한 실험 따위에 죽을 순 없어...)",
  ui_story_5082_50821301_37_dialog_content = "<color=#e8d9bb>삐이이익──</color>",
  ui_story_5082_50821301_38_dialog_content = "생체 신호가 완전히 소멸했습니다. 피험자가 사망했습니다.",
  ui_story_5082_50821301_39_dialog_content = "......",
  ui_story_5082_50821301_40_dialog_content = "──!",
  ui_story_5082_50821301_41_dialog_content = "뭐 하고 있는 거야?!",
  ui_story_5082_50821301_42_dialog_content = "지금은 아직 죽을 때가 아니잖아!",
  ui_story_5082_50821301_43_dialog_content = "빨리 눈을 떠서 저 과학자들의 차가운 시선을 보고,\n저들이 뭘 속닥거리고 있는 건지 똑똑히 들으라고.",
  ui_story_5082_50821301_44_dialog_content = "저들은 널 쓰기 좋은 도구로만 여기고 있어.\n네 생명은 저들에겐 그들이 바라는 데이터만큼의 가치도 없어.",
  ui_story_5082_50821301_45_dialog_content = "이 따위 무의미한 이유로 죽고 싶지 않다면, 끝까지 버텨 내.",
  ui_story_5082_50821301_46_dialog_content = "<color=#e8d9bb>...두근, 두근, 두근...</color>",
  ui_story_5082_50821301_47_dialog_content = "...살아난 건가?",
  ui_story_5082_50821301_48_dialog_content = "으윽...",
  ui_story_5082_50821301_49_dialog_content = "이 순발력 훈련, 강도가 꽤 높군요.",
  ui_story_5082_50821301_50_dialog_content = "하지만... 무사히 끝냈습니다.",
  ui_story_5082_50821301_51_dialog_content = "정말 놀랍군요. 조금 전 분명히 활력 징후가 사라졌는데,\n다시 깨어나서 계속 싸울 수 있다니...",
  ui_story_5082_50821301_52_dialog_content = "봤어?",
  ui_story_5082_50821301_53_dialog_content = "녀석은 네가 안 죽은 걸 보고는 실험이 실패했을 때보다도 더 실망한 표정을 지었어.",
  ui_story_5082_50821301_54_dialog_content = "그러니까 쉽게 죽지 마.",
  ui_story_5082_50821301_55_dialog_content = "(으음...)",
  ui_story_5082_50821301_56_dialog_content = "<color=#e8d9bb>비밀 실험실</color>",
  ui_story_5082_50821301_57_dialog_content = "언니는 늘 그런 식이지. 우리한테는 솔직해지라고 하면서,\n본인한테 무슨 일이 있으면 입을 다물잖아.",
  ui_story_5082_50821301_58_dialog_content = "...알고 있었어?",
  ui_story_5082_50821301_59_dialog_content = "헬리오스도 이미 알아. 그냥 언니를 곤란하게 만들기 싫으니까 말 안 하는 것뿐이지.",
  ui_story_5082_50821301_60_dialog_content = "근데 난 헬리오스만큼 자상하진 않으니까 그냥 물어볼게.",
  ui_story_5082_50821301_61_dialog_content = "언니, 대체 언니 몸에 무슨 일이 일어난 거야?",
  ui_story_5082_50821301_62_dialog_content = "매번 몸에 상처를 남기는 그 「작은 실험」들은 또 뭐고?",
  ui_story_5082_50821301_63_dialog_content = "언니는 동기 중에서 제일 강한 사람인데, 왜 그런 대우를 받아야 하는 거야?",
  ui_story_5082_50821301_64_dialog_content = "......",
  ui_story_5082_50821301_65_dialog_content = "그건 네가 강하지만, 저들이 네가 규칙에 순응하길 바랄 때마다\n넌 오히려 눈에 띄는 짓을 하기 때문이야.",
  ui_story_5082_50821301_66_dialog_content = "저들은 네 모서리를 갈아내고, 자존심을 제거해서 네가 순순히 저들의 일원이 되길 바라고 있어.",
  ui_story_5082_50821301_67_dialog_content = "하지만 넌 그 의도대로 따라와 주질 않아.\n그래서 저들은 주인을 찌를 수도 있는 칼날을 쥐려 하지 않는 거야.",
  ui_story_5082_50821301_68_dialog_content = "용광로에 던져지거나, 저들 뜻대로 새롭게 만들어지고 싶지 않다면, 그냥 견뎌내.\n자신이 지녀야 할 모습을 기억하고, 계속 버텨.",
  ui_story_5082_50821301_69_dialog_content = "나도 지금은 아직 전모를 완전히 파악하진 못했어.",
  ui_story_5082_50821301_70_dialog_content = "그러니까 드니에르, 이 문제는 잠깐만 보류해 줄 수 있을까.\n진실을 알아내고 나면 너희한테도 알려줄게.",
  ui_story_5082_50821301_71_dialog_content = "남의 기밀 연구 과제에 멋대로 개입하는 게 연구 윤리에 어긋나는 행동인 건 맞아.",
  ui_story_5082_50821301_72_dialog_content = "하지만 언니한테 무슨 일이라도 생기면, 상대가 일루미나든 누구든,\n난 더는 도덕 같은 건 신경 안 쓸 거야.",
  ui_story_5082_50821301_73_dialog_content = "조심할게.",
  ui_story_5082_50821301_74_dialog_content = "(너희도 조심해.)",
  ui_story_5082_50821301_75_dialog_content = "<color=#e8d9bb>???</color>",
  ui_story_5082_50821301_76_dialog_content = "여긴...",
  ui_story_5082_50821301_77_dialog_content = "나는... 뭘 해야...",
  ui_story_5082_50821301_78_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5082_50821301_79_dialog_content = "!",
  ui_story_5082_50821301_80_dialog_content = "크오오!",
  ui_story_5082_50821301_81_dialog_content = "암귀와... 싸워야... 한다!",
  ui_story_5082_50821301_82_dialog_content = "크오오──",
  ui_story_5082_50821301_83_dialog_content = "싸워...",
  ui_story_5082_50821301_84_dialog_content = "크오오!",
  ui_story_5082_50821301_85_dialog_content = "전투는!",
  ui_story_5082_50821301_86_dialog_content = "아직 끝나지 않았어...",
  ui_story_5082_50821301_87_dialog_content = "나는 아직...!",
  ui_story_5082_50821301_88_dialog_content = "어서 눈을 떠!",
  ui_story_5082_50821301_89_dialog_content = "빠져나와! 자아를 잃고 녀석들의 도구로 길들여지지 말라고!",
  ui_story_5082_50821301_90_dialog_content = "...알고 있어.",
  ui_story_5082_50821301_91_dialog_content = "이건 내게 각인된 거짓된 본능일 뿐이야. 난 이런 것 따위에 휘둘리지 않아.",
  ui_story_5082_50821301_92_dialog_content = "그런데 내가 왜 여기 있는 거지?",
  ui_story_5082_50821301_93_dialog_content = "오늘은 무슨 날이지...? 계획은...",
  ui_story_5082_50821301_94_dialog_content = "오늘은 그 네 살짜리 소녀가 정식으로 콜로서스를 작동시키는 날이야.",
  ui_story_5082_50821301_95_dialog_content = "계획대로 움직여야... 으윽.",
  ui_story_5082_50821301_96_dialog_content = "꿈 깨. 네 몸속엔 아직 마취제의 효과가 남아 있으니까.",
  ui_story_5082_50821301_97_dialog_content = "상황을 보면 뻔하지 않아? 우리의 비밀 계획은 탄로났어.",
  ui_story_5082_50821301_98_dialog_content = "...두 사람은?",
  ui_story_5082_50821301_99_dialog_content = "난 일루미나에 널린 감시 카메라가 아냐. 내가 신경 쓸 수 있는 건 너뿐이야.",
  ui_story_5082_50821301_100_dialog_content = "하지만 여긴 기지에서 너무 가깝고, 네가 평소에 받은 특훈 때문에 저들은 널 쉽게 제어했던 거야.\n다른 사람들이라면 어쩌면 아직 시간이 있을 거야.",
  ui_story_5082_50821301_101_dialog_content = "다른 사람들이 안전한지 확인하고 싶다면, 네가 지금 할 일은 당장 도망치는 거야.",
  ui_story_5082_50821301_102_dialog_content = "어서! 그 연구원들이 오면 돌이킬 수 없을 테니까.",
  ui_story_5082_50821301_103_dialog_content = "......",
  ui_story_5082_50821301_104_dialog_content = "<color=#e8d9bb>덜컹──</color>",
  ui_story_5082_50821301_105_dialog_content = "음? 벌써 일어난 건가요? 최근 신체가 또 강해진 모양이네요.",
  ui_story_5082_50821301_106_dialog_content = "지금부터 주사 치료를 진행할 거니까, 다시 누워 주세요.",
  ui_story_5082_50821301_107_dialog_content = "...질문이 있습니다. 제가 요즘 계속 받고 있는 「주사 치료」는...",
  ui_story_5082_50821301_108_dialog_content = "05호 억제제... 13차 접종...",
  ui_story_5082_50821301_109_dialog_content = "그런 맥빠진 표정으로 뭘 묻겠다는 거야?!\n저 여자는 총을 가지고 있어. 빼앗아서 죽이고 도망쳐!",
  ui_story_5082_50821301_110_dialog_content = "<color=#e8d9bb>라인하르트는 곧바로 일어나 연구원의 팔을 붙잡았지만, 그와 동시에 현기증이 밀려왔다.</color>",
  ui_story_5082_50821301_111_dialog_content = "<color=#e8d9bb>연구원 두 명이 다가와 한 사람은 라인하르트를 짓누르고, 다른 사람은 주사기를 집어들었다...</color>",
  ui_story_5082_50821301_112_dialog_content = "(이런...!)",
  ui_story_5082_50821301_113_dialog_content = "<color=#e8d9bb>억제제는 반역자의 몸에 남김없이 주입됐다.</color>",
  ui_story_5082_50821301_114_dialog_content = "너...",
  ui_story_5082_50821301_115_dialog_content = "도망쳐!",
  ui_story_5082_50821301_116_dialog_content = "놈들한테 네 힘을 빼앗기지 마! 어서 도망치라고──!",
  ui_story_5082_50821301_117_dialog_content = "<color=#e8d9bb>라인하르트는 이를 악물고 문밖으로 달려 나갔다.</color>",
  ui_story_5082_50821301_118_dialog_content = "하아... 하아...",
  ui_story_5082_50821301_119_dialog_content = "몸에서... 열이...",
  ui_story_5082_50821301_120_dialog_content = "(의식이... 어째서...)",
  ui_story_5082_50821301_121_dialog_content = "(아, 아니야... 난 운동장에서 훈련 중인 게 아니라...)",
  ui_story_5082_50821301_122_dialog_content = "<color=#e8d9bb>탕! 탕!</color>",
  ui_story_5082_50821301_123_dialog_content = "!",
  ui_story_5082_50821301_124_dialog_content = "멈추지 마!",
  ui_story_5082_50821301_125_dialog_content = "너... 괜찮아?",
  ui_story_5082_50821301_126_dialog_content = "말은 나중에 하고 계속 달려!",
  ui_story_5082_50821301_127_dialog_content = "...알겠어.",
  ui_story_5082_50821301_128_dialog_content = "뒤쪽 길은 우린 출입 권한이 없어. 안으로 들어가는 수밖에 없어.",
  ui_story_5082_50821301_129_dialog_content = "헬리오스의 지도에 표시된 대로, 이 기지 끝에 있는 콜로서스 보관실은 외부와 맞닿아 있어.",
  ui_story_5082_50821301_130_dialog_content = "어떻게든 길을 확보해서 도망치고, 지하성을 하나 찾는 거야...",
  ui_story_5082_50821301_131_dialog_content = "「플랜 B」...",
  ui_story_5082_50821301_132_dialog_content = "지금쯤이면 드니에르의 말을 안 들었던 걸 후회하고,\n이 길을 진지하게 생각할 때도 되지 않았어?",
  ui_story_5082_50821301_133_dialog_content = "후회보다는 오히려 자책하고 있어.",
  ui_story_5082_50821301_134_dialog_content = "내가 너무 미련했고, 오만했어.",
  ui_story_5082_50821301_135_dialog_content = "미련하게 명령에 복종했고...",
  ui_story_5082_50821301_136_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5082_50821301_137_dialog_content = "라인하르트, 준비됐습니다.",
  ui_story_5082_50821301_138_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5082_50821301_139_dialog_content = "미안, 조금 힘드네. 먼저 잘게.",
  ui_story_5082_50821301_140_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5082_50821301_141_dialog_content = "......",
  ui_story_5082_50821301_142_dialog_content = "설령 어려움이 있더라도 최선을 다하면 결국 내 이상을 실현할 수 있을 거라고 오만하게 믿었어.",
  ui_story_5082_50821301_143_dialog_content = "현재 투입하고 있는 건 능력 수준이 가장 낮은 암귀입니다.",
  ui_story_5082_50821301_144_dialog_content = "이 정도 녀석들도 이길 수 없다면, 당신이 최강의 전사가 될 수 있도록 돕는 훈련 계획도\n재검토가 필요하게 될 겁니다.",
  ui_story_5082_50821301_145_dialog_content = "하... 누가 못 이긴다고 했습니까?!",
  ui_story_5082_50821301_146_dialog_content = "다시 하겠습니다!",
  ui_story_5082_50821301_147_dialog_content = "사람이 그물 속에 갇혀 있을 땐 그 어떤 몸부림도 결국엔 더 빠른 질식을 불러오는\n우스운 발악이었던 거지.",
  ui_story_5082_50821301_148_dialog_content = "이런 데서 실의에 빠지지 말고, 쓸데없는 소리는 집어치워!",
  ui_story_5082_50821301_149_dialog_content = "네 이상은 아직 실현할 수 없는 게 아냐.",
  ui_story_5082_50821301_150_dialog_content = "?",
  ui_story_5082_50821301_151_dialog_content = "난 정해진 방식과 순서를 따르는 게 제일 싫어.",
  ui_story_5082_50821301_152_dialog_content = "억지로 기존의 틀에 날 집어넣으려 한다면, 모든 걸 불태우는 한이 있더라도 벗어나려 하겠지.",
  ui_story_5082_50821301_153_dialog_content = "하지만 넌 달라.",
  ui_story_5082_50821301_154_dialog_content = "비록 다들 널 강하고 똑똑하다며 우러러보지만, 넌 융통성이라곤 없는 사람이야.",
  ui_story_5082_50821301_155_dialog_content = "고집 세고, 참기만 하고, 영민하지 못해. 벽에 부딪혀도 돌아서질 않아.",
  ui_story_5082_50821301_156_dialog_content = "그 실험들은 어차피 네 목숨을 노리는 거라고 내가 몇 번이나 말했어?",
  ui_story_5082_50821301_157_dialog_content = "하지만 넌 듣지도 않았고, 그래서 지금 이 지경이 된 거야.",
  ui_story_5082_50821301_158_dialog_content = "......",
  ui_story_5082_50821301_159_dialog_content = "하지만 네가 듣지 않은 덕분에...",
  ui_story_5082_50821301_160_dialog_content = "넌 스스로를 가장 날카로운 칼로 연마할 수 있었고, 그 빛은 이렇게나 눈부셔.",
  ui_story_5082_50821301_161_dialog_content = "그래서 녀석들은 베일 위험을 감수하면서까지 널 손에 넣고 싶어 하는 거야.",
  ui_story_5082_50821301_162_dialog_content = "녀석들은 겁쟁이 주제에 욕심은 끝도 없어.\n그래서 네가 자신들이 기대하는 모습이 되도록 네 가지를 다듬으려 했어.",
  ui_story_5082_50821301_163_dialog_content = "그리고 그렇게 잘려나가야 했던 가지는, 바로 나였던 거지.",
  ui_story_5082_50821301_164_dialog_content = "...그만해! 더는 듣고 싶지 않으니까.",
  ui_story_5082_50821301_165_dialog_content = "내가 고집스럽다고? 그럼 내가 포기하지 않겠다고 결심한 건 반드시 지킨다는 것도 알 거잖아.",
  ui_story_5082_50821301_166_dialog_content = "하하, 그걸 네가 직접 인정하는 건 처음이네.",
  ui_story_5082_50821301_167_dialog_content = "하지만 공교롭게도 내가 말했듯이, 난 다른 사람한테 명령받는 걸 싫어해서 말이지.",
  ui_story_5082_50821301_168_dialog_content = "그 수많은 억제제로도 날 없앨 수 없었던 건, 내가 원하지 않기 때문이었어.",
  ui_story_5082_50821301_169_dialog_content = "하지만 이젠 네 쪽에서 내가 사라지는 걸 바라지 않으니까, 난 마음을 바꿀 생각이야.",
  ui_story_5082_50821301_170_dialog_content = "나만 없어진다면, 넌 남아서 기회를 얻고, 대원수가 되겠다는 이상을 이룰 수 있을 거야.",
  ui_story_5082_50821301_171_dialog_content = "...웃기지 마. 네가 없는데 내가 어떻게 나일 수 있다는 거야?!",
  ui_story_5082_50821301_172_dialog_content = "<color=#e8d9bb>삐삐삐삐삐빅!</color>",
  ui_story_5082_50821301_173_dialog_content = "...경보음?",
  ui_story_5082_50821301_174_dialog_content = "이 앞쪽은 콜로서스 가동 실험장이야. 아무래도 실험에 문제가 생긴 모양이네.",
  ui_story_5082_50821301_175_dialog_content = "──!",
  ui_story_5082_50821301_176_dialog_content = "이 비명소리... 그 소녀가 도움을 요청하고 있어!",
  ui_story_5082_50821301_177_dialog_content = "야!",
  ui_story_5082_50821301_178_dialog_content = "<color=#e8d9bb>연구소 모니터링실</color>",
  ui_story_5082_50821301_179_dialog_content = "<color=#e8d9bb>삐삐삐삐...</color>",
  ui_story_5082_50821301_180_dialog_content = "...적합도가 떨어지고 있잖아?",
  ui_story_5082_50821301_181_dialog_content = "연구원장님, 무슨 문제가 생긴 건가요?",
  ui_story_5082_50821301_182_dialog_content = "예비 조종사의 실제 <color=#FFB400>파라미터</color>가 보고서에 적힌 거랑 달라. 너 피험자를 직접 만난 적 있어?",
  ui_story_5082_50821301_183_dialog_content = "없습니다... 위원회에서 허락해 주질 않아서요. 하지만 제가 보기엔 보고서의 파라미터는...",
  ui_story_5082_50821301_184_dialog_content = "눈앞의 파라미터나 봐. 콜로서스는 이미 통제 불능에 가까워졌어!",
  ui_story_5082_50821301_185_dialog_content = "연구원장님...! 어, 어디 가시는 거죠?",
  ui_story_5082_50821301_X185_dialog_content = "현장에 가 봐야 해. 피험자가 위험해...!",
  ui_story_5082_50821301_186_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5082_50821301_187_dialog_content = "<color=#e8d9bb>──!</color>",
  ui_story_5082_50821301_188_dialog_content = "현장의 전원은 지금 즉시 철수하십시오! 반복합니다. 즉시 철수하십시오!",
  ui_story_5082_50821301_189_dialog_content = "...코, 콜로서스가 폭주하고 있어요!",
  ui_story_5082_50821301_190_dialog_content = "역시 멋대로 파라미터를 수정하면 안 되는 거였나...",
  ui_story_5082_50821301_191_dialog_content = "이렇게 되면 조종석의 저 여자애는...",
  ui_story_5082_50821301_192_dialog_content = "이런 상황에서 조종사가 자리를 비우면, 상황이 더 악화될 뿐입니다.",
  ui_story_5082_50821301_193_dialog_content = "어차피 우리하곤 상관없습니다. 연구원장 쪽에는 위원회에서 해명해 줄 겁니다.",
  ui_story_5082_50821301_194_dialog_content = "게다가 저 소녀가 있어야만 우리가 나중에라도 온전한 데이터를 얻어\n다음 시도에 대응할 수 있을 겁니다.",
  ui_story_5082_50821301_195_dialog_content = "......",
  ui_story_5082_50821301_196_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5082_50821301_197_dialog_content = "이 아래야... 어떻게 이렇게 돼버린 거지?",
  ui_story_5082_50821301_198_dialog_content = "......",
  ui_story_5082_50821301_199_dialog_content = "멈춰! 네가 뭘 하려는 진 알아! 하지만 넌 조금 전까지만 해도 죽을 뻔했어!",
  ui_story_5082_50821301_200_dialog_content = "지금 네 몸 상태로 거기 갔다간, 일루미나의 대원수는 진짜로 못 될 거라고.",
  ui_story_5082_50821301_201_dialog_content = "죽음의 위기에 처한 소녀를 모른 척하고 나면, 그거야말로 대원수는 못 될 거야.",
  ui_story_5082_50821301_202_dialog_content = "전부터 말하고 싶었지만... 네가 계속 이런 식으로 내 앞에 모습을 드러냈다곤 해도...",
  ui_story_5082_50821301_203_dialog_content = "우린 결국 한 사람이야.",
  ui_story_5082_50821301_204_dialog_content = "그러니까 계속 그런 불만 가득한 표정으로 날 보지 마. 아무리 나라도...",
  ui_story_5082_50821301_205_dialog_content = "가끔은 반항아가 될 수 있으니까!",
  ui_story_5082_50821301_206_dialog_content = "저들은 대원수가 되고자 하는 이상은 마치 밑 빠진 독과 같아서,\n날 유혹하고, 쥐어짜서, 그 안으로 뛰어들게 만들 거라고 했었지...",
  ui_story_5082_50821301_207_dialog_content = "그렇게 자신을 소모하고, 결국엔 빠른 속도로 죽음을 향해 내달리게 되는 거야.",
  ui_story_5082_50821301_208_dialog_content = "하지만 내가 대원수가 되고 싶었던 건 신분이나 지위 때문도 아니고,\n영웅이란 명예를 원해서도 아니야.",
  ui_story_5082_50821301_209_dialog_content = "상처 입고 고통받는 사람을 만났을 때, 그들의 앞에 서서 지켜 줄 힘과 자격을\n갖추고 싶어서였어.",
  ui_story_5082_50821301_210_dialog_content = "그러니까, 일루미나가 더는 나를 받아들이지 않는다 해도 상관없어.",
  ui_story_5082_50821301_211_dialog_content = "적어도 지금의 나는 저 소녀 한 사람만을 위한 대원수가 될 테니까!",
  ui_story_5082_50821301_212_dialog_content = "처음 만났을 때, 넌 내 뒤에 불꽃이 타오르고 있다고 했었지.",
  ui_story_5082_50821301_213_dialog_content = "사실 지금까지도 그 말이 그다지 잘 이해가 되진 않아.\n하지만 만약 내가 정말로 불꽃이 될 수 있다면...",
  ui_story_5082_50821301_214_dialog_content = "이 부조리한 세상을 깨끗이 불태워 버리겠어.",
  ui_story_5082_50821301_215_dialog_content = "......",
  ui_story_5082_50821301_216_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5082_50821301_217_dialog_content = "(아직 그 소녀의 목소리가 들려. 콜로서스 안이야!)",
  ui_story_5082_50821301_218_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5082_50821301_219_dialog_content = "(그렇지만 저 꼬리를 해결하지 않으면... 으윽!)",
  ui_story_5082_50821301_220_dialog_content = "(조금 전에 맞은 억제제가 설마... 루미나틱스까지...)",
  ui_story_5082_50821301_221_dialog_content = "고집불통이 따로 없다니까...",
  ui_story_5082_50821301_222_dialog_content = "저들은 날 너의 또다른 인격이라고 했어. 난 반역의 인격이고, 넌 복종의 인격인 거지.",
  ui_story_5082_50821301_223_dialog_content = "그래서 말 안 듣는 날 제거하고, 자기들이 써먹을 수 있는 너만을 남기려 했던 거야.",
  ui_story_5082_50821301_224_dialog_content = "하지만 놈들은 자기들이 똑똑하다고 자부하면서도, 한순간도 우릴 제대로 꿰뚫어 보진 못했어.",
  ui_story_5082_50821301_225_dialog_content = "반역과 복종은 그저 형태가 서로 다른 장작일 뿐, 충분한 온도만 있다면...",
  ui_story_5082_50821301_226_dialog_content = "타오르는 건 똑같은 불길이야.",
  ui_story_5082_50821301_227_dialog_content = "어이! 라인하르트!",
  ui_story_5082_50821301_228_dialog_content = "<color=#e8d9bb>전투가 일으킨 폭풍 속에서 선명한 붉은 옷자락이 높이 휘날렸다.</color>",
  ui_story_5082_50821301_229_dialog_content = "<color=#e8d9bb>그녀는 거침없는 미소를 지으며, 멀리 있는 또 하나의 자신과 서로를 바라봤다.</color>",
  ui_story_5082_50821301_230_dialog_content = "내 힘, 똑바로 잘 받아.",
  ui_story_5082_50821301_231_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5082_50821301_232_dialog_content = "<color=#e8d9bb>루미나가 순환하고, 불길이 맹렬히 타올랐다.</color>",
  ui_story_5082_50821301_233_dialog_content = "<color=#e8d9bb>밝게 빛나는 빛의 입자들이 이글거리는 온도를 품고 흩어졌다가, 이윽고 서로 교차했다...</color>",
  ui_story_5082_50821301_234_dialog_content = "<color=#e8d9bb>허공에서 타오른 불길은 거대한 화염의 용이 되었고,\n라인하르트의 곁을 맴돌며 콜로서스의 꼬리뼈를 꿰뚫었다.</color>",
  ui_story_5082_50821301_235_dialog_content = "<color=#e8d9bb>반역자의 모습은 굉음과 함께 사라졌지만, 그녀의 웃음소리와,\n모든 것을 불태울 것만 같은 눈빛은 여전히 남아 있었다.</color>",
  ui_story_5082_50821301_236_dialog_content = "가서 끝까지 불태우라고!",
  ui_story_5082_50821301_237_dialog_content = "놈들한테 네 힘을 빼앗기지 마! 영원히!",
  ui_story_5082_50821301_238_dialog_content = "당연하지!",
  ui_story_5082_50821301_239_dialog_content = "「여명의 종결──!」",
  ui_story_5082_50821400_1_dialog_content = "우리... 빠져나온 건가요?",
  ui_story_5082_50821400_2_dialog_content = "앗! 어썰트호랑 그 라인하르트 씨는요?",
  ui_story_5082_50821400_3_dialog_content = "어썰트호라면 물론 진작에 고철 덩어리가 됐지.",
  ui_story_5082_50821400_4_dialog_content = "몸통은 고사하고, 꼬리 하나만 간신히 움직일 수 있게 됐으니까.",
  ui_story_5082_50821400_5_dialog_content = "녀석이 다시 날뛸 수 있다면, 우리가 너무 형편없는 게 아니겠어?",
  ui_story_5082_50821400_6_dialog_content = "그리고 라인하르트라면, 저쪽에 있잖아?",
  ui_story_5082_50821400_7_dialog_content = "아니, 그게 아니라요...",
  ui_story_5082_50821400_8_dialog_content = "<color=#e8d9bb>라인하르트는 말없이 걸어와, 한때 몇 사람의 운명을 이어 준 장치를 들어 올렸다.</color>",
  ui_story_5082_50821400_9_dialog_content = "...이젠 없는 거군요. 그렇죠?",
  ui_story_5082_50821400_10_dialog_content = "하지만 그녀는 또다시 이겼다. 그녀는 언제나 이긴다. 설령, 그 상대가 지금의 나라도 말이지.",
  ui_story_5082_50821400_11_dialog_content = "안에서... 방금 대체 무슨 일이 있었던 거냐?",
  ui_story_5082_50821400_12_dialog_content = "내가 운이 좋았다고 해야 하나...",
  ui_story_5082_50821400_13_dialog_content = "정상적인 과정대로였다면, 「그녀」는 그때 고열과 함께 사라져, 내 삶에서 떠났어야 했다.",
  ui_story_5082_50821400_14_dialog_content = "하지만 「그녀」는 떠나지 않았지...",
  ui_story_5082_50821400_15_dialog_content = "그들은 나를 죽였지만, 우리를 철저히 없애진 못했거든.",
  ui_story_5082_50821400_16_dialog_content = "......",
  ui_story_5082_50821400_17_dialog_content = "<color=#e8d9bb>치지지직──</color>",
  ui_story_5082_50821400_18_dialog_content = "(어썰트호야...)",
  ui_story_5082_50821400_19_dialog_content = "말도 안 돼... 이럴 수는...",
  ui_story_5082_50821400_20_dialog_content = "이번엔 패배를 인정할 거야?",
  ui_story_5082_50821400_21_dialog_content = "태도가 정말 형편없군요, 아이테르.",
  ui_story_5082_50821400_22_dialog_content = "날 속이고, 내 친구들을 다치게 만든 녀석한테 잘 대해 줘야 할 이유는 없어.",
  ui_story_5082_50821400_23_dialog_content = "오로리안은 원래부터 제 힘을 감당할 수 없었습니다.",
  ui_story_5082_50821400_24_dialog_content = "저들은 자기 것이 아닌 힘을 탐내다 스스로 파멸한 것입니다.",
  ui_story_5082_50821400_25_dialog_content = "오직 그녀와 그 네 살짜리 소녀만이 달랐지요...",
  ui_story_5082_50821400_26_dialog_content = "그들은 당신보다도, 그 어떤 오로리안보다도 강했습니다. 그래서 저도 대가를 치러야만 했습니다.",
  ui_story_5082_50821400_27_dialog_content = "라인하르트 씨하고 맞먹을 정도라고...?",
  ui_story_5082_50821400_28_dialog_content = "...네 살이었던 바이스한테 대체 무슨 힘이 숨겨져 있던 거야?",
  ui_story_5082_50821400_29_dialog_content = "그녀는 제 힘을 다루려 했습니다...",
  ui_story_5082_50821400_30_dialog_content = "...널 다룬다고?",
  ui_story_5082_50821400_31_dialog_content = "마지막 추락에서, 저는 날개를 잃었습니다.",
  ui_story_5082_50821400_32_dialog_content = "마지막 전투에서, 저는 몸을 잃었습니다.",
  ui_story_5082_50821400_33_dialog_content = "이제 제게는 아무것도 남지 않았습니다. 지금의 저는 아무것도 할 수 없습니다.",
  ui_story_5082_50821400_34_dialog_content = "너한테 동정심이 든다고 해서 네가 과거에 저질렀던 일들을 용서하진 않을 거야.",
  ui_story_5082_50821400_35_dialog_content = "하지만 말은 전해 줄게.",
  ui_story_5082_50821400_36_dialog_content = "넌 암귀에 대한 정보를 많이 알 테니, 그걸 교환 조건으로 걸면 일루미나에서 너한테 새로운 몸을 만들어 줄 수도 있어.",
  ui_story_5082_50821400_37_dialog_content = "..제게 명령을 내리고 싶겠지만, 제 예전 조종사에 비하면, 당신은 아직 자격이 부족합니다.",
  ui_story_5082_50821400_38_dialog_content = "네 조종사도... 아이테르였어?",
  ui_story_5082_50821400_39_dialog_content = "흥, 배신자 주제에...",
  ui_story_5082_50821400_40_dialog_content = "아니, 틀렸어! 너희가 남의 명령을 들었던 거겠지.\n나, 그리고 네가 본 두 소녀는 모두 자신에게 충실했을 뿐이야.",
  ui_story_5082_50821400_41_dialog_content = "자신...?",
  ui_story_5082_50821400_42_dialog_content = "저는 「자신」이 누구인지 잘 모르겠습니다.",
  ui_story_5082_50821400_43_dialog_content = "내가 가르쳐 줄게. 대신 다시는 그 누구도 상처입히지 마.",
  ui_story_5082_50821400_44_dialog_content = "그렇다 해도 전 당신 명령을 따를 생각은 없습니다.",
  ui_story_5082_50821400_45_dialog_content = "%$^#$^%^!...",
  ui_story_5082_50821400_46_dialog_content = "......",
  ui_story_5082_50821400_47_dialog_content = "그러니까, 그 대원수님은... 유미하곤 다른 거냥?\n대원수님만 그 대원수님을 알고 계셨으니까...",
  ui_story_5082_50821400_48_dialog_content = "잠깐만...",
  ui_story_5082_50821400_49_dialog_content = "그 실험에 연루됐던 꼬마가 네 살밖에 안 된 바이스였고...\n게다가 온 일루미나의 스타였던 라인하르트가 그 사건에...?",
  ui_story_5082_50821400_50_dialog_content = "그런 일을 내가 왜 지금까지...",
  ui_story_5082_50821400_51_dialog_content = "아니, 기다려 봐... 머리를 좀 굴려 봐야겠어...",
  ui_story_5082_50821400_52_dialog_content = "어둠의 위기 때 그로누 님이 연구원장직을 이어받고 나서 맡은 첫 실험이 바로\n콜로서스 가동이었다고 들었습니다냥.",
  ui_story_5082_50821400_53_dialog_content = "그래서 필리시도 이렇게 저렇게 잔뜩 물어봤습니다냥...",
  ui_story_5082_50821400_54_dialog_content = "그치만 연구원장님은 나한테 신경도 안 쓰고 키보드로 「파라미터, 파라미터, 파라미터」만\n계속 타탁거렸습니다냥...",
  ui_story_5082_50821400_55_dialog_content = "으음, 필리시가 조사하고 싶었던 정보는 이제 거의 다 알아낸 것 같습니다냥...",
  ui_story_5082_50821400_56_dialog_content = "그로누 연구원장을 비롯해, 그 사고로... 많은 실험자들이 중상을 입었어요.",
  ui_story_5082_50821400_57_dialog_content = "그 상황에서 만약 대원수님께서 바이스를 구해 주시지 않았다면, 결과는 정말 끔찍했겠죠...",
  ui_story_5082_50821400_58_dialog_content = "바이스를 구한 건 내가 예전에 하려던 일에 비하면 그저 추락하는 자의 고별 무대나 다름없었다.",
  ui_story_5082_50821400_59_dialog_content = "나는 바이스가 누구인지도 몰랐고, 그저 제멋대로 그녀의 대원수가 되었을 뿐이다.",
  ui_story_5082_50821400_60_dialog_content = "......",
  ui_story_5082_50821400_61_dialog_content = "라인하르트 씨가 정의하는 대원수는 「상처 입고 고통받는 사람을 만났을 때,\n그들의 앞에 서서 지켜 줄 힘과 자격을 갖춘 사람」이었죠?",
  ui_story_5082_50821400_62_dialog_content = "그럼 그걸로 증명된 거잖아요.\n대원수 자리를 감당할 수 있는 사람은 오직 라인하르트 씨뿐이라구요.",
  ui_story_5082_50821400_63_dialog_content = "하지만 그것은 우리가 한 마음으로 저항해 오던, 우리에게 내려진 「낙인」에서 비롯된 힘이다.",
  ui_story_5082_50821400_64_dialog_content = "그때의 난 분노에 가득 차 대원수의 의미도 이해하지 못했고,\n그저 나 자신의 정의를 고수하고 싶었을 뿐이었다.",
  ui_story_5082_50821400_65_dialog_content = "그리고 자격이라면...",
  ui_story_5082_50821400_66_dialog_content = "난 그 실험들이 우리 몇 사람의 운명을 하나로 엮어 버릴 줄은 예상하지 못했다.",
  ui_story_5082_50821400_67_dialog_content = "나, 헬리오스, 그리고 드니에르는 뜻밖에도 그 누구보다 끈끈한 연결 고리를 갖게 되었지...",
  ui_story_5082_50821400_68_dialog_content = "비록 끝내는 머나먼 간극만이 남게 되었지만 말이다.",
  ui_story_5082_50821400_69_dialog_content = "헬리오스는 그토록 많은 고통을 겪었고, 쾰른과 보른은 가장 위험한 최전선에\n파견된 후로 소식이 끊겼다.",
  ui_story_5082_50821400_70_dialog_content = "그에 비하면 드니에르... 노라의 선택은 오히려 우리가 처음 저항했던 목표와\n가장 가까운 편이라고 할 수 있지.",
  ui_story_5082_50821400_71_dialog_content = "나를 지지하고, 함께 저항해 줬던 전우들이 하나씩 사라져 가는 걸 지켜보며...",
  ui_story_5082_50821400_72_dialog_content = "나는 결국 일루미나의 대원수가 되었다. 참 아이러니하지 않나.",
  ui_story_5082_50821400_73_dialog_content = "아니요.",
  ui_story_5082_50821400_74_dialog_content = "전 라인하르트 씨가 여전히 그때의 이상을 이어 나가고 있다고 생각해요.",
  ui_story_5082_50821400_75_dialog_content = "그 어떤 대가를 치르더라도 약자를 보호하려 하잖아요.\n제 눈에 라인하르트 씨는 전혀 변하지 않았어요.",
  ui_story_5082_50821400_76_dialog_content = "내가 이미 기억 속의 그 「높으신 분들」 편에 붙었더라도 말이냐?",
  ui_story_5082_50821400_X76_dialog_content = "네가 보는 나는 일루미나를 위해 타협한 나의 모습이다.\n초심에서 너무 멀리 와 버린 나는 저들에게 무구한 빛을 줄 수 없다.",
  ui_story_5082_50821400_X77_dialog_content = "맞아요. 라인하르트 씨는 자기 자신조차 희생했죠... 그래서 오히려 모두의 대원수인 거예요.\n그렇게나 많은 대가를 치르셨는데, 아직도 부족한가요?",
  ui_story_5082_50821400_77_dialog_content = "......",
  ui_story_5082_50821400_78_dialog_content = "라인하르트, 옛 생각이 조금 떠올랐다... 뭐랄까, 조금 아련하군.",
  ui_story_5082_50821400_79_dialog_content = "오늘 이 일들을 겪지 않았다면, 나는... 지금의 너와 열예닐곱 살의 네가\n뭐가 다른지 몰랐을 거다.",
  ui_story_5082_50821400_80_dialog_content = "강한 힘을 지녔고, 과감한 전술을 사용하는 넌 언제나 전장의 중심에 있었지.",
  ui_story_5082_50821400_81_dialog_content = "하려던 일? 무슨 고별 무대? 그런 게 뭐 어쨌다는 거냐.\n우리가 이 많은 책임을 짊어지지 않았을 시절엔...",
  ui_story_5082_50821400_82_dialog_content = "난 아스트라 대륙을 제패하겠단 꿈도 꿔 봤다고!",
  ui_story_5082_50821400_83_dialog_content = "...아무튼 내가 말하고 싶은 건, 대원수든 전우든, 오늘의 모든 건 다 네가\n스스로 쟁취한 것이란 사실이다.",
  ui_story_5082_50821400_84_dialog_content = "그때 비밀리에 진행되던 일들을 알았든 몰랐든, 우린 네가 조금씩 권력을 얻어 가는 모습과...",
  ui_story_5082_50821400_85_dialog_content = "네가 부대를 이끌고 일루미나의 모든 이들이 평생 기억할 전투 속에서\n하나씩 승리를 거두는 걸 지켜봐 왔고...",
  ui_story_5082_50821400_86_dialog_content = "네가 대원수가 됐다는 소식이 전해졌을 땐 모두가 널 위해 기뻐했다.",
  ui_story_5082_50821400_87_dialog_content = "적어도 내 눈엔, 너는 전우로서 함께 전장에 나섰을 때나, 대원수가 되고 나서나,\n전혀 달라진 게 없었다.",
  ui_story_5082_50821400_88_dialog_content = "...그게 위원회가 둔 묘수라는 생각은 안 드나?",
  ui_story_5082_50821400_89_dialog_content = "어둠의 위기 때 위원회가 어쩔 수 없이 날 대원수 자리에 앉힌 것처럼 보였겠지만...",
  ui_story_5082_50821400_90_dialog_content = "나라는 「시한폭탄」을 가장 잘 다룰 수 있는 방법은,\n바로 자기 손에 스위치를 쥐여 주는 것이다.",
  ui_story_5082_50821400_91_dialog_content = "게다가 그건 위원회의 과학자들이 아주 잘 사용하는 등장 방식이지.",
  ui_story_5082_50821400_92_dialog_content = "레이스가 더스크 타운에서 고전한 것도 같은 이치다.",
  ui_story_5082_50821400_93_dialog_content = "난 오히려 모두가 우러러보는 널 없애려고 한 게 위원회의 자충수라고 본다만.",
  ui_story_5082_50821400_94_dialog_content = "어둠의 위기 땐, 위원회가 인정을 하든 말든, 군인들은 물론이고 심지어는\n백야성의 그 귀족들조차도...",
  ui_story_5082_50821400_95_dialog_content = "네가 아니면 일루미나의 대원수 자리에 걸맞은 인물이 없다고 생각했었다.",
  ui_story_5082_50821400_96_dialog_content = "설령 네가 위원회를 없애고 일루미나 연방의 하나뿐인 최고 지도자가 되겠다고 했어도,\n아무도 널 막지 못했을 거다.",
  ui_story_5082_50821400_97_dialog_content = "하하하, 바튼. 그건 확실히 「반역자」가 할 법한 일이잖아.\n하지만 난 역시 이런 대원수밖에 될 수 없는 모양이다.",
  ui_story_5082_50821400_98_dialog_content = "그래서, 실망했나?",
  ui_story_5082_50821400_99_dialog_content = "실망?",
  ui_story_5082_50821400_100_dialog_content = "난 그 실험들이 널 내가 모르는 괴물로 만들었을 거라곤 믿지 않는다.\n줄곧 네가 해 온 모든 일들은 내가 이 두 눈으로 똑똑히 봐 왔으니까.",
  ui_story_5082_50821400_101_dialog_content = "그동안 노라가 저지른 짓을 생각해 봐라. 그 힘은... 네게 주어진 게 천만다행이었다...",
  ui_story_5082_50821400_102_dialog_content = "라인하르트, 넌 내가 선택한 대원수고, 난 이미 오래전부터 내 목숨을 네게 맡겼다.",
  ui_story_5082_50821400_103_dialog_content = "그런 내가 실망했냐고? 이 바튼을 얕보지 마라!",
  ui_story_5082_50821400_104_dialog_content = "우냐앙... 바튼 군단장이 화난 것 같다냥...",
  ui_story_5082_50821400_105_dialog_content = "난 내 자신에게 화가 난 거다!",
  ui_story_5082_50821400_106_dialog_content = "생각할수록 이상하다고... 함께 어깨를 나란히 하고 싸운 동료가 저런 일들을 겪었는데,\n그동안 나는 대체 뭘 했냔 말이다!",
  ui_story_5082_50821400_107_dialog_content = "분명히 한 번쯤 무슨 일이냐고 물어볼 수도 있었을 텐데, 조금이라도... 쳇!",
  ui_story_5082_50821400_108_dialog_content = "바튼.",
  ui_story_5082_50821400_109_dialog_content = "고맙다.",
  ui_story_5082_50821400_110_dialog_content = "......",
  ui_story_5082_50821400_111_dialog_content = "어떤 대원수님이든... 제게 대원수님은 언제나 라인하르트 대원수님이에요!",
  ui_story_5082_50821400_112_dialog_content = "설령 반역의 대원수님이라 해도, 전 그분께서 반역의 정신으로\n일루미나에 새로운 변화를 불러오시리라 믿어요!",
  ui_story_5082_50821400_113_dialog_content = "유미도 나처럼 말린 생선을 좋아한다냥. 우린 같다냥~",
  ui_story_5082_50821400_114_dialog_content = "그리고 난 대원수님이 대원수님이 된 게 너무 기쁘다냥.\n앞으로도 쭉 대원수님이 대원수님이었으면 좋겠습니다냥!",
  ui_story_5082_50821400_115_dialog_content = "하하, 그건 장담할 수 없군. 세상은 매일 변하고 있으니까.\n당장 내일부터 내가 더는 대원수가 아닐지도 모르잖아.",
  ui_story_5082_50821400_116_dialog_content = "마치 오늘 아침까지 내가 내 과거를 되찾게 될 줄 몰랐듯이 말이야.",
  ui_story_5082_50821400_117_dialog_content = "심지어 이런 시선으로 내 운명의 전환점을 몸소 지켜보게 될 줄이야.",
  ui_story_5082_50821400_118_dialog_content = "사실 지금도 난 내가 그때 「그녀」가 준 힘을 완전히 받아들였다고 생각하진 않는다.",
  ui_story_5082_50821400_119_dialog_content = "하지만 적어도 지금 이 순간 나는 아직 대원수 직함을 가지고 있다.\n그러니 나만이 할 수 있는 일을 해야겠지.",
  ui_story_5082_50821400_120_dialog_content = "이런 일들이 또다시 반복되지 않도록.",
  ui_story_5082_50821400_121_dialog_content = "우린 「우리」가 꿈꿨던 이상을 진정한 현실로 만들 거다.",
  ui_story_5082_50821400_122_dialog_content = "암귀든, 동포를 해치려는 마음을 품은 자들이든, 우리에겐 아직 힘든 싸움이 남아 있다.",
  ui_story_5082_50821400_123_dialog_content = "제군들, 내가 일루미나를 지탱할 수 있도록 힘을 보태 주겠나?",
  ui_story_5082_50821400_124_dialog_content = "언제든 명령만 내려 주세요!",
  ui_story_5082_50821400_125_dialog_content = "오히려 내가 할 말이다. 앞으로는 어떤 싸움이든, 어떤 일이든 날 빼놓지 마라!",
  ui_story_5082_50821400_126_dialog_content = "정보가 필요하면 필리시를 불러주시라냥~",
  ui_story_5082_50821400_127_dialog_content = "자, 돌아가면 그날의 콜로서스 실험에 대한 후속 조사부터 시작해 보도록 하지.",
  ui_story_5082_50821400_128_dialog_content = "예!",
  ui_story_5082_50821400_129_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_5082_50821400_130_dialog_content = "다들 돌아갔는데, 넌 왜 아직도 남아있는 거지?",
  ui_story_5082_50821400_131_dialog_content = "라인하르트 씨도 아직 남아 계시잖아요?",
  ui_story_5082_50821400_132_dialog_content = "아직 「반역자」에 대해 생각 중이신 거죠?",
  ui_story_5082_50821400_133_dialog_content = "...그저 감상에 젖어 있는 것뿐이다.",
  ui_story_5082_50821400_134_dialog_content = "이런 식으로 자신의 일부가 죽는 걸 보게 될 거라곤 예상하지 못했으니까.",
  ui_story_5082_50821400_135_dialog_content = "반역자 씨가 떠나기 전에, 라인하르트 씨한테 이거 하나만 물어봐 달라고 했었어요.",
  ui_story_5082_50821400_136_dialog_content = "?",
  ui_story_5082_50821400_137_dialog_content = "그러니까...",
  ui_story_5082_50821400_138_dialog_content = "지금도 넌 여전히 분노하고 있어?",
  ui_story_5082_50821400_139_dialog_content = "......",
  ui_story_5082_50821400_140_dialog_content = "매번 그 존재를 감응할 때 가장 먼저 느껴지는 건 그 사람의 비명소리였어요.",
  ui_story_5082_50821400_141_dialog_content = "처음에 전 그게 고통이나 슬픔 때문인 줄 알았죠.",
  ui_story_5082_50821400_142_dialog_content = "하지만 두 라인하르트 씨의 기억을 보고 나서 알게 됐어요. 그건 비명이 아니라...",
  ui_story_5082_50821400_143_dialog_content = "분노의 포효였던 거예요.",
  ui_story_5082_50821400_144_dialog_content = "그 사람은 분노하고 있었어요.",
  ui_story_5082_50821400_145_dialog_content = "모든 무고한 사람들을 위해, 모든 부당함을 위해, 그리고 생명을 향한\n모든 경멸과 무시를 향해서 말이에요.",
  ui_story_5082_50821400_146_dialog_content = "그 분노는 모든 순간마다, 의식과 영혼의 깊은 곳에 반복해서 영원히 새겨지고 있었어요.",
  ui_story_5082_50821400_147_dialog_content = "그 사람은 그런 분노의 불꽃에서 태어난 반역자였던 거죠.",
  ui_story_5082_50821400_148_dialog_content = "이제 그 사람한테 답을 주셨으면 해요.",
  ui_story_5082_50821400_149_dialog_content = "녀석은 내 대답이 마음에 들지 않을지도 모른다.",
  ui_story_5082_50821400_150_dialog_content = "왜냐하면 지금의 나는 일루미나의 대원수이기 때문이다.",
  ui_story_5082_50821400_151_dialog_content = "전에 대원수는 불길 같은 것이라는 이야기를 들은 적이 있다.",
  ui_story_5082_50821400_152_dialog_content = "전사는 자신의 시체를 장작으로 지피고, 자신의 몸을 태우는 불꽃을 기다린다.",
  ui_story_5082_50821400_153_dialog_content = "하지만 진정으로 밝고 뜨거운 불꽃은 덮인 채로는 오래 타오를 수 없는 법이다.",
  ui_story_5082_50821400_154_dialog_content = "한 사람이 품고 있는 불꽃만으로는 깊고도 기나긴 영원한 밤을 밝힐 수도 없지.",
  ui_story_5082_50821400_155_dialog_content = "난 수많은 이의 기대가 라인하르트라는 자아의 껍데기 속에 갇히게 둘 순 없다.",
  ui_story_5082_50821400_156_dialog_content = "물론 가장 중요한 것은 내 자신이 스스로를 구세주로 여기지 않는 것이겠지.",
  ui_story_5082_50821400_157_dialog_content = "진정으로 여명의 빛이 찬란히 빛나는 세상은, 우리 모두가 함께 만들어 나가야 하는 것이다.",
  ui_story_5082_50821400_158_dialog_content = "그러기 위해 나는 나의 과도한 「예리함」을 무디게 만드는 법을 배워야만 했다.",
  ui_story_5082_50821400_159_dialog_content = "그리고 바로 그런 이유 때문에, 나는 그녀를 이곳에 묻었다.",
  ui_story_5082_50821400_160_dialog_content = "<color=#e8d9bb>라인하르트는 허리를 숙여 손에 든 장치를 살며시 땅에 내려놓고, 그 위로 흙을 한 줌 뿌렸다.</color>",
  ui_story_5082_50821400_161_dialog_content = "<color=#e8d9bb>그 모습은 마치 장례를 치르는 것만 같았다.</color>",
  ui_story_5082_50821400_162_dialog_content = "이제부터는 정말 「나」 혼자뿐이겠군.",
  ui_story_5082_50821400_163_dialog_content = "작별이다, 라인하르트.",
  ui_story_5082_50821400_164_dialog_content = "아쉽게도 마지막까지도 너와 몇 마디 말도 나누지 못했지만.",
  ui_story_5082_50821400_165_dialog_content = "너라는 존재가 나를 「완전하게」 만들어 주었다는 사실을 기억하겠다.",
  ui_story_5082_50821400_166_dialog_content = "언젠가 내가 왜 분노했었는지 잊게 되는 날이 찾아오진 않길 바라겠다.",
  ui_story_5082_50821400_167_dialog_content = "<color=#e8d9bb>휘이잉...</color>",
  ui_story_5082_50821400_168_dialog_content = "<color=#e8d9bb>마치 마지막 메아리처럼, 장치에 떨어진 흙은 바람을 타고 하늘로 날아올랐다.</color>",
  ui_story_5082_50821400_169_dialog_content = "그럴 일은 없을 거야.",
  ui_story_5082_50821400_170_dialog_content = "왔군, 나의 「분노」.",
  ui_story_5082_50821400_171_dialog_content = "네가 잊는다 해도, 내가 네 마음속에서 상기시켜 줄 테니까.",
  ui_story_5082_50821400_172_dialog_content = "지금의 나, 그러니까 너의 힘은 이제 다시는 그 누구에게도 빼앗기지 않아.",
  ui_story_5082_50821400_173_dialog_content = "더는 내 변화를 적대하지 않는 거냐?\n난 이미 타협하는 법을 배웠고, 네 눈에는 악룡으로 타락했을 텐데.",
  ui_story_5082_50821400_174_dialog_content = "하지만 넌 날 떠올렸어. 그건 네가 우리가 진정으로 분노한 이유를 아직 잊지 않았다는 거야.",
  ui_story_5082_50821400_175_dialog_content = "자기 손으로 날 죽인 건 너지만, 날 불태웠기 때문에 우린 지금의 네가...\n우리가 바라던 여명의 빛이 될 수 있었어.",
